-- Trigonometry
insert into public.packs (id, category_id, title, course, description, position) values
  ('trig-unit-circle', 'trigonometry', 'Unit Circle & Radians', 'Precalculus', 'Degree-radian conversion, arc length and sector area, exact values at special angles, ASTC signs, and reference and coterminal angles.', 0),
  ('trig-identities', 'trigonometry', 'Trig Identities', 'Precalculus', 'Reciprocal, Pythagorean, even/odd and cofunction identities; sum, difference, double- and half-angle formulas; product-to-sum; proof strategy.', 1),
  ('trig-triangles', 'trigonometry', 'Triangles & Inverse Trig', 'Precalculus', 'SOH-CAH-TOA, special right triangles, laws of sines and cosines, the SSA ambiguous case, area and Heron''s formula, inverse trig ranges.', 2),
  ('trig-graphs', 'trigonometry', 'Trig Graphs & Equations', 'Precalculus', 'Amplitude, period, phase shift and midline of y = A sin(Bx − C) + D, tangent asymptotes, csc range, symmetry, and solving trig equations.', 3)
on conflict (id) do update set category_id = excluded.category_id, title = excluded.title, course = excluded.course, description = excluded.description, position = excluded.position;

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('trig-unit-circle/radian-definition', 'trig-unit-circle', 0, 'What is one radian, and about how many degrees is it?', 'The central angle whose intercepted arc is exactly one radius long.
The circumference 2πr is 2π radii, so 360° = 2π rad and 1 rad = 180°/π ≈ 57.3°.', null, '{}'::text[]),
  ('trig-unit-circle/degrees-to-radians', 'trig-unit-circle', 1, 'Convert 210° to radians (exact form).', '7π/6.
Multiply degrees by π/180: 210 · π/180 = 7π/6. Check: 30° = π/6, and 210° = 7 · 30°.', '7pi/6', array['(7pi)/6', '7/6pi', '(7/6)pi']::text[]),
  ('trig-unit-circle/radians-to-degrees', 'trig-unit-circle', 2, 'Convert 5π/3 radians to degrees.', '300°.
Multiply radians by 180/π: (5π/3)(180/π) = 5 · 60 = 300°. Shortcut: π/3 = 60°, so 5π/3 = 5 · 60°.', '300', array['300 degrees', '300 degree', '300°', '300 deg']::text[]),
  ('trig-unit-circle/arc-length', 'trig-unit-circle', 3, 'Exact length of the arc cut off by a central angle of 2π/3 on a circle of radius 6 cm?', '4π cm (≈ 12.57 cm).
s = rθ with θ in radians: 6 · 2π/3 = 4π. Trap: plugging in degrees (120) gives 720, which is nonsense; convert to radians first.', '4pi', array['4pi cm', '4pi centimeters']::text[]),
  ('trig-unit-circle/sector-area', 'trig-unit-circle', 4, 'Exact area of a sector with radius 4 and central angle π/4?', '2π square units.
A = ½r²θ with θ in radians: ½ · 16 · π/4 = 2π. Check: π/4 is 1/8 of a full turn, and 1/8 of πr² = 16π/8 = 2π.', '2pi', array['2pi square units']::text[]),
  ('trig-unit-circle/unit-circle-coordinates', 'trig-unit-circle', 5, 'If the terminal side of θ meets the unit circle at (x, y), what are cos θ, sin θ, and tan θ?', 'cos θ = x, sin θ = y, tan θ = y/x (when x ≠ 0).
So every point on the unit circle is (cos θ, sin θ). Example: θ = π lands at (−1, 0), so cos π = −1, sin π = 0, tan π = 0.', null, '{}'::text[]),
  ('trig-unit-circle/special-angle-pattern', 'trig-unit-circle', 6, 'What pattern gives sin θ at θ = 0, π/6, π/4, π/3, π/2, and how do the cosines relate?', 'sin θ = √0/2, √1/2, √2/2, √3/2, √4/2, i.e. 0, 1/2, √2/2, √3/2, 1.
Cosine runs the same list backward, from cos 0 = 1 down to cos(π/2) = 0. So cos(π/6) = √3/2 and cos(π/3) = 1/2.', null, '{}'::text[]),
  ('trig-unit-circle/tan-pi-over-3', 'trig-unit-circle', 7, 'Exact value of tan(π/3)?', '√3.
tan = sin/cos = (√3/2)/(1/2) = √3. Don''t swap it with tan(π/6) = 1/√3 = √3/3: tan θ is the slope of the terminal side, and the 60° line is the steeper one.', 'sqrt(3)', array['sqrt3']::text[]),
  ('trig-unit-circle/tan-undefined', 'trig-unit-circle', 8, 'For which angles θ is tan θ undefined? Give the general form and the angles in [0, 2π).', 'θ = π/2 + kπ for any integer k; in [0, 2π) that''s π/2 and 3π/2.
tan θ = sin θ/cos θ, and cos θ = 0 there (x = 0 on the unit circle). sec θ is undefined at the same angles.', null, '{}'::text[]),
  ('trig-unit-circle/astc-quadrant-signs', 'trig-unit-circle', 9, 'Which trig functions are positive in each of the four quadrants?', 'QI: all six. QII: sin and csc. QIII: tan and cot. QIV: cos and sec.
Mnemonic ASTC, ''All Students Take Calculus'', counterclockwise from QI. It follows from x = cos θ, y = sin θ, and tan θ = y/x.', null, '{}'::text[]),
  ('trig-unit-circle/coterminal-angle', 'trig-unit-circle', 10, 'Which angle in [0, 2π) is coterminal with −7π/6?', '5π/6.
Coterminal angles differ by multiples of 2π. Add 2π = 12π/6: −7π/6 + 12π/6 = 5π/6. For a large angle like 17π/4, subtract 2π until it lands in [0, 2π): 17π/4 − 4π = π/4.', '5pi/6', array['(5pi)/6', '5/6pi', '(5/6)pi']::text[]),
  ('trig-unit-circle/reference-angle', 'trig-unit-circle', 11, 'What is the reference angle of θ = 7π/5, in radians?', '2π/5.
The reference angle is the acute angle between the terminal side and the x-axis. 7π/5 (252°) lies between π and 3π/2, so it''s in QIII: subtract π to get 7π/5 − π = 2π/5 (72°). In QII use π − θ; in QIV use 2π − θ.', '2pi/5', array['(2pi)/5', '2/5pi', '(2/5)pi']::text[]),
  ('trig-unit-circle/point-at-2pi-over-3', 'trig-unit-circle', 12, 'At what exact point does the terminal side of θ = 2π/3 meet the unit circle?', '(−1/2, √3/2).
2π/3 is in QII with reference angle π/3. Cosine (x) is negative there and sine (y) is positive: (−cos(π/3), sin(π/3)) = (−1/2, √3/2).', null, '{}'::text[]),
  ('trig-unit-circle/cos-5pi-over-4', 'trig-unit-circle', 13, 'Exact value of cos(5π/4)?', '−√2/2.
5π/4 = π + π/4 is in QIII with reference angle π/4. Cosine (the x-coordinate) is negative in QIII, so cos(5π/4) = −cos(π/4) = −√2/2.', '-sqrt(2)/2', array['-sqrt2/2', '-1/sqrt(2)', '-1/sqrt2', '-(sqrt(2)/2)', '-(sqrt2)/2']::text[]),
  ('trig-unit-circle/sin-7pi-over-6', 'trig-unit-circle', 14, 'Exact value of sin(7π/6)?', '−1/2.
7π/6 = π + π/6 is in QIII with reference angle π/6. Sine (the y-coordinate) is negative in QIII, so sin(7π/6) = −sin(π/6) = −1/2.', '-1/2', array['-0.5', '-.5']::text[]),
  ('trig-unit-circle/tan-11pi-over-6', 'trig-unit-circle', 15, 'Exact value of tan(11π/6)?', '−√3/3, equivalently −1/√3.
11π/6 = 2π − π/6 is in QIV with reference angle π/6. tan = y/x is negative in QIV, so tan(11π/6) = −tan(π/6) = −√3/3.', '-sqrt(3)/3', array['-sqrt3/3', '-1/sqrt(3)', '-1/sqrt3', '-(sqrt(3)/3)', '-(sqrt3)/3']::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'trig-unit-circle' and id not in ('trig-unit-circle/radian-definition', 'trig-unit-circle/degrees-to-radians', 'trig-unit-circle/radians-to-degrees', 'trig-unit-circle/arc-length', 'trig-unit-circle/sector-area', 'trig-unit-circle/unit-circle-coordinates', 'trig-unit-circle/special-angle-pattern', 'trig-unit-circle/tan-pi-over-3', 'trig-unit-circle/tan-undefined', 'trig-unit-circle/astc-quadrant-signs', 'trig-unit-circle/coterminal-angle', 'trig-unit-circle/reference-angle', 'trig-unit-circle/point-at-2pi-over-3', 'trig-unit-circle/cos-5pi-over-4', 'trig-unit-circle/sin-7pi-over-6', 'trig-unit-circle/tan-11pi-over-6');

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('trig-identities/reciprocal-secant', 'trig-identities', 0, 'sec θ is the reciprocal of which trig function?', 'Cosine: sec θ = 1/cos θ.
Likewise csc θ = 1/sin θ and cot θ = 1/tan θ = cos θ/sin θ. Trap: sec is not 1/sin. Each reciprocal pair has exactly one ''co'': cos–sec, sin–csc, tan–cot.', 'cosine', array['cos', 'cos theta', 'cos(theta)', 'cos x', 'cosine function']::text[]),
  ('trig-identities/pythagorean-cot-csc', 'trig-identities', 1, 'Complete the Pythagorean identity: 1 + cot²θ = ?', 'csc²θ.
Divide sin²θ + cos²θ = 1 through by sin²θ to get 1 + cot²θ = csc²θ. Dividing by cos²θ instead gives tan²θ + 1 = sec²θ. Pairs: tan goes with sec, cot goes with csc.', 'csc^2 theta', array['csc^2(theta)', 'csc^2', '(csc theta)^2', '(csc(theta))^2', '1/sin^2 theta', '1/sin^2(theta)']::text[]),
  ('trig-identities/pythagorean-find-cosine', 'trig-identities', 2, 'If sin θ = 3/5 and θ is in Quadrant II, what is cos θ?', '−4/5.
cos²θ = 1 − sin²θ = 1 − 9/25 = 16/25, so cos θ = ±4/5. Cosine is negative in QII, so cos θ = −4/5. The identity gives the size; the quadrant picks the sign.', '-4/5', array['-0.8', '-.8']::text[]),
  ('trig-identities/even-odd-simplify', 'trig-identities', 3, 'Use even/odd identities to simplify sin(−θ) · sec(−θ).', '−tan θ.
sin is odd, so sin(−θ) = −sin θ; sec is even, so sec(−θ) = sec θ. The product is −sin θ · (1/cos θ) = −tan θ. Only cos and sec are even; sin, csc, tan, and cot are odd, since −θ flips the y-coordinate.', '-tan theta', array['-tan(theta)', '-tan', '-(tan theta)', '-sin theta/cos theta', '-sin(theta)/cos(theta)']::text[]),
  ('trig-identities/cofunction-tangent', 'trig-identities', 4, 'Cofunction identity: tan(π/2 − θ) = ?', 'cot θ.
Cofunctions of complementary angles are equal: sin(π/2 − θ) = cos θ, tan(π/2 − θ) = cot θ, sec(π/2 − θ) = csc θ. In a right triangle, the leg opposite one acute angle is adjacent to the other.', 'cot theta', array['cot(theta)', 'cot', 'cotangent', '1/tan theta', '1/tan(theta)']::text[]),
  ('trig-identities/proving-identities-strategy', 'trig-identities', 5, 'What is the standard strategy for proving a trig identity?', 'Transform one side, usually the more complicated one, step by step until it matches the other (or simplify each side separately to a common form).
Go-to moves: rewrite in sin and cos, combine fractions, factor, use Pythagorean identities, multiply by a conjugate such as 1 + sin θ. Never apply an operation across the equals sign; that assumes what you''re proving.', null, '{}'::text[]),
  ('trig-identities/sum-difference-sin-cos', 'trig-identities', 6, 'State the sum and difference formulas for sin(A ± B) and cos(A ± B).', 'sin(A ± B) = sin A cos B ± cos A sin B
cos(A ± B) = cos A cos B ∓ sin A sin B
Traps: cosine takes the opposite sign (∓), and sin(A + B) ≠ sin A + sin B.', null, '{}'::text[]),
  ('trig-identities/cos-15-degrees', 'trig-identities', 7, 'Use a difference formula to find the exact value of cos 15°.', '(√6 + √2)/4 ≈ 0.966.
cos(45° − 30°) = cos 45° cos 30° + sin 45° sin 30° = (√2/2)(√3/2) + (√2/2)(1/2) = (√6 + √2)/4. Note the + sign: cos(A − B) adds the sine product.', '(sqrt(6)+sqrt(2))/4', array['(sqrt6+sqrt2)/4', '(sqrt(2)+sqrt(6))/4', '(sqrt2+sqrt6)/4', 'sqrt(6)/4+sqrt(2)/4', 'sqrt(2+sqrt(3))/2', 'sqrt(2+sqrt3)/2']::text[]),
  ('trig-identities/tan-sum-difference', 'trig-identities', 8, 'State the sum and difference formulas for tan(A ± B).', 'tan(A ± B) = (tan A ± tan B)/(1 ∓ tan A tan B).
The numerator sign matches the operation; the denominator sign is the opposite. Example: tan 75° = tan(45° + 30°) = (1 + √3/3)/(1 − √3/3) = 2 + √3.', null, '{}'::text[]),
  ('trig-identities/sin-double-angle-value', 'trig-identities', 9, 'cos θ = −5/13 with θ in Quadrant III. Find the exact value of sin 2θ.', '120/169.
sin θ < 0 in QIII, so sin θ = −√(1 − 25/169) = −12/13. Then sin 2θ = 2 sin θ cos θ = 2(−12/13)(−5/13) = 120/169. Positive makes sense: 2θ lies between 2π and 3π.', '120/169', '{}'::text[]),
  ('trig-identities/cos-double-angle-forms', 'trig-identities', 10, 'Give all three forms of the double-angle formula for cos 2θ.', 'cos 2θ = cos²θ − sin²θ = 2cos²θ − 1 = 1 − 2sin²θ.
The last two come from substituting sin²θ + cos²θ = 1. Pick the form that uses what you know: only cos θ → 2cos²θ − 1; only sin θ → 1 − 2sin²θ.', null, '{}'::text[]),
  ('trig-identities/cos-double-angle-value', 'trig-identities', 11, 'If sin θ = 1/4, what is cos 2θ?', '7/8.
Use the sine-only form: cos 2θ = 1 − 2sin²θ = 1 − 2(1/16) = 1 − 1/8 = 7/8. No quadrant information is needed, because only sin²θ appears.', '7/8', array['0.875', '.875']::text[]),
  ('trig-identities/tan-double-angle', 'trig-identities', 12, 'State the double-angle formula for tan 2θ in terms of tan θ.', 'tan 2θ = 2 tan θ/(1 − tan²θ).
It''s the tan(A + B) formula with A = B = θ. Example: tan θ = 1/2 gives tan 2θ = 1/(1 − 1/4) = 4/3.', null, '{}'::text[]),
  ('trig-identities/power-reducing', 'trig-identities', 13, 'Power-reducing formulas: write sin²θ and cos²θ in terms of cos 2θ.', 'sin²θ = (1 − cos 2θ)/2
cos²θ = (1 + cos 2θ)/2
They''re the cos 2θ formulas solved for sin²θ and cos²θ. Hook: sine gets the minus. Replacing θ with θ/2 gives the half-angle formulas.', null, '{}'::text[]),
  ('trig-identities/half-angle-sign', 'trig-identities', 14, 'In sin(θ/2) = ±√((1 − cos θ)/2), what decides the ± sign?', 'The quadrant of θ/2, not the quadrant of θ.
Example: θ = 300° (QIV) gives θ/2 = 150° (QII), where sine is positive: sin 150° = +√((1 − 1/2)/2) = 1/2. Same rule for cos(θ/2) = ±√((1 + cos θ)/2).', null, '{}'::text[]),
  ('trig-identities/product-to-sum', 'trig-identities', 15, 'Product-to-sum: rewrite sin A cos B as a sum of sines.', 'sin A cos B = ½[sin(A + B) + sin(A − B)].
Check: add the expansions of sin(A + B) and sin(A − B); the cos A sin B terms cancel, leaving 2 sin A cos B.', null, '{}'::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'trig-identities' and id not in ('trig-identities/reciprocal-secant', 'trig-identities/pythagorean-cot-csc', 'trig-identities/pythagorean-find-cosine', 'trig-identities/even-odd-simplify', 'trig-identities/cofunction-tangent', 'trig-identities/proving-identities-strategy', 'trig-identities/sum-difference-sin-cos', 'trig-identities/cos-15-degrees', 'trig-identities/tan-sum-difference', 'trig-identities/sin-double-angle-value', 'trig-identities/cos-double-angle-forms', 'trig-identities/cos-double-angle-value', 'trig-identities/tan-double-angle', 'trig-identities/power-reducing', 'trig-identities/half-angle-sign', 'trig-identities/product-to-sum');

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('trig-triangles/sohcahtoa-sine', 'trig-triangles', 0, 'A right triangle has legs 5 and 12. What is sin θ for the angle θ opposite the leg of length 5?', '5/13.
Hypotenuse = √(5² + 12²) = √169 = 13. SOH-CAH-TOA: sin = opposite/hypotenuse = 5/13, cos = adjacent/hypotenuse = 12/13, tan = opposite/adjacent = 5/12.', '5/13', '{}'::text[]),
  ('trig-triangles/special-right-triangles', 'trig-triangles', 1, 'What are the side ratios of a 45-45-90 triangle and a 30-60-90 triangle?', '45-45-90: 1 : 1 : √2, so hypotenuse = leg · √2.
30-60-90: 1 : √3 : 2, opposite the 30°, 60°, and 90° angles. The short leg is half the hypotenuse; the long leg is √3 times the short leg.', null, '{}'::text[]),
  ('trig-triangles/thirty-sixty-ninety-leg', 'trig-triangles', 2, 'A 30-60-90 triangle has hypotenuse 10. How long is the leg opposite the 60° angle?', '5√3 ≈ 8.66.
The short leg (opposite 30°) is half the hypotenuse, 5. The long leg (opposite 60°) is √3 times that: 5√3. Check: sin 60° = 5√3/10 = √3/2.', '5sqrt(3)', array['5sqrt3', 'sqrt(75)', 'sqrt75']::text[]),
  ('trig-triangles/angle-of-elevation', 'trig-triangles', 3, 'On level ground 50 m from a tower''s base, the angle of elevation to its top is 60°. Exact height of the tower?', '50√3 m ≈ 86.6 m.
tan 60° = height/50, so height = 50 tan 60° = 50√3. Elevation and depression angles are measured from the horizontal, never the vertical; looking down from the top, the angle of depression is also 60°.', '50sqrt(3)', array['50sqrt3', '50sqrt(3) m', '50sqrt3 m', '50sqrt(3) meters', '50sqrt3 meters']::text[]),
  ('trig-triangles/law-of-sines', 'trig-triangles', 4, 'State the law of sines and the given-part cases it solves.', 'a/sin A = b/sin B = c/sin C: each side over the sine of its opposite angle.
Use it for AAS, ASA, and SSA, since you need an angle paired with its opposite side (for ASA, get the third angle from A + B + C = 180° first). SSA can be ambiguous.', null, '{}'::text[]),
  ('trig-triangles/law-of-cosines', 'trig-triangles', 5, 'State the law of cosines and the given-part cases it solves.', 'c² = a² + b² − 2ab cos C, where C is the angle between sides a and b.
Use it for SAS (find the third side) and SSS (find an angle: cos C = (a² + b² − c²)/(2ab)). With C = 90°, cos C = 0 and it becomes the Pythagorean theorem.', null, '{}'::text[]),
  ('trig-triangles/law-of-cosines-angle', 'trig-triangles', 6, 'A triangle has sides 5, 7, and 8. Find the angle opposite the side of length 7, in degrees.', '60°.
Put the side opposite the unknown angle alone on the left: 7² = 5² + 8² − 2(5)(8) cos θ, so 49 = 89 − 80 cos θ, cos θ = 40/80 = 1/2, and θ = 60°.', '60', array['60 degrees', '60 degree', '60°', '60 deg']::text[]),
  ('trig-triangles/ssa-ambiguous-case', 'trig-triangles', 7, 'SSA with acute angle A, opposite side a, and adjacent side b: when do you get 0, 1, or 2 triangles?', 'Compare a with the height h = b sin A.
a < h: none. a = h: one right triangle. h < a < b: two triangles (the ambiguous case). a ≥ b: exactly one.
If A is obtuse: one triangle if a > b, otherwise none.', null, '{}'::text[]),
  ('trig-triangles/ssa-triangle-count', 'trig-triangles', 8, 'Given A = 30°, a = 6, and b = 10, how many triangles are possible?', '2.
h = b sin A = 10 · ½ = 5, and h < a < b (5 < 6 < 10). Law of sines: sin B = 10 sin 30°/6 = 5/6, so B ≈ 56.4° or B ≈ 123.6°. Both work, because 30° + 123.6° < 180°.', '2', array['two', '2 triangles', 'two triangles']::text[]),
  ('trig-triangles/area-sas', 'trig-triangles', 9, 'Area of a triangle with sides 8 and 5 and an included angle of 30°?', '10 square units.
Area = ½ab sin C, where C is the angle between sides a and b: ½ · 8 · 5 · sin 30° = 20 · ½ = 10. The angle must be the included one; if it isn''t, find the included angle first.', '10', array['10 square units']::text[]),
  ('trig-triangles/herons-formula', 'trig-triangles', 10, 'Use Heron''s formula: what is the area of a triangle with sides 5, 5, and 6?', '12.
Area = √(s(s − a)(s − b)(s − c)) with semiperimeter s = (a + b + c)/2 = 8: √(8 · 3 · 3 · 2) = √144 = 12. Check: the height to the base 6 is √(5² − 3²) = 4, and ½ · 6 · 4 = 12.', '12', array['12 square units']::text[]),
  ('trig-triangles/inverse-trig-domains', 'trig-triangles', 11, 'Why is arcsin(2) undefined, while arctan(2) exists?', 'arcsin and arccos accept only inputs in [−1, 1], because sine and cosine never output anything outside [−1, 1].
Tangent takes every real value, so arctan is defined for all real x (arctan 2 ≈ 1.107).', null, '{}'::text[]),
  ('trig-triangles/inverse-trig-ranges', 'trig-triangles', 12, 'What are the principal ranges of arcsin, arccos, and arctan?', 'arcsin: [−π/2, π/2]. arccos: [0, π]. arctan: (−π/2, π/2).
Each is an interval where the function is one-to-one and hits all its values. arctan''s endpoints are open because tan has vertical asymptotes at ±π/2.', null, '{}'::text[]),
  ('trig-triangles/arccos-negative-input', 'trig-triangles', 13, 'Exact value of arccos(−1/2), in radians?', '2π/3.
arccos returns angles in [0, π], so a negative input lands in QII: π − π/3 = 2π/3. Traps: 4π/3 has cosine −1/2 but lies outside [0, π], and −π/3 is wrong because arccos(−x) = π − arccos x, not −arccos x.', '2pi/3', array['(2pi)/3', '2/3pi', '(2/3)pi']::text[]),
  ('trig-triangles/arcsin-of-sin-trap', 'trig-triangles', 14, 'Exact value of arcsin(sin(5π/6))?', 'π/6.
sin(5π/6) = 1/2, and arcsin must return an angle in [−π/2, π/2], so arcsin(1/2) = π/6, not 5π/6. arcsin(sin x) = x only when x is already in [−π/2, π/2].', 'pi/6', '{}'::text[]),
  ('trig-triangles/tan-of-arcsin', 'trig-triangles', 15, 'Exact value of tan(arcsin(−3/5))?', '−3/4.
Let θ = arcsin(−3/5), so sin θ = −3/5 with θ between −π/2 and 0 (QIV). Cosine is positive there, cos θ = 4/5 (3-4-5 triangle), so tan θ = (−3/5)/(4/5) = −3/4.', '-3/4', array['-0.75', '-.75']::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'trig-triangles' and id not in ('trig-triangles/sohcahtoa-sine', 'trig-triangles/special-right-triangles', 'trig-triangles/thirty-sixty-ninety-leg', 'trig-triangles/angle-of-elevation', 'trig-triangles/law-of-sines', 'trig-triangles/law-of-cosines', 'trig-triangles/law-of-cosines-angle', 'trig-triangles/ssa-ambiguous-case', 'trig-triangles/ssa-triangle-count', 'trig-triangles/area-sas', 'trig-triangles/herons-formula', 'trig-triangles/inverse-trig-domains', 'trig-triangles/inverse-trig-ranges', 'trig-triangles/arccos-negative-input', 'trig-triangles/arcsin-of-sin-trap', 'trig-triangles/tan-of-arcsin');

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('trig-graphs/sinusoid-parameters', 'trig-graphs', 0, 'For y = A sin(Bx − C) + D with B > 0, what are the amplitude, period, phase shift, and midline?', 'Amplitude |A|, period 2π/B, phase shift C/B (to the right if positive), midline y = D.
Factor out B to see the shift: A sin(B(x − C/B)) + D. Same rules for cosine. Trap: the shift is C/B, not C.', null, '{}'::text[]),
  ('trig-graphs/amplitude-negative-a', 'trig-graphs', 1, 'What is the amplitude of y = −3 sin(2x) + 1?', '3.
Amplitude = |A| = |−3| = 3. It''s a distance, so it''s never negative; the minus sign only reflects the graph across its midline, y = 1.', '3', '{}'::text[]),
  ('trig-graphs/period-cosine', 'trig-graphs', 2, 'What is the period of y = 4 cos(πx/3)?', '6.
Period = 2π/B with B = π/3: 2π ÷ (π/3) = 6. The 4 changes the amplitude, not the period.', '6', '{}'::text[]),
  ('trig-graphs/phase-shift', 'trig-graphs', 3, 'y = sin(2x − π/3) is the graph of y = sin(2x) shifted right by how much?', 'π/6.
Factor out B: sin(2x − π/3) = sin(2(x − π/6)). The phase shift is C/B = (π/3)/2 = π/6. Trap: answering π/3 forgets to divide by B.', 'pi/6', array['pi/6 to the right', 'pi/6 right']::text[]),
  ('trig-graphs/range-shifted-sine', 'trig-graphs', 4, 'What is the range of y = 2 sin x + 3?', '[1, 5].
sin x has range [−1, 1] (its domain is all reals), so 2 sin x runs over [−2, 2], and adding 3 gives [1, 5]. Equivalently: midline y = 3, amplitude 2, so 3 ± 2.', '[1, 5]', array['1<=y<=5', '1≤y≤5', '1 to 5']::text[]),
  ('trig-graphs/midline-from-max-min', 'trig-graphs', 5, 'A sinusoid has maximum value 9 and minimum value −1. What is its midline?', 'y = 4.
Midline = (max + min)/2 = (9 + (−1))/2 = 4. Amplitude = (max − min)/2 = 5, so the graph swings 5 units above and below y = 4.', 'y = 4', array['4']::text[]),
  ('trig-graphs/period-tangent', 'trig-graphs', 6, 'What is the period of y = tan(3x)?', 'π/3.
tan and cot have period π, not 2π, so y = tan(Bx) has period π/B = π/3. Only sin, cos, sec, and csc use 2π/B.', 'pi/3', '{}'::text[]),
  ('trig-graphs/tangent-asymptotes', 'trig-graphs', 7, 'Where are the vertical asymptotes of y = tan(2x)?', 'x = π/4 + kπ/2, k any integer.
tan u is undefined at u = π/2 + kπ, so solve 2x = π/2 + kπ. Consecutive asymptotes are one period (π/2) apart, and the graph rises from −∞ to ∞ between them.', null, '{}'::text[]),
  ('trig-graphs/cosecant-domain-range', 'trig-graphs', 8, 'What are the domain and range of y = csc x?', 'Domain: all real x except x = kπ (where sin x = 0). Range: (−∞, −1] ∪ [1, ∞).
Since |sin x| ≤ 1, |csc x| = 1/|sin x| ≥ 1. sec x has the same range; its domain excludes x = π/2 + kπ instead.', null, '{}'::text[]),
  ('trig-graphs/cosecant-symmetry', 'trig-graphs', 9, 'Is the graph of y = csc x symmetric about the y-axis or about the origin?', 'The origin.
csc is odd: csc(−x) = 1/sin(−x) = −csc x. Odd functions (sin, tan, cot, csc) have origin symmetry; the even ones (cos, sec) are symmetric about the y-axis.', 'origin', array['about the origin', 'symmetric about the origin', 'origin symmetry']::text[]),
  ('trig-graphs/general-solution-sine', 'trig-graphs', 10, 'What is the general solution of sin x = 1/2?', 'x = π/6 + 2kπ or x = 5π/6 + 2kπ, k any integer.
Sine is positive in QI and QII, so each period has two solutions with reference angle π/6. Trap: π/6 + kπ is wrong; it includes 7π/6, where sin = −1/2.', null, '{}'::text[]),
  ('trig-graphs/general-solution-tangent', 'trig-graphs', 11, 'What is the general solution of tan x = √3?', 'x = π/3 + kπ, k any integer.
tan has period π, so one family covers both solutions in each 2π: π/3 (QI) and 4π/3 (QIII). Writing π/3 + 2kπ would miss 4π/3.', null, '{}'::text[]),
  ('trig-graphs/solve-cosine-equation', 'trig-graphs', 12, 'Solve 2 cos x + √3 = 0 on [0, 2π).', 'x = 5π/6 and x = 7π/6.
cos x = −√3/2, so the reference angle is π/6. Cosine is negative in QII and QIII: π − π/6 = 5π/6 and π + π/6 = 7π/6.', null, '{}'::text[]),
  ('trig-graphs/count-solutions-sin-2x', 'trig-graphs', 13, 'How many solutions does sin(2x) = 1/2 have on [0, 2π)?', '4.
As x runs over [0, 2π), 2x runs over [0, 4π): two full periods, each with two solutions. 2x = π/6, 5π/6, 13π/6, 17π/6, so x = π/12, 5π/12, 13π/12, 17π/12.', '4', array['four']::text[]),
  ('trig-graphs/quadratic-trig-equation', 'trig-graphs', 14, 'Solve 2 sin²x − sin x − 1 = 0 on [0, 2π).', 'x = π/2, 7π/6, 11π/6.
Factor as a quadratic in sin x: (2 sin x + 1)(sin x − 1) = 0. sin x = 1 gives π/2; sin x = −1/2 gives 7π/6 and 11π/6 (QIII and QIV).', null, '{}'::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'trig-graphs' and id not in ('trig-graphs/sinusoid-parameters', 'trig-graphs/amplitude-negative-a', 'trig-graphs/period-cosine', 'trig-graphs/phase-shift', 'trig-graphs/range-shifted-sine', 'trig-graphs/midline-from-max-min', 'trig-graphs/period-tangent', 'trig-graphs/tangent-asymptotes', 'trig-graphs/cosecant-domain-range', 'trig-graphs/cosecant-symmetry', 'trig-graphs/general-solution-sine', 'trig-graphs/general-solution-tangent', 'trig-graphs/solve-cosine-equation', 'trig-graphs/count-solutions-sin-2x', 'trig-graphs/quadratic-trig-equation');

delete from public.packs where category_id = 'trigonometry' and id not in ('trig-unit-circle', 'trig-identities', 'trig-triangles', 'trig-graphs');

-- Biology
insert into public.packs (id, category_id, title, course, description, position) values
  ('bio-cell-structure', 'biology', 'Cell Structure & Membranes', 'Intro Biology', 'Organelle jobs, endosymbiosis evidence, the cytoskeleton, the fluid mosaic membrane, tonicity, passive vs active transport, the Na⁺/K⁺ pump and junctions.', 0),
  ('bio-cell-division', 'biology', 'Cell Cycle, Mitosis & Meiosis', 'Intro Biology', 'Cell-cycle phases, mitosis stages, chromosome counts, meiosis I vs II, crossing over, nondisjunction, checkpoints, MPF, p53 and oncogenes vs tumor suppressors.', 1),
  ('bio-molecular', 'biology', 'DNA, RNA & Protein Synthesis', 'Molecular Biology', 'Base pairing, Chargaff''s rules, replication enzymes, Okazaki fragments, telomerase, transcription, RNA processing, codons, ribosome sites, mutations, operons.', 2),
  ('bio-genetics', 'biology', 'Mendelian & Population Genetics', 'Genetics', 'Mendel''s laws, cross ratios and probability, testcrosses, dominance, ABO, epistasis, X-linkage, pedigrees, map units, Hardy–Weinberg math and drift.', 3),
  ('bio-metabolism', 'biology', 'Respiration & Photosynthesis', 'Intro Biology', 'Enzymes and inhibitors, glycolysis, the citric acid cycle, the ETC and chemiosmosis, ATP yield, fermentation, light reactions, the Calvin cycle, C4 and CAM.', 4),
  ('bio-evolution', 'biology', 'Evolution & Speciation', 'Intro Biology', 'Natural selection, fitness, modes of selection, sexual selection, gene flow, homology, species concepts, reproductive barriers, speciation and cladistics.', 5),
  ('bio-physiology', 'biology', 'Human Physiology', 'Anatomy & Physiology', 'Neuron signaling, muscle contraction, blood flow and the pacemaker, the nephron, ADH and aldosterone, glucose control, the Bohr effect, immunity and hormones.', 6)
on conflict (id) do update set category_id = excluded.category_id, title = excluded.title, course = excluded.course, description = excluded.description, position = excluded.position;

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('bio-cell-structure/prokaryote-nucleoid', 'bio-cell-structure', 0, 'In a prokaryotic cell, what is the region called where the DNA is concentrated without any membrane around it?', 'The nucleoid.
Prokaryotes (bacteria and archaea) have no nucleus and no membrane-bound organelles. Eukaryotes enclose their DNA in a nucleus bounded by the nuclear envelope, a double membrane perforated by pores.', 'nucleoid', array['nucleoid region', 'nucleoids']::text[]),
  ('bio-cell-structure/nucleolus-ribosome-subunits', 'bio-cell-structure', 1, 'Which dense, non-membrane-bound region inside the nucleus makes rRNA and assembles ribosomal subunits?', 'The nucleolus.
rRNA made there is combined with proteins imported from the cytoplasm into large and small subunits, which exit through nuclear pores. A large and a small subunit join into a working ribosome only in the cytoplasm.', 'nucleolus', array['nucleoli']::text[]),
  ('bio-cell-structure/free-vs-bound-ribosomes', 'bio-cell-structure', 2, 'Proteins headed for mitochondria, chloroplasts or the nucleus: are they made on free ribosomes or on ER-bound ribosomes?', 'Free ribosomes in the cytosol.
Free ribosomes make cytosolic proteins and proteins imported later into mitochondria, chloroplasts and the nucleus. ER-bound ribosomes make secreted proteins (e.g., insulin), membrane proteins, and proteins for the ER, Golgi and lysosomes. The ribosomes are identical; a signal peptide on the new protein sends a ribosome to the ER.', null, '{}'::text[]),
  ('bio-cell-structure/smooth-er-functions', 'bio-cell-structure', 3, 'Which organelle makes lipids such as steroid hormones, detoxifies drugs in liver cells, and stores Ca²⁺ in muscle cells?', 'Smooth ER (no ribosomes).
Drugs such as barbiturates and alcohol make liver cells build more smooth ER, which raises drug tolerance. In muscle, its release of Ca²⁺ triggers contraction. Rough ER, studded with ribosomes, makes secretory and membrane proteins instead.', 'smooth ER', array['smooth endoplasmic reticulum', 'SER']::text[]),
  ('bio-cell-structure/golgi-cis-face', 'bio-cell-structure', 4, 'Which face of the Golgi apparatus receives the transport vesicles arriving from the ER?', 'The cis face (the receiving side, near the ER).
Products are modified as they pass through the cisternae (e.g., glycoprotein carbohydrates trimmed and altered, phosphate ID tags added), then sorted into vesicles that leave from the trans face (the shipping side).', 'cis face', array['cis', 'cis side', 'cis-face', 'cis Golgi', 'cis region', 'cis face of the Golgi', 'cis-Golgi network', 'cis Golgi network', 'forming face']::text[]),
  ('bio-cell-structure/lysosome-function', 'bio-cell-structure', 5, 'In an animal cell, which membrane-bound sac of hydrolytic enzymes digests engulfed food and recycles worn-out organelles?', 'The lysosome.
Its enzymes work best at about pH 5, kept acidic by H⁺ pumps in its membrane; enzymes that leak out do little at the cytosol''s near-neutral pH. Recycling organelles is called autophagy. In Tay-Sachs disease a lipid-digesting lysosomal enzyme is missing, so lipids build up in brain cells.', 'lysosome', array['lysosomes']::text[]),
  ('bio-cell-structure/peroxisome-function', 'bio-cell-structure', 6, 'Which organelle transfers hydrogen from substrates to O₂, producing H₂O₂ that its own enzyme then converts to water?', 'The peroxisome.
These reactions break fatty acids into smaller molecules that mitochondria burn as fuel and, in liver cells, detoxify alcohol. The enzyme catalase turns the toxic H₂O₂ into H₂O. Glyoxysomes, specialized peroxisomes in fat-storing seeds, help convert fatty acids to sugar.', 'peroxisome', array['peroxisomes']::text[]),
  ('bio-cell-structure/endosymbiont-evidence', 'bio-cell-structure', 7, 'Give three lines of evidence that mitochondria and chloroplasts evolved from engulfed prokaryotes.', 'Any three: a double membrane; their own circular DNA without histones, like a bacterial chromosome; their own ribosomes, which resemble bacterial ribosomes (including antibiotic sensitivity); division by a process like binary fission; inner-membrane enzymes and transport systems like those of prokaryotes.
Mitochondria came from an alphaproteobacterium, chloroplasts from a cyanobacterium.', null, '{}'::text[]),
  ('bio-cell-structure/microtubules', 'bio-cell-structure', 8, 'Which cytoskeletal fibers resist compression, form the mitotic spindle, and make up the core of cilia and flagella?', 'Microtubules: hollow tubes of tubulin dimers, ≈25 nm wide, the thickest fibers.
In animal cells they grow out from the centrosome, and motor proteins carry vesicles along them. Motile cilia and flagella have a 9 + 2 pattern (nine doublets around two single microtubules), bent by dynein motors.', 'microtubules', array['microtubule']::text[]),
  ('bio-cell-structure/microfilaments', 'bio-cell-structure', 9, 'Which cytoskeletal fibers form the animal cleavage furrow and the core of microvilli, and work with myosin to contract muscle?', 'Microfilaments (actin filaments), ≈7 nm wide, the thinnest fibers.
They bear tension and power amoeboid movement and cytoplasmic streaming. Don''t confuse them with intermediate filaments (8–12 nm; e.g., keratins, nuclear lamins), the most permanent fibers, which anchor the nucleus and other organelles in place.', 'microfilaments', array['microfilament', 'actin filaments', 'actin filament']::text[]),
  ('bio-cell-structure/fluid-mosaic-model', 'bio-cell-structure', 10, 'In the fluid mosaic model of a cell membrane, what is ''fluid'' and what makes up the ''mosaic''?', 'Fluid: phospholipids (and many proteins) drift sideways within the bilayer, though flip-flopping across it is rare. Mosaic: many different proteins embedded in or attached to the bilayer.
Unsaturated, kinked fatty acid tails keep membranes fluid in the cold; in animal cells, cholesterol buffers fluidity against temperature changes.', null, '{}'::text[]),
  ('bio-cell-structure/tonicity-animal-vs-plant', 'bio-cell-structure', 11, 'What happens to an animal cell and to a plant cell placed in a hypotonic solution? In a hypertonic one?', 'Hypotonic (water moves in): the animal cell swells and may lyse; the plant cell becomes turgid, its healthy state, as the wall pushes back.
Hypertonic (water moves out): the animal cell shrivels; the plant cell plasmolyzes as its membrane pulls away from the wall.
In isotonic solution the animal cell is normal but the plant cell is flaccid (limp).', null, '{}'::text[]),
  ('bio-cell-structure/facilitated-diffusion', 'bio-cell-structure', 12, 'Glucose enters a red blood cell down its concentration gradient via a carrier protein, using no ATP. What kind of transport is this?', 'Facilitated diffusion, a form of passive transport.
Using a transport protein doesn''t make it active: the energy comes from the gradient itself. Active transport moves solutes against their gradient and needs energy, from ATP or from another solute''s gradient (cotransport).', 'facilitated diffusion', array['passive transport', 'passive', 'facilitated transport']::text[]),
  ('bio-cell-structure/sodium-potassium-pump', 'bio-cell-structure', 13, 'For each ATP it uses, how many Na⁺ and K⁺ ions does the sodium-potassium pump move, and in which directions?', '3 Na⁺ out and 2 K⁺ in, both against their concentration gradients (active transport).
ATP phosphorylates the pump, changing its shape. Because each cycle exports one net positive charge, it is an electrogenic pump that adds to the negative charge inside the cell.', null, '{}'::text[]),
  ('bio-cell-structure/receptor-mediated-endocytosis', 'bio-cell-structure', 14, 'Cells take in LDL particles bound to specific proteins clustered in coated pits, which pinch inward. What type of endocytosis is this?', 'Receptor-mediated endocytosis.
The coated pit forms a coated vesicle carrying the LDL inside. In familial hypercholesterolemia, defective or missing LDL receptors leave LDL in the blood, causing early atherosclerosis. Other endocytosis: phagocytosis (cell eating) and pinocytosis (cell drinking). Exocytosis does the reverse, secreting vesicle contents.', 'receptor-mediated endocytosis', array['receptor mediated endocytosis', 'receptor-mediated', 'receptor mediated', 'clathrin-mediated endocytosis', 'clathrin mediated endocytosis', 'clathrin-mediated']::text[]),
  ('bio-cell-structure/gap-junctions', 'bio-cell-structure', 15, 'Which animal cell junctions are protein-lined pores letting ions and small molecules pass straight between cells, as in heart muscle?', 'Gap junctions.
Plant cells use plasmodesmata, channels through their cell walls. Other animal junctions: tight junctions press membranes together into a seal that blocks leakage (e.g., between skin cells); desmosomes are rivets, anchored by intermediate filaments, that fasten cells into strong sheets.', 'gap junctions', array['gap junction', 'communicating junctions', 'communicating junction']::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'bio-cell-structure' and id not in ('bio-cell-structure/prokaryote-nucleoid', 'bio-cell-structure/nucleolus-ribosome-subunits', 'bio-cell-structure/free-vs-bound-ribosomes', 'bio-cell-structure/smooth-er-functions', 'bio-cell-structure/golgi-cis-face', 'bio-cell-structure/lysosome-function', 'bio-cell-structure/peroxisome-function', 'bio-cell-structure/endosymbiont-evidence', 'bio-cell-structure/microtubules', 'bio-cell-structure/microfilaments', 'bio-cell-structure/fluid-mosaic-model', 'bio-cell-structure/tonicity-animal-vs-plant', 'bio-cell-structure/facilitated-diffusion', 'bio-cell-structure/sodium-potassium-pump', 'bio-cell-structure/receptor-mediated-endocytosis', 'bio-cell-structure/gap-junctions');

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('bio-cell-division/s-phase-replication', 'bio-cell-division', 0, 'In which phase of the cell cycle is the DNA replicated?', 'S phase (synthesis).
Order: G1 → S → G2 → M. G1, S and G2 together make up interphase, often about 90% of the cycle, and the cell grows throughout it. The M phase is mitosis plus cytokinesis.', null, '{}'::text[]),
  ('bio-cell-division/g2-chromosome-count', 'bio-cell-division', 1, 'A human body cell has finished S phase and is now in G2. How many chromosomes does it contain?', '46, made up of 92 sister chromatids.
Replication doubles the DNA but not the chromosome number: each chromosome now has two sister chromatids joined at the centromere, so count centromeres. The count briefly doubles to 92 only in anaphase, when sisters separate.', '46', array['46 chromosomes', 'forty-six', 'forty six']::text[]),
  ('bio-cell-division/mitosis-stage-order', 'bio-cell-division', 2, 'List the five stages of mitosis in order.', 'Prophase → prometaphase → metaphase → anaphase → telophase.
Cytokinesis usually overlaps the end of telophase. Some texts fold prometaphase into prophase and list only four stages (PMAT).', null, '{}'::text[]),
  ('bio-cell-division/prometaphase', 'bio-cell-division', 3, 'In which stage of mitosis does the nuclear envelope fragment, letting spindle microtubules reach and attach to the chromosomes?', 'Prometaphase.
Each chromatid now has a kinetochore, and kinetochore microtubules start moving the chromosomes toward the cell''s midline. Four-stage schemes call this late prophase.', 'prometaphase', array['late prophase']::text[]),
  ('bio-cell-division/kinetochore', 'bio-cell-division', 4, 'What protein structure forms at the centromere of each sister chromatid and is where spindle microtubules attach?', 'The kinetochore.
Don''t mix up: centromere = the DNA region where sister chromatids are most tightly joined; centrosome = the microtubule-organizing center at each spindle pole (with a pair of centrioles in animal cells); kinetochore = the attachment site for spindle microtubules.', 'kinetochore', array['kinetochores']::text[]),
  ('bio-cell-division/cytokinesis-cell-plate', 'bio-cell-division', 5, 'During cytokinesis in a plant cell, what structure forms from fused Golgi-derived vesicles and develops into the new cell wall?', 'The cell plate.
A rigid wall means plant cells can''t pinch in two. Animal cells instead form a cleavage furrow: a contractile ring of actin microfilaments, interacting with myosin, tightens until the cell splits.', 'cell plate', array['cell plates']::text[]),
  ('bio-cell-division/meiosis-i-vs-ii', 'bio-cell-division', 6, 'Which meiotic division separates homologous chromosomes, and which separates sister chromatids?', 'Meiosis I separates homologs (the reductional division: diploid → haploid). Meiosis II separates sister chromatids, much like mitosis.
In humans, one 2n = 46 cell gives two cells with 23 duplicated chromosomes after meiosis I, then four haploid cells with 23 chromosomes each.', null, '{}'::text[]),
  ('bio-cell-division/crossing-over', 'bio-cell-division', 7, 'When during meiosis does crossing over occur, and between which chromatids?', 'Prophase I, between nonsister chromatids of a homologous pair held together in synapsis.
The X-shaped sites where it has happened are chiasmata. It creates recombinant chromosomes that combine maternal and paternal alleles.', null, '{}'::text[]),
  ('bio-cell-division/independent-assortment-combinations', 'bio-cell-division', 8, 'Independent orientation of homologous pairs at metaphase I alone allows how many chromosome combinations in human gametes?', '2²³, about 8.4 million (23 pairs, each able to line up 2 ways).
Random fertilization then allows about 70 trillion (2²³ × 2²³) zygote combinations, before crossing over adds even more variation.', null, '{}'::text[]),
  ('bio-cell-division/nondisjunction-outcomes', 'bio-cell-division', 9, 'If nondisjunction occurs in meiosis I vs meiosis II, what fraction of the resulting gametes is abnormal in each case?', 'Meiosis I: all four gametes are abnormal (two n + 1, two n − 1). Meiosis II: half are (one n + 1, one n − 1, two normal).
An n + 1 gamete fused with a normal one gives a trisomic zygote (2n + 1); an n − 1 gamete gives a monosomic one (2n − 1).', null, '{}'::text[]),
  ('bio-cell-division/down-syndrome-trisomy-21', 'bio-cell-division', 10, 'Down syndrome usually results from having three copies of which chromosome?', 'Chromosome 21 (trisomy 21), usually from nondisjunction; the risk rises with maternal age.
Sex-chromosome examples: XXY is Klinefelter syndrome (male); XO is Turner syndrome (female), the only known viable monosomy in humans.', '21', array['chromosome 21', 'trisomy 21', 'trisomy-21', 'chr 21']::text[]),
  ('bio-cell-division/g1-checkpoint', 'bio-cell-division', 11, 'Which checkpoint is the key ''go/no-go'' decision for many cells, after which the cell usually completes the whole cycle?', 'The G1 checkpoint (called the restriction point in mammalian cells).
Without a go-ahead signal such as a growth factor, the cell exits into G0, a nondividing state. Most body cells are in G0; mature nerve and muscle cells never divide, but liver cells can be called back into the cycle after injury.', 'G1 checkpoint', array['G1', 'restriction point', 'G1/S checkpoint', 'G1/S', 'G1 restriction point', 'G1 phase checkpoint']::text[]),
  ('bio-cell-division/spindle-checkpoint', 'bio-cell-division', 12, 'What must be true before the M-phase (spindle) checkpoint lets a cell begin anaphase?', 'Every chromosome must be attached to spindle microtubules at its kinetochores, with sister kinetochores attached to opposite poles, and aligned at the metaphase plate.
Any unattached kinetochore delays anaphase, which keeps daughter cells from getting missing or extra chromosomes.', null, '{}'::text[]),
  ('bio-cell-division/mpf-cyclin-cdk', 'bio-cell-division', 13, 'Which cyclin–Cdk complex, once enough accumulates in late G2, triggers the cell''s passage past the G2 checkpoint into M phase?', 'MPF (maturation-promoting factor, also called M-phase-promoting factor).
Cdk levels stay fairly constant; cyclin builds up during S and G2 and activates Cdk. During anaphase, MPF switches itself off by triggering the breakdown of its own cyclin.', 'MPF', array['maturation-promoting factor', 'maturation promoting factor', 'M-phase-promoting factor', 'M-phase promoting factor', 'M phase promoting factor', 'mitosis-promoting factor', 'mitosis promoting factor', 'cyclin B-Cdk1', 'Cdk1-cyclin B', 'cyclin B/Cdk1', 'Cdk1/cyclin B']::text[]),
  ('bio-cell-division/p53', 'bio-cell-division', 14, 'Which tumor-suppressor protein, nicknamed the ''guardian of the genome'', halts the cell cycle when DNA is damaged?', 'p53.
This transcription factor switches on p21 (which binds Cdks and stops the cycle), DNA-repair genes, and, if the damage can''t be fixed, genes that trigger apoptosis. The p53 gene is mutated in roughly half of all human cancers.', 'p53', array['TP53', 'p53 protein']::text[]),
  ('bio-cell-division/proto-oncogene-vs-tumor-suppressor', 'bio-cell-division', 15, 'Why is one mutated allele of a proto-oncogene enough to promote cancer, while tumor-suppressor genes usually need both alleles lost?', 'Proto-oncogene mutations are gain of function: one hyperactive allele (now an oncogene, e.g., ras) is enough, like a stuck accelerator. Tumor-suppressor mutations are loss of function: one working allele still makes enough protein, so both copies must be lost (e.g., p53, BRCA1), like failed brakes. Cancer usually needs several such mutations.', null, '{}'::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'bio-cell-division' and id not in ('bio-cell-division/s-phase-replication', 'bio-cell-division/g2-chromosome-count', 'bio-cell-division/mitosis-stage-order', 'bio-cell-division/prometaphase', 'bio-cell-division/kinetochore', 'bio-cell-division/cytokinesis-cell-plate', 'bio-cell-division/meiosis-i-vs-ii', 'bio-cell-division/crossing-over', 'bio-cell-division/independent-assortment-combinations', 'bio-cell-division/nondisjunction-outcomes', 'bio-cell-division/down-syndrome-trisomy-21', 'bio-cell-division/g1-checkpoint', 'bio-cell-division/spindle-checkpoint', 'bio-cell-division/mpf-cyclin-cdk', 'bio-cell-division/p53', 'bio-cell-division/proto-oncogene-vs-tumor-suppressor');

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('bio-molecular/gc-hydrogen-bonds', 'bio-molecular', 0, 'How many hydrogen bonds hold a G–C base pair together?', 'Three (A–T pairs have two), so GC-rich DNA needs more heat to separate.
Each pair joins a purine (A, G) with a pyrimidine (C, T; U in RNA), keeping the helix a uniform 2 nm wide. The two strands are antiparallel: they run 5′→3′ in opposite directions.', '3', array['three', '3 hydrogen bonds']::text[]),
  ('bio-molecular/chargaff-rules', 'bio-molecular', 1, 'A double-stranded DNA sample is 30% adenine. What percentage of its bases are guanine?', '20%.
Chargaff''s rules: A = T and G = C. If A = 30%, T = 30%, leaving 40% for G + C, so G = 20% and C = 20%. This works only for double-stranded DNA.', '20%', array['20', '20 percent', '0.2']::text[]),
  ('bio-molecular/meselson-stahl', 'bio-molecular', 2, 'Meselson and Stahl grew bacteria on ¹⁵N, then moved them to ¹⁴N. Their results supported which model of DNA replication?', 'Semiconservative: each new double helix has one parental strand and one newly made strand.
After one round in ¹⁴N, all the DNA formed a single hybrid band (ruling out conservative); after two rounds, hybrid and light bands (ruling out dispersive).', 'semiconservative', array['semi-conservative', 'semiconservative model', 'semiconservative replication', 'semi-conservative replication']::text[]),
  ('bio-molecular/topoisomerase', 'bio-molecular', 3, 'Which enzyme relieves the overwinding strain ahead of a replication fork by breaking, swiveling and rejoining DNA strands?', 'Topoisomerase.
Don''t confuse it with helicase, which untwists the double helix at the fork, separating the two strands. Single-strand binding proteins then keep the separated strands from re-pairing.', 'topoisomerase', array['topoisomerases', 'DNA topoisomerase', 'DNA gyrase', 'gyrase']::text[]),
  ('bio-molecular/primase', 'bio-molecular', 4, 'DNA polymerase can''t start a new strand from scratch. Which enzyme synthesizes the short RNA starter that it extends?', 'Primase.
It makes an RNA primer (typically 5–10 nucleotides) whose free 3′ end gives DNA polymerase a start: polymerases can only add nucleotides to an existing 3′ end, so new DNA grows 5′→3′. The leading strand needs one primer; the lagging strand needs one for each Okazaki fragment.', 'primase', array['DNA primase']::text[]),
  ('bio-molecular/lagging-strand-enzymes', 'bio-molecular', 5, 'On the lagging strand in E. coli, what do DNA pol III, DNA pol I and DNA ligase each do?', 'DNA pol III extends each RNA primer into an Okazaki fragment. DNA pol I removes the RNA primer and replaces it with DNA. DNA ligase seals the remaining nick, joining the sugar-phosphate backbones of adjacent fragments.
The strand is discontinuous because polymerase builds only 5′→3′, which on this strand means working away from the fork.', null, '{}'::text[]),
  ('bio-molecular/telomerase', 'bio-molecular', 6, 'Which enzyme lengthens the ends of linear chromosomes in germ cells, using an RNA template it carries with it?', 'Telomerase.
Once the RNA primer at the very end of a new strand is removed, it can''t be replaced with DNA (no 3′ end to extend), so chromosomes shorten each round. Telomeres (TTAGGG repeats in humans) buffer this loss. Telomerase is active in germ cells and many cancer cells but not in most somatic cells.', 'telomerase', '{}'::text[]),
  ('bio-molecular/coding-vs-template-strand', 'bio-molecular', 7, 'An mRNA has the same sequence (with U in place of T) as which DNA strand?', 'The coding (nontemplate) strand.
RNA polymerase reads the template strand 3′→5′ and builds a complementary RNA 5′→3′, so the RNA matches the other strand. Trap: the template strand is complementary to the mRNA, not identical to it.', 'coding strand', array['coding', 'nontemplate strand', 'non-template strand', 'nontemplate', 'non-template', 'sense strand']::text[]),
  ('bio-molecular/tata-box', 'bio-molecular', 8, 'In eukaryotic promoters, what sequence ≈25 nucleotides upstream of the start point is a key binding site for transcription factors?', 'The TATA box.
Transcription factors bind it first, then RNA polymerase II joins them to form the transcription initiation complex. Unlike bacterial RNA polymerase, eukaryotic RNA polymerase can''t recognize a promoter on its own.', 'TATA box', array['TATA', 'TATAAA', 'TATA sequence', 'Hogness box', 'Goldberg-Hogness box']::text[]),
  ('bio-molecular/rna-processing', 'bio-molecular', 9, 'Name the three modifications that turn eukaryotic pre-mRNA into mature mRNA before it leaves the nucleus.', 'A 5′ cap (a modified guanine nucleotide), a poly-A tail (50–250 adenine nucleotides on the 3′ end), and RNA splicing, in which spliceosomes cut out introns and join the exons.
The cap and tail help export the mRNA from the nucleus, protect it from hydrolytic enzymes, and help ribosomes attach.', null, '{}'::text[]),
  ('bio-molecular/start-and-stop-codons', 'bio-molecular', 10, 'Which codon starts translation, and which three codons stop it?', 'Start: AUG, which also codes for methionine and sets the reading frame.
Stop: UAA, UAG, UGA. They code for no amino acid; a protein release factor binds the stop codon in the A site and frees the polypeptide.
Mnemonic: U Are Away, U Are Gone, U Go Away.', null, '{}'::text[]),
  ('bio-molecular/codon-anticodon', 'bio-molecular', 11, 'An mRNA codon reads 5′-GCA-3′. What is the matching tRNA anticodon, written 5′→3′?', '5′-UGC-3′.
Codon and anticodon pair antiparallel: 5′-GCA-3′ pairs with 3′-CGU-5′, which reads UGC when written 5′→3′. Trap: answering CGU without flipping it. GCA codes for alanine, so this tRNA carries Ala.', 'UGC', array['5''-UGC-3''', '5''UGC3''', '3''-CGU-5''', '3''CGU5''']::text[]),
  ('bio-molecular/ribosome-sites', 'bio-molecular', 12, 'During elongation, what does each tRNA binding site on the ribosome (A, P and E) hold?', 'A site: the incoming aminoacyl-tRNA with the next amino acid. P site: the tRNA holding the growing polypeptide. E site: the empty tRNA about to exit.
The polypeptide is transferred onto the A-site amino acid (rRNA catalyzes the peptide bond), then the ribosome shifts one codon so tRNAs move A → P → E.', null, '{}'::text[]),
  ('bio-molecular/frameshift-mutation', 'bio-molecular', 13, 'Inserting or deleting nucleotides in a number that isn''t a multiple of three causes what type of mutation?', 'A frameshift mutation: every codon after it is misread, usually giving a nonfunctional protein, often cut short by an early stop codon.
Substitution types: silent (same amino acid), missense (different amino acid, e.g., sickle-cell disease), nonsense (codon becomes a stop codon).', 'frameshift mutation', array['frameshift', 'frame-shift', 'frame-shift mutation', 'frameshift mutations']::text[]),
  ('bio-molecular/lac-operon-inducer', 'bio-molecular', 14, 'What is the natural inducer of the lac operon, the molecule that binds and inactivates the lac repressor?', 'Allolactose, an isomer of lactose (trap: not lactose itself; IPTG is a synthetic lab inducer).
The lac operon is inducible: usually off because the repressor sits on the operator. When glucose is scarce, cAMP builds up and activates CAP, which helps RNA polymerase bind the promoter and boosts transcription (positive control).', 'allolactose', '{}'::text[]),
  ('bio-molecular/trp-operon-corepressor', 'bio-molecular', 15, 'How does abundant tryptophan switch off the trp operon in E. coli?', 'It acts as a corepressor: tryptophan binds the trp repressor, which is inactive on its own, and activates it, so the repressor binds the operator and blocks transcription.
The trp operon is repressible (usually on; anabolic pathway). The lac operon is inducible (usually off; catabolic pathway).', null, '{}'::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'bio-molecular' and id not in ('bio-molecular/gc-hydrogen-bonds', 'bio-molecular/chargaff-rules', 'bio-molecular/meselson-stahl', 'bio-molecular/topoisomerase', 'bio-molecular/primase', 'bio-molecular/lagging-strand-enzymes', 'bio-molecular/telomerase', 'bio-molecular/coding-vs-template-strand', 'bio-molecular/tata-box', 'bio-molecular/rna-processing', 'bio-molecular/start-and-stop-codons', 'bio-molecular/codon-anticodon', 'bio-molecular/ribosome-sites', 'bio-molecular/frameshift-mutation', 'bio-molecular/lac-operon-inducer', 'bio-molecular/trp-operon-corepressor');

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('bio-genetics/law-of-segregation', 'bio-genetics', 0, 'Which of Mendel''s laws says the two alleles for a character separate during gamete formation, so each gamete gets just one?', 'The law of segregation.
Its physical basis: homologous chromosomes, which carry the two alleles, separate in anaphase I of meiosis. So a heterozygote (Aa) makes A and a gametes in a 1:1 ratio.', 'law of segregation', array['segregation', 'principle of segregation', 'Mendel''s law of segregation', 'Mendels law of segregation', 'Mendel''s first law', 'Mendels first law']::text[]),
  ('bio-genetics/monohybrid-heterozygote-fraction', 'bio-genetics', 1, 'In a Pp × Pp cross (purple dominant to white), what fraction of the purple-flowered offspring are heterozygous?', '2/3.
Genotypes come out 1 PP : 2 Pp : 1 pp, so phenotypes are 3 purple : 1 white. Of the 3 purple, 2 are Pp. Trap: 1/2 is the fraction of all offspring that are Pp.', '2/3', array['two thirds', 'two-thirds', '2 out of 3', '2 in 3', '0.67', '0.667', '67%', '66.7%', '66.67%']::text[]),
  ('bio-genetics/testcross', 'bio-genetics', 2, 'How can you find out whether a purple-flowered pea plant (dominant phenotype) is PP or Pp?', 'A testcross: breed it with a homozygous recessive (pp, white) plant.
All purple offspring → the plant is PP. About half white (1:1) → it''s Pp. The pp parent can only pass on p, so each offspring''s phenotype reveals which allele the unknown parent gave.', null, '{}'::text[]),
  ('bio-genetics/dihybrid-ratio', 'bio-genetics', 3, 'What phenotypic ratio comes from an AaBb × AaBb cross with two unlinked genes, each showing complete dominance?', '9:3:3:1 (9 A_B_ : 3 A_bb : 3 aaB_ : 1 aabb).
Each gene alone gives 3:1, and (3:1) × (3:1) = 9:3:3:1. This is the signature of independent assortment; linkage or epistasis changes it.', '9:3:3:1', array['9 3 3 1', '9-3-3-1', '9/3/3/1', '9,3,3,1']::text[]),
  ('bio-genetics/product-rule', 'bio-genetics', 4, 'With three unlinked genes, what fraction of the offspring from AaBbCc × AaBbCc will be aabbcc?', '1/64, by the product rule: each gene independently gives 1/4 homozygous recessive, so 1/4 × 1/4 × 1/4 = 1/64.
Use the sum rule (add) when an outcome can arise in more than one mutually exclusive way: Aa from Aa × Aa = 1/4 + 1/4 = 1/2.', '1/64', array['1 in 64', '0.015625', '0.0156', '1.56%', '1.5625%']::text[]),
  ('bio-genetics/incomplete-dominance', 'bio-genetics', 5, 'Red snapdragons crossed with white ones give all pink offspring. What inheritance pattern explains this?', 'Incomplete dominance: the heterozygote shows an intermediate phenotype.
Crossing two pinks gives 1 red : 2 pink : 1 white, so the phenotype ratio equals the genotype ratio. It isn''t blending, since red and white reappear. Contrast codominance, where both alleles show fully (e.g., AB blood type).', 'incomplete dominance', array['incomplete', 'partial dominance', 'semidominance', 'semi-dominance']::text[]),
  ('bio-genetics/abo-blood-type-cross', 'bio-genetics', 6, 'A type A parent and a type B parent have a type O child. What are the parents'' genotypes?', 'Iᴬi and Iᴮi (both heterozygous); the child is ii.
Their children could be AB, A, B or O, each with probability 1/4. ABO has three alleles: Iᴬ and Iᴮ are codominant (type AB shows both A and B carbohydrates), and both are dominant to i.', null, '{}'::text[]),
  ('bio-genetics/epistasis', 'bio-genetics', 7, 'Labradors with genotype ee are yellow no matter which B/b alleles they carry. What is this kind of gene interaction called?', 'Epistasis: the E gene (whether pigment is deposited in fur) masks the B gene (black vs brown pigment).
BbEe × BbEe gives 9 black : 3 brown : 4 yellow instead of 9:3:3:1.', 'epistasis', array['epistatic', 'recessive epistasis', 'epistatic interaction']::text[]),
  ('bio-genetics/x-linked-recessive-sons', 'bio-genetics', 8, 'A woman who carries an X-linked recessive allele has children with an unaffected man. What fraction of their sons will be affected?', '1/2: each son gets one of his mother''s two X chromosomes (and his father''s Y).
No daughters are affected, but half are carriers. Males need only one copy because they''re hemizygous, so disorders like hemophilia and Duchenne muscular dystrophy are far more common in males.', '1/2', array['half', 'one half', 'one-half', '1 in 2', '50%', '50 percent', '0.5']::text[]),
  ('bio-genetics/pedigree-autosomal-recessive', 'bio-genetics', 9, 'In a pedigree, two unaffected parents have an affected daughter. What mode of inheritance must the trait have?', 'Autosomal recessive, with both parents carriers (heterozygous).
It can''t be dominant: an affected child would need an affected parent. It can''t be X-linked recessive: an affected daughter would need an affected father.', 'autosomal recessive', array['recessive autosomal', 'autosomal-recessive', 'autosomal recessive inheritance', 'AR']::text[]),
  ('bio-genetics/linked-genes', 'bio-genetics', 10, 'Mendel''s law of independent assortment holds for genes on different chromosomes. What kind of genes tend to break it?', 'Linked genes: genes close together on the same chromosome, which tend to be inherited together.
Only crossing over separates them, producing recombinant offspring. Genes far apart on one chromosome recombine so often (up to 50%) that they assort as if unlinked.', 'linked genes', array['linked', 'linked gene', 'genetically linked genes', 'genes on the same chromosome', 'genes close together on the same chromosome']::text[]),
  ('bio-genetics/map-units', 'bio-genetics', 11, 'A testcross yields 2,000 offspring, 160 of them recombinant for two genes. How far apart are the genes on a linkage map?', '8 map units (centimorgans).
Recombination frequency = 160 ÷ 2,000 = 8%, and 1% recombination = 1 map unit (1 cM). Genes farther apart cross over more often. Frequencies top out at 50%, and map units measure crossover frequency, not physical distance.', '8 map units', array['8', '8 cM', '8 centimorgans', '8 centimorgan', '8 map unit', '8 mu', '8 m.u.']::text[]),
  ('bio-genetics/hardy-weinberg-equations', 'bio-genetics', 12, 'Write the two Hardy–Weinberg equations and say what each term stands for.', 'p + q = 1: allele frequencies (p = dominant allele, q = recessive allele).
p² + 2pq + q² = 1: genotype frequencies (p² = homozygous dominant, 2pq = heterozygous, q² = homozygous recessive).', null, '{}'::text[]),
  ('bio-genetics/hardy-weinberg-conditions', 'bio-genetics', 13, 'List the five conditions a population must meet to stay in Hardy–Weinberg equilibrium.', '1) No mutations. 2) Random mating. 3) No natural selection. 4) An extremely large population (no genetic drift). 5) No gene flow.
If any is violated, allele or genotype frequencies can change from generation to generation.', null, '{}'::text[]),
  ('bio-genetics/carrier-frequency', 'bio-genetics', 14, 'A recessive disorder affects 1 in 10,000 newborns. Assuming Hardy–Weinberg, about what fraction of people are carriers?', 'About 2% (≈1 in 50).
q² = 0.0001, so q = 0.01 and p = 0.99. Carriers = 2pq = 2 × 0.99 × 0.01 ≈ 0.0198. Traps: using q² or q as the carrier frequency, or forgetting to take the square root.', null, '{}'::text[]),
  ('bio-genetics/founder-effect', 'bio-genetics', 15, 'A few individuals colonize an island, and by chance a rare mainland allele becomes common there. Which kind of genetic drift is this?', 'The founder effect, a form of genetic drift.
The small founding group''s allele frequencies differ from the source population''s by chance. Related: the bottleneck effect, when a disaster or habitat loss drastically shrinks a population, as with Illinois''s greater prairie chickens. Drift is strongest in small populations.', 'founder effect', array['founder', 'founders effect', 'founder''s effect']::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'bio-genetics' and id not in ('bio-genetics/law-of-segregation', 'bio-genetics/monohybrid-heterozygote-fraction', 'bio-genetics/testcross', 'bio-genetics/dihybrid-ratio', 'bio-genetics/product-rule', 'bio-genetics/incomplete-dominance', 'bio-genetics/abo-blood-type-cross', 'bio-genetics/epistasis', 'bio-genetics/x-linked-recessive-sons', 'bio-genetics/pedigree-autosomal-recessive', 'bio-genetics/linked-genes', 'bio-genetics/map-units', 'bio-genetics/hardy-weinberg-equations', 'bio-genetics/hardy-weinberg-conditions', 'bio-genetics/carrier-frequency', 'bio-genetics/founder-effect');

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('bio-metabolism/activation-energy', 'bio-metabolism', 0, 'Enzymes speed up chemical reactions by lowering what?', 'The activation energy (EA), the energy needed to reach the transition state.
Enzymes don''t change ΔG, so they can''t make an endergonic reaction spontaneous; they only speed up reactions that would happen anyway. They aren''t used up and are specific to their substrates.', 'activation energy', array['EA', 'activation energy barrier', 'energy of activation', 'free energy of activation']::text[]),
  ('bio-metabolism/competitive-inhibition', 'bio-metabolism', 1, 'An enzyme inhibitor''s effect can be overcome by adding more substrate. What type of inhibitor is it?', 'A competitive inhibitor: it resembles the substrate and competes for the active site.
A noncompetitive inhibitor binds elsewhere on the enzyme and changes its shape, making the active site less effective, so extra substrate doesn''t help.', 'competitive', array['competitive inhibitor', 'competitive inhibition']::text[]),
  ('bio-metabolism/glycolysis-net-atp', 'bio-metabolism', 2, 'What is the net ATP yield of glycolysis per molecule of glucose?', '2 ATP (4 made by substrate-level phosphorylation, minus 2 invested early on).
Glycolysis also yields 2 NADH and 2 pyruvate. It runs in the cytosol and doesn''t need O₂.', '2', array['2 ATP', 'two', 'net 2 ATP', 'net 2']::text[]),
  ('bio-metabolism/pyruvate-oxidation', 'bio-metabolism', 3, 'Pyruvate oxidation converts each pyruvate into what molecule, which then enters the citric acid cycle?', 'Acetyl CoA.
In the mitochondrial matrix, pyruvate loses a carbon as CO₂, the remaining two-carbon fragment is oxidized (NAD⁺ → NADH), and coenzyme A is attached. Per glucose: 2 acetyl CoA, 2 CO₂, 2 NADH.', 'acetyl CoA', array['acetyl-CoA', 'acetyl Co-A', 'acetyl-Co-A', 'acetyl coenzyme A', 'acetyl-coenzyme A']::text[]),
  ('bio-metabolism/citric-acid-cycle-yield', 'bio-metabolism', 4, 'Per glucose (two turns), what does the citric acid cycle produce?', '2 ATP, 6 NADH, 2 FADH₂ and 4 CO₂ (per turn: 1 ATP, 3 NADH, 1 FADH₂, 2 CO₂).
It runs in the mitochondrial matrix. With pyruvate oxidation''s 2 CO₂, all six carbons of glucose leave as CO₂. In some cells, the cycle''s one substrate-level phosphorylation step makes GTP instead of ATP.', null, '{}'::text[]),
  ('bio-metabolism/final-electron-acceptor', 'bio-metabolism', 5, 'What is the final electron acceptor of the mitochondrial electron transport chain?', 'O₂, which picks up electrons and H⁺ to form water.
The chain is embedded in the inner mitochondrial membrane (cristae). Without O₂ the chain stalls, NADH can''t be reoxidized, and cells must rely on fermentation. Cyanide kills by blocking electron transfer to O₂.', 'O2', array['oxygen', 'molecular oxygen', 'oxygen gas']::text[]),
  ('bio-metabolism/chemiosmosis-intermembrane-space', 'bio-metabolism', 6, 'In mitochondria, the electron transport chain pumps H⁺ out of the matrix into which compartment?', 'The intermembrane space.
H⁺ flows back down its gradient into the matrix through ATP synthase, which uses this proton-motive force to make ATP from ADP and phosphate. This is chemiosmosis; together with the ETC it forms oxidative phosphorylation, which makes almost 90% of respiration''s ATP.', 'intermembrane space', array['intermembrane', 'inter-membrane space']::text[]),
  ('bio-metabolism/atp-yield-per-glucose', 'bio-metabolism', 7, 'About how many ATP does aerobic respiration yield per glucose, and why isn''t it an exact whole number?', 'About 30–32 ATP in current textbooks (older ones say 36–38).
Each NADH gives ≈2.5 ATP and each FADH₂ ≈1.5; NADH from glycolysis yields less if a shuttle passes its electrons to FAD; and some of the proton-motive force powers other work. That captures roughly a third of glucose''s chemical energy.', null, '{}'::text[]),
  ('bio-metabolism/fermentation-nad', 'bio-metabolism', 8, 'Fermentation makes no ATP beyond glycolysis. So what does it accomplish for a cell without O₂?', 'It regenerates NAD⁺ from NADH, so glycolysis (net 2 ATP per glucose) can keep running.
Lactic acid fermentation: pyruvate → lactate (muscle cells, some bacteria). Alcohol fermentation: pyruvate → CO₂ + acetaldehyde → ethanol (yeast).', null, '{}'::text[]),
  ('bio-metabolism/oxygen-from-water', 'bio-metabolism', 9, 'The O₂ released by photosynthesis comes from splitting which molecule?', 'Water (H₂O).
Photosystem II splits water to replace electrons lost by its P680 reaction center; the H⁺ goes into the thylakoid space and O₂ is released. ¹⁸O tracer experiments confirmed it: labeled water gives labeled O₂, labeled CO₂ doesn''t. CO₂''s oxygen ends up in sugar and new water.', 'water', array['H2O']::text[]),
  ('bio-metabolism/photosystem-ii-first', 'bio-metabolism', 10, 'In linear electron flow, which photosystem is the first to absorb light and pass electrons down the chain?', 'Photosystem II (reaction center P680); the photosystems are numbered in order of discovery.
Its electrons pass via an electron transport chain (plastoquinone → cytochrome complex → plastocyanin) to photosystem I (P700), then to NADP⁺, forming NADPH. The H⁺ gradient built along the way drives ATP synthesis. All of this happens in the thylakoid membranes.', null, '{}'::text[]),
  ('bio-metabolism/calvin-cycle-stroma', 'bio-metabolism', 11, 'In which part of the chloroplast does the Calvin cycle take place?', 'The stroma, the fluid surrounding the thylakoids.
It spends the ATP and NADPH made by the light reactions in the thylakoid membranes. Location trap: thylakoid = light reactions, stroma = Calvin cycle (just as the mitochondrial matrix holds the citric acid cycle).', 'stroma', array['chloroplast stroma']::text[]),
  ('bio-metabolism/rubisco', 'bio-metabolism', 12, 'Which enzyme catalyzes carbon fixation, the first step of the Calvin cycle, and is probably the most abundant protein on Earth?', 'Rubisco (RuBP carboxylase-oxygenase).
It attaches CO₂ to the 5-carbon sugar RuBP; the unstable 6-carbon product immediately splits into two molecules of 3-phosphoglycerate. Rubisco can also bind O₂ instead of CO₂, which causes photorespiration.', 'rubisco', array['RuBP carboxylase', 'RuBP carboxylase-oxygenase', 'RuBP carboxylase/oxygenase', 'ribulose bisphosphate carboxylase', 'ribulose bisphosphate carboxylase-oxygenase', 'ribulose bisphosphate carboxylase/oxygenase', 'ribulose-1,5-bisphosphate carboxylase/oxygenase']::text[]),
  ('bio-metabolism/calvin-cycle-cost', 'bio-metabolism', 13, 'To make one net G3P from 3 CO₂, how many ATP and NADPH does the Calvin cycle use?', '9 ATP and 6 NADPH.
Phases: carbon fixation (rubisco), reduction (6 ATP and 6 NADPH turn 3-phosphoglycerate into G3P), and regeneration of RuBP (3 ATP). The equivalent of one glucose takes 2 G3P: 6 CO₂, 18 ATP and 12 NADPH.', null, '{}'::text[]),
  ('bio-metabolism/photorespiration', 'bio-metabolism', 14, 'On hot, dry days a C3 plant closes its stomata, and rubisco starts adding O₂ instead of CO₂ to RuBP. What is this wasteful process?', 'Photorespiration.
It consumes O₂ and releases CO₂ but makes no ATP and no sugar, and can drain as much as 50% of the carbon fixed by the Calvin cycle. C3 crops such as rice, wheat and soybeans are vulnerable; C4 and CAM plants minimize it.', 'photorespiration', '{}'::text[]),
  ('bio-metabolism/c4-vs-cam', 'bio-metabolism', 15, 'How do C4 plants and CAM plants each keep initial CO₂ fixation separate from the Calvin cycle?', 'C4 (corn, sugarcane): in space. PEP carboxylase fixes CO₂ into 4-carbon compounds in mesophyll cells, which pass them to bundle-sheath cells that release CO₂ to the Calvin cycle.
CAM (cacti, pineapple): in time. Stomata open at night and CO₂ is stored as organic acids; by day, with stomata closed, the same cells release it to the Calvin cycle.', null, '{}'::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'bio-metabolism' and id not in ('bio-metabolism/activation-energy', 'bio-metabolism/competitive-inhibition', 'bio-metabolism/glycolysis-net-atp', 'bio-metabolism/pyruvate-oxidation', 'bio-metabolism/citric-acid-cycle-yield', 'bio-metabolism/final-electron-acceptor', 'bio-metabolism/chemiosmosis-intermembrane-space', 'bio-metabolism/atp-yield-per-glucose', 'bio-metabolism/fermentation-nad', 'bio-metabolism/oxygen-from-water', 'bio-metabolism/photosystem-ii-first', 'bio-metabolism/calvin-cycle-stroma', 'bio-metabolism/rubisco', 'bio-metabolism/calvin-cycle-cost', 'bio-metabolism/photorespiration', 'bio-metabolism/c4-vs-cam');

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('bio-evolution/natural-selection-requirements', 'bio-evolution', 0, 'What conditions must hold for natural selection to change a population over generations?', 'Individuals vary in a trait; the variation is heritable; more offspring are produced than can survive and reproduce; and some heritable traits improve survival and reproduction.
Favored heritable traits then become more common over generations. Selection acts on individuals'' phenotypes, but populations are what evolve.', null, '{}'::text[]),
  ('bio-evolution/relative-fitness', 'bio-evolution', 1, 'A strong, long-lived male mouse never fathers any offspring. What is his relative fitness?', 'Zero.
Relative fitness is an individual''s contribution to the gene pool of the next generation compared with others'' contributions. Strength and survival count only insofar as they lead to reproduction.', '0', array['zero']::text[]),
  ('bio-evolution/directional-selection', 'bio-evolution', 2, 'After a drought left mostly large, hard seeds, finches with deeper beaks survived and mean beak depth rose. What mode of selection is this?', 'Directional selection: individuals at one extreme are favored, shifting the population''s mean.
This happened to medium ground finches on Daphne Major in the Galápagos after the 1977 drought: the survivors'' offspring had deeper beaks on average.', 'directional selection', array['directional']::text[]),
  ('bio-evolution/stabilizing-selection', 'bio-evolution', 3, 'Babies of intermediate birth weight have historically survived better than very small or very large ones. What mode of selection is this?', 'Stabilizing selection: it favors intermediate phenotypes and acts against both extremes, reducing variation while the mean stays put.
Most human birth weights fall around 3–4 kg; much smaller or larger babies have had higher mortality.', 'stabilizing selection', array['stabilizing', 'stabilising selection', 'stabilising']::text[]),
  ('bio-evolution/disruptive-selection', 'bio-evolution', 4, 'Seedcracker finches with small or large beaks feed efficiently, but those with intermediate beaks don''t. What mode of selection is this?', 'Disruptive selection: both extremes are favored over intermediates, which can split the trait into two peaks.
In black-bellied seedcrackers in Cameroon, small-billed birds feed mainly on soft seeds and large-billed birds crack hard ones; intermediate bills handle both poorly.', 'disruptive selection', array['disruptive', 'diversifying selection']::text[]),
  ('bio-evolution/intersexual-selection', 'bio-evolution', 5, 'Peahens prefer to mate with the males that have the showiest tails. What specific form of sexual selection is this?', 'Intersexual selection (mate choice): members of one sex, usually females, choose mates based on certain traits.
Contrast intrasexual selection: competition within one sex, often males, for mates. Either can spread traits that boost mating success even if they reduce survival, producing sexual dimorphism.', 'intersexual selection', array['intersexual', 'mate choice', 'female choice']::text[]),
  ('bio-evolution/gene-flow', 'bio-evolution', 6, 'What is the movement of alleles into or out of a population by migrating fertile individuals or their gametes, such as pollen, called?', 'Gene flow.
It tends to make populations more genetically alike. It can spread useful alleles (e.g., insecticide resistance among mosquito populations) or swamp local adaptations. Contrast genetic drift: chance changes in allele frequencies, strongest in small populations.', 'gene flow', array['migration']::text[]),
  ('bio-evolution/homologous-vs-analogous', 'bio-evolution', 7, 'How do homologous structures differ from analogous structures? Give an example of each.', 'Homologous: similar because of shared ancestry, even if their functions differ (human arm, whale flipper and bat wing share the same set of bones). Analogous: similar function but evolved independently by convergent evolution (bird wings vs insect wings).
Homologies indicate common ancestry; analogies don''t.', null, '{}'::text[]),
  ('bio-evolution/vestigial-structures', 'bio-evolution', 8, 'Remnants of structures that were functional in an organism''s ancestors, like the pelvic bones of some snakes, are called what?', 'Vestigial structures.
They persist because they''re inherited from ancestors that used them, so they''re evidence of descent with modification. They may keep minor uses; what matters is that they''re reduced leftovers of an ancestral feature. Another example: the reduced eyes of blind cave fish.', 'vestigial structures', array['vestigial', 'vestigial structure', 'vestigial organs', 'vestigial organ', 'vestigial traits', 'vestigial trait']::text[]),
  ('bio-evolution/biological-species-concept', 'bio-evolution', 9, 'According to the biological species concept, what makes two populations members of the same species?', 'Their members can interbreed in nature and produce viable, fertile offspring, and are reproductively isolated from other such groups.
Limitation: it can''t be applied to fossils or to asexual organisms such as prokaryotes, so morphological, ecological and phylogenetic species concepts are used as well.', null, '{}'::text[]),
  ('bio-evolution/temporal-isolation', 'bio-evolution', 10, 'Eastern spotted skunks mate in late winter, western spotted skunks in late summer, so they don''t interbreed. Which specific barrier is this?', 'Temporal isolation, a prezygotic barrier (it acts before fertilization).
Other prezygotic barriers: habitat, behavioral, mechanical and gametic isolation. Postzygotic barriers act after a hybrid zygote forms: reduced hybrid viability, reduced hybrid fertility and hybrid breakdown.', 'temporal isolation', array['temporal', 'temporal barrier']::text[]),
  ('bio-evolution/postzygotic-barrier', 'bio-evolution', 11, 'A horse and a donkey can produce a mule, but mules are sterile. What type of reproductive barrier is this?', 'A postzygotic barrier: reduced hybrid fertility.
The hybrid forms and survives but can''t reproduce, because the parents'' chromosomes differ in number and structure and can''t pair properly in meiosis. Other postzygotic barriers: reduced hybrid viability and hybrid breakdown (later-generation hybrids are feeble or sterile).', 'postzygotic', array['post-zygotic', 'postzygotic barrier', 'postzygotic isolation', 'reduced hybrid fertility', 'hybrid sterility']::text[]),
  ('bio-evolution/allopatric-vs-sympatric', 'bio-evolution', 12, 'What is the key difference between allopatric and sympatric speciation?', 'Allopatric: a geographic barrier splits a population and the isolated groups diverge (e.g., snapping shrimp separated by the Isthmus of Panama).
Sympatric: a new species arises within the same area, with no geographic barrier, through polyploidy, habitat differentiation or sexual selection.', null, '{}'::text[]),
  ('bio-evolution/polyploidy', 'bio-evolution', 13, 'A cell-division error gives a plant extra chromosome sets, isolating it from its parent species in one generation. What is this condition?', 'Polyploidy.
A tetraploid (4n) can self-pollinate or mate with other tetraploids, but crosses with its diploid parents give triploid offspring with reduced fertility, so it''s reproductively isolated at once. It''s a common route to sympatric speciation in plants; wheat, oats, cotton and potatoes are polyploids.', 'polyploidy', array['polyploid', 'autopolyploidy', 'autopolyploid', 'tetraploidy', 'tetraploid']::text[]),
  ('bio-evolution/shared-derived-character', 'bio-evolution', 14, 'Hair is found in all mammals and in no other vertebrates. In cladistic terms, what kind of character is hair for the mammal clade?', 'A shared derived character (synapomorphy): an evolutionary novelty unique to a clade, so it can define that clade.
A backbone is a shared ancestral character for mammals: it arose in an earlier ancestor and is shared with other vertebrates. A clade is an ancestor plus all of its descendants.', 'shared derived character', array['shared derived', 'shared derived trait', 'shared derived characters', 'synapomorphy', 'derived character', 'derived trait']::text[]),
  ('bio-evolution/punctuated-equilibrium', 'bio-evolution', 15, 'How does the punctuated equilibrium model of the tempo of speciation differ from gradualism?', 'Punctuated equilibrium: species appear relatively suddenly in the fossil record, then change little for long periods (stasis). Gradualism: species diverge slowly and steadily through many intermediate forms.
The fossil record shows both patterns, and ''sudden'' in geologic time can still mean tens of thousands of years.', null, '{}'::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'bio-evolution' and id not in ('bio-evolution/natural-selection-requirements', 'bio-evolution/relative-fitness', 'bio-evolution/directional-selection', 'bio-evolution/stabilizing-selection', 'bio-evolution/disruptive-selection', 'bio-evolution/intersexual-selection', 'bio-evolution/gene-flow', 'bio-evolution/homologous-vs-analogous', 'bio-evolution/vestigial-structures', 'bio-evolution/biological-species-concept', 'bio-evolution/temporal-isolation', 'bio-evolution/postzygotic-barrier', 'bio-evolution/allopatric-vs-sympatric', 'bio-evolution/polyploidy', 'bio-evolution/shared-derived-character', 'bio-evolution/punctuated-equilibrium');

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('bio-physiology/resting-potential-potassium', 'bio-physiology', 0, 'Which ion, leaking out through channels that stay open at rest, is mainly responsible for a neuron''s negative resting potential?', 'K⁺ (potassium).
K⁺ is concentrated inside the cell and diffuses out, leaving the inside at about −70 mV (typically −60 to −80 mV). The Na⁺/K⁺ pump maintains the gradients: high K⁺ inside, high Na⁺ outside.', 'K+', array['potassium', 'K', 'K^+', 'potassium ion', 'potassium ions', 'K+ ions']::text[]),
  ('bio-physiology/action-potential-sodium', 'bio-physiology', 1, 'When a neuron reaches threshold, influx of which ion through voltage-gated channels causes the rising phase of the action potential?', 'Na⁺ (sodium).
At threshold (often about −55 mV), voltage-gated Na⁺ channels open and Na⁺ rushes in, making the inside positive. Then Na⁺ channels inactivate and voltage-gated K⁺ channels open; K⁺ flows out (falling phase), and the membrane briefly dips below rest (undershoot). Inactivated Na⁺ channels cause the refractory period, so signals travel one way.', 'Na+', array['sodium', 'Na', 'Na^+', 'sodium ion', 'sodium ions', 'Na+ ions']::text[]),
  ('bio-physiology/saltatory-conduction', 'bio-physiology', 2, 'In myelinated axons, action potentials are regenerated only at the gaps between myelin segments. What is this jumping conduction called?', 'Saltatory conduction (Latin saltare, to leap).
The gaps are nodes of Ranvier, where voltage-gated Na⁺ channels cluster. Myelin comes from Schwann cells in the PNS and oligodendrocytes in the CNS, and makes conduction much faster than in unmyelinated axons of the same diameter. Multiple sclerosis destroys CNS myelin.', 'saltatory conduction', array['saltatory']::text[]),
  ('bio-physiology/synaptic-calcium', 'bio-physiology', 3, 'When an action potential reaches an axon terminal, influx of which ion triggers synaptic vesicles to release neurotransmitter?', 'Ca²⁺ (calcium), entering through voltage-gated Ca²⁺ channels.
The vesicles fuse with the presynaptic membrane (exocytosis), and the neurotransmitter diffuses across the synaptic cleft to bind receptors, often ligand-gated ion channels, on the postsynaptic cell.', 'Ca2+', array['calcium', 'Ca', 'Ca++', 'Ca+2', 'Ca^2+', 'Ca^(2+)', 'calcium ion', 'calcium ions']::text[]),
  ('bio-physiology/troponin', 'bio-physiology', 4, 'In skeletal muscle, Ca²⁺ binds which protein, shifting tropomyosin off the myosin-binding sites on actin?', 'Troponin (the troponin complex).
The Ca²⁺ is released from the sarcoplasmic reticulum after an action potential spreads down the T tubules. Trap: Ca²⁺ binds troponin, not tropomyosin or myosin. When Ca²⁺ is pumped back into the SR, tropomyosin re-blocks the sites and the muscle relaxes.', 'troponin', array['troponin complex', 'troponin C']::text[]),
  ('bio-physiology/atp-myosin-detachment', 'bio-physiology', 5, 'In the cross-bridge cycle, what must bind to a myosin head to make it let go of actin?', 'ATP.
ATP binding releases the head; hydrolyzing it to ADP and phosphate then cocks the head into its high-energy position, ready to bind actin and pull again (power stroke). With no ATP after death, myosin stays locked to actin: rigor mortis. The filaments slide past each other; neither one shortens.', 'ATP', array['adenosine triphosphate']::text[]),
  ('bio-physiology/blood-path-heart', 'bio-physiology', 6, 'Trace blood through the heart from the venae cavae to the aorta, naming each chamber and valve in order.', 'Venae cavae → right atrium → tricuspid valve → right ventricle → pulmonary valve → pulmonary arteries → lungs → pulmonary veins → left atrium → mitral (bicuspid) valve → left ventricle → aortic valve → aorta.
Trap: pulmonary arteries carry O₂-poor blood. Arteries carry blood away from the heart, whatever its O₂ content.', null, '{}'::text[]),
  ('bio-physiology/sa-node', 'bio-physiology', 7, 'What cluster of specialized cells in the wall of the right atrium sets the heart''s rhythm as its pacemaker?', 'The SA (sinoatrial) node.
Its impulses spread across both atria through gap junctions, are delayed about 0.1 s at the AV node so the atria can empty first, then travel along the bundle branches and Purkinje fibers through the ventricles.', 'SA node', array['sinoatrial node', 'sinoatrial', 'sino-atrial node', 'SA']::text[]),
  ('bio-physiology/nephron-filtrate-path', 'bio-physiology', 8, 'Trace filtrate through a nephron, from where it forms to the collecting duct.', 'Bowman''s capsule → proximal tubule → loop of Henle → distal tubule → collecting duct.
Blood pressure forces water and small solutes (salts, glucose, amino acids, urea) out of the glomerulus into Bowman''s capsule; cells and large proteins stay in the blood. The loop of Henle (water leaves the descending limb, NaCl the ascending) builds the salty medulla that lets the collecting duct concentrate urine.', null, '{}'::text[]),
  ('bio-physiology/adh', 'bio-physiology', 9, 'Which hormone, released from the posterior pituitary when blood osmolarity rises, adds aquaporins to collecting duct cells?', 'ADH (antidiuretic hormone, also called vasopressin), made in the hypothalamus.
More aquaporins let the kidney reabsorb more water, concentrating the urine and bringing blood osmolarity back down (negative feedback). Alcohol inhibits ADH release, producing dilute urine.', 'ADH', array['antidiuretic hormone', 'anti-diuretic hormone', 'vasopressin', 'arginine vasopressin', 'AVP']::text[]),
  ('bio-physiology/aldosterone', 'bio-physiology', 10, 'Which adrenal hormone, triggered by the renin–angiotensin system, makes the distal tubule and collecting duct reabsorb more Na⁺?', 'Aldosterone, from the adrenal cortex.
Low blood pressure or volume makes the juxtaglomerular apparatus release renin, leading to angiotensin II, which stimulates the adrenal cortex. Reabsorbing more Na⁺ (with water following) raises blood volume and pressure. ADH, by contrast, mainly controls water alone.', 'aldosterone', '{}'::text[]),
  ('bio-physiology/glucagon', 'bio-physiology', 11, 'When blood glucose falls between meals, which hormone from pancreatic alpha cells raises it back toward its set point?', 'Glucagon: it signals the liver to break down glycogen and release glucose.
After a meal, beta cells release insulin, which helps body cells take up glucose and the liver store it as glycogen. Each hormone''s effect reverses the change that triggered it: negative feedback.', 'glucagon', '{}'::text[]),
  ('bio-physiology/bohr-effect', 'bio-physiology', 12, 'Lower pH from CO₂ in active tissues reduces hemoglobin''s affinity for O₂, so it unloads more O₂. What is this called?', 'The Bohr effect (Bohr shift): the O₂ dissociation curve shifts right.
CO₂ reacts with water to form carbonic acid, releasing H⁺ that binds hemoglobin and changes its shape. Each hemoglobin has 4 subunits, each with an iron-containing heme that binds one O₂, and binding is cooperative, giving an S-shaped curve.', 'Bohr effect', array['Bohr shift', 'Bohr']::text[]),
  ('bio-physiology/innate-vs-adaptive', 'bio-physiology', 13, 'How does innate immunity differ from adaptive immunity in speed, specificity and memory?', 'Innate: rapid, recognizes molecules shared by broad groups of pathogens (e.g., via Toll-like receptors), no memory. Includes barriers, phagocytes (neutrophils, macrophages), natural killer cells and inflammation; found in all animals.
Adaptive: slower first response, highly specific B- and T-cell receptors, and immunological memory; vertebrates only.', null, '{}'::text[]),
  ('bio-physiology/lymphocyte-roles', 'bio-physiology', 14, 'What does each do: B cells, helper T cells (CD4) and cytotoxic T cells (CD8)?', 'B cells: become plasma cells that secrete antibodies (humoral response).
Helper T (CD4): recognize antigen on class II MHC of antigen-presenting cells, then release cytokines that activate B cells and cytotoxic T cells. HIV destroys them.
Cytotoxic T (CD8): recognize antigen on class I MHC and kill infected or cancer cells with perforin and granzymes.', null, '{}'::text[]),
  ('bio-physiology/steroid-vs-peptide-hormones', 'bio-physiology', 15, 'Why do steroid hormones bind receptors inside target cells, while peptide hormones like insulin bind receptors on the surface?', 'Steroids (e.g., cortisol, estradiol) are lipid-soluble: they diffuse through the plasma membrane and bind intracellular receptors, and the hormone–receptor complex acts as a transcription factor.
Peptide hormones are water-soluble and can''t cross the membrane, so they bind surface receptors that trigger signal transduction, often via second messengers like cAMP.', null, '{}'::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'bio-physiology' and id not in ('bio-physiology/resting-potential-potassium', 'bio-physiology/action-potential-sodium', 'bio-physiology/saltatory-conduction', 'bio-physiology/synaptic-calcium', 'bio-physiology/troponin', 'bio-physiology/atp-myosin-detachment', 'bio-physiology/blood-path-heart', 'bio-physiology/sa-node', 'bio-physiology/nephron-filtrate-path', 'bio-physiology/adh', 'bio-physiology/aldosterone', 'bio-physiology/glucagon', 'bio-physiology/bohr-effect', 'bio-physiology/innate-vs-adaptive', 'bio-physiology/lymphocyte-roles', 'bio-physiology/steroid-vs-peptide-hormones');

delete from public.packs where category_id = 'biology' and id not in ('bio-cell-structure', 'bio-cell-division', 'bio-molecular', 'bio-genetics', 'bio-metabolism', 'bio-evolution', 'bio-physiology');

-- Engineering
insert into public.packs (id, category_id, title, course, description, position) values
  ('eng-circuits', 'engineering', 'Circuit Analysis', 'Circuits I', 'Dividers, node vs mesh, Thévenin/Norton, max power, superposition, op-amp gains, C and L behavior, first-order transients, impedance, RMS.', 0),
  ('eng-statics', 'engineering', 'Statics', 'Engineering Mechanics', 'Varignon, couples, moments about an axis, FBDs and supports, trusses, distributed loads, determinacy, friction (incline, tipping, belts), centroids.', 1),
  ('eng-materials', 'engineering', 'Mechanics of Materials', 'Strength of Materials', 'E and ν values, axial and thermal loading, torsion, bending and shear stress, beam deflection, Mohr''s circle and Euler buckling, with worked numbers.', 2),
  ('eng-thermo', 'engineering', 'Engineering Thermodynamics', 'Thermodynamics I', 'Systems, first-law signs, quality, ideal-gas relations, boundary work, nozzles and throttling, second law, Carnot, COP, entropy, Otto and Rankine.', 3),
  ('eng-fluids', 'engineering', 'Fluid Mechanics', 'Fluid Mechanics', 'Viscosity, hydrostatics, buoyancy, center of pressure, continuity, Bernoulli and Pitot tubes, Reynolds number, friction factor, head loss, drag scaling.', 4),
  ('eng-digital-logic', 'engineering', 'Digital Logic', 'Digital Systems', 'Hex and two''s complement, overflow, De Morgan, NAND universality, parity, minterms and K-maps, adders, muxes, latches, flip-flops, timing, FSMs, counters.', 5)
on conflict (id) do update set category_id = excluded.category_id, title = excluded.title, course = excluded.course, description = excluded.description, position = excluded.position;

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('eng-circuits/resistor-power', 'eng-circuits', 0, 'A 10 Ω resistor carries 2 A. How much power does it absorb?', '40 W.
V = IR = 20 V, so P = VI = 40 W. Same from P = I²R = 4·10 or P = V²/R = 400/10.
Pick whichever form uses the quantities you know. With the passive sign convention a resistor''s p = i²R is never negative: it only absorbs.', '40 W', array['40', '40 watts', '40 watt']::text[]),
  ('eng-circuits/passive-sign-convention', 'eng-circuits', 1, 'Passive sign convention: current enters an element''s + terminal and p = vi = −12 W. Is the element absorbing or delivering power?', 'Delivering (supplying) 12 W.
When current enters the + terminal, p = vi is the power absorbed: p > 0 absorbs, p < 0 delivers. Absorbing −12 W is the same as delivering +12 W.
If current enters the − terminal, use p = −vi. Alexander/Sadiku and Nilsson/Riedel both use this convention.', null, '{}'::text[]),
  ('eng-circuits/voltage-divider', 'eng-circuits', 2, '12 V is applied across 4 kΩ and 2 kΩ resistors in series. What is the voltage across the 2 kΩ resistor?', '4 V.
Voltage divider: v₂ = V_s·R₂/(R₁ + R₂) = 12·2/6 = 4 V; the 4 kΩ resistor takes the other 8 V. The larger resistor gets the larger share.
Only valid if nothing draws current from the midpoint: a load across R₂ must first be combined in parallel with R₂.', '4 V', array['4', '4 volts', '4 volt']::text[]),
  ('eng-circuits/current-divider', 'eng-circuits', 3, '9 A splits between 3 Ω and 6 Ω resistors in parallel. How much current flows through the 3 Ω resistor?', '6 A.
Current divider: i₁ = I·R₂/(R₁ + R₂) = 9·6/9 = 6 A. The numerator is the OTHER resistor, so the smaller resistance carries more current.
Check: R_eq = R₁R₂/(R₁ + R₂) = 2 Ω, v = 9·2 = 18 V, and 18/3 = 6 A.', '6 A', array['6', '6 amps', '6 amp', '6 amperes']::text[]),
  ('eng-circuits/node-vs-mesh', 'eng-circuits', 4, 'Node-voltage vs mesh-current analysis: which Kirchhoff law does each method apply, and what are the unknowns?', 'Node-voltage: KCL at each non-reference node; unknowns are node voltages (N − 1 of them). Works for any circuit.
Mesh-current: KVL around each mesh; unknowns are mesh currents (B − N + 1 of them). Planar circuits only.
Voltage source between two non-reference nodes → supernode; current source shared by two meshes → supermesh.', null, '{}'::text[]),
  ('eng-circuits/superposition-limits', 'eng-circuits', 5, 'Superposition lets you add the voltages and currents produced by each independent source acting alone. What can you NOT add this way?', 'Power.
p = i²R is nonlinear: (i₁ + i₂)²R ≠ i₁²R + i₂²R. Superpose the currents or voltages first, then compute power.
Superposition needs a linear circuit: turn off the other independent sources (V → short, I → open) but leave dependent sources on. (Exception: average powers from sources of different frequencies do add.)', 'power', array['powers', 'power dissipated', 'energy', 'power and energy']::text[]),
  ('eng-circuits/thevenin-deactivate-sources', 'eng-circuits', 6, 'Finding R_th by turning sources off: what replaces an independent voltage source, an independent current source, and a dependent source?', 'Voltage source → short circuit (v = 0). Current source → open circuit (i = 0). Dependent sources are never turned off.
With dependent sources present, use R_th = v_oc/i_sc, or turn off only the independent sources, apply a test source and take R_th = v_test/i_test.
Norton equivalent: R_N = R_th, I_N = i_sc = V_th/R_th.', null, '{}'::text[]),
  ('eng-circuits/max-power-transfer', 'eng-circuits', 7, 'A source has V_th = 20 V and R_th = 5 Ω. What is the maximum power it can deliver to a load resistor?', '20 W, when R_L = R_th = 5 Ω.
P_max = V_th²/(4R_th) = 400/20 = 20 W (check: i = 20/10 = 2 A, P = 2²·5 = 20 W).
Trap: V_th²/R_th = 80 W. At maximum power transfer the efficiency is only 50%: R_th dissipates as much as the load.', '20 W', array['20', '20 watts', '20 watt']::text[]),
  ('eng-circuits/ideal-op-amp-rules', 'eng-circuits', 8, 'What two rules let you analyze an ideal op-amp circuit that has negative feedback?', '1) No current flows into either input: i₊ = i₋ = 0 (infinite input resistance).
2) The two input voltages are equal: v₊ = v₋ (virtual short), from the infinite open-loop gain plus negative feedback.
Write KCL at the input nodes, not at the output node: the op-amp''s output current is an extra unknown (it supplies whatever is needed), and v_o must stay within the supply rails.', null, '{}'::text[]),
  ('eng-circuits/inverting-amplifier-gain', 'eng-circuits', 9, 'An inverting op-amp amplifier has R_in = 2 kΩ and R_f = 10 kΩ. What is its voltage gain v_o/v_in?', '−5.
v_o/v_in = −R_f/R_in = −10/2. Derivation: v₋ = v₊ = 0 (virtual ground), so KCL at the − input gives v_in/R_in = −v_o/R_f.
The minus sign means the output is inverted. The input resistance seen by the source is just R_in.', '-5', array['-5 V/V']::text[]),
  ('eng-circuits/noninverting-amplifier-gain', 'eng-circuits', 10, 'A non-inverting op-amp amplifier has R_f = 4 kΩ (output to − input) and R₁ = 1 kΩ (− input to ground). What is its gain?', '5.
v_o/v_in = 1 + R_f/R₁ = 1 + 4 = 5. The output drives a divider: v₋ = v_o·R₁/(R₁ + R_f), and v₋ = v₊ = v_in.
Trap: answering R_f/R₁ = 4. The gain is always ≥ 1; with R_f = 0 (or R₁ removed) it''s a voltage follower with gain 1.', '5', array['5 V/V']::text[]),
  ('eng-circuits/capacitor-dc-steady-state', 'eng-circuits', 11, 'At DC steady state, an ideal capacitor behaves like what circuit element?', 'An open circuit.
i = C dv/dt, and at DC steady state v is constant, so i = 0. It still holds its charge and stored energy w = ½Cv².
Dual: an inductor (v = L di/dt) acts as a short circuit at DC steady state and stores w = ½Li².', 'open circuit', array['open', 'open-circuit', 'open circuits']::text[]),
  ('eng-circuits/inductor-current-continuity', 'eng-circuits', 12, 'At a switching instant, which cannot change instantaneously in an inductor: its voltage or its current?', 'Its current: i_L(0⁺) = i_L(0⁻).
v = L di/dt, so a jump in current would need an infinite voltage. The inductor''s voltage, by contrast, can jump.
Dual: a capacitor''s voltage is continuous, v_C(0⁺) = v_C(0⁻), while its current can jump.', 'current', array['its current', 'inductor current', 'i_L', 'iL']::text[]),
  ('eng-circuits/first-order-step-response', 'eng-circuits', 13, 'In a first-order RC or RL circuit switched at t = 0, what is the general form of any response x(t) for t > 0?', 'x(t) = x(∞) + [x(0⁺) − x(∞)]e^(−t/τ)
τ = R_th·C for RC, or L/R_th for RL, where R_th is the Thévenin resistance seen by the C or L.
After 1τ about 63.2% of the change is done; after 5τ, more than 99%. Get x(0⁺) from the continuity of v_C or i_L.', null, '{}'::text[]),
  ('eng-circuits/capacitor-impedance', 'eng-circuits', 14, 'What is the impedance of a 1 μF capacitor at ω = 1000 rad/s?', '−j1000 Ω (−j1 kΩ).
Z_C = 1/(jωC) = −j/(ωC) = −j/(1000·10⁻⁶). Inductor: Z_L = jωL.
Limits: as ω → 0, |Z_C| → ∞ (open at DC) and Z_L → 0 (short). The −j means the capacitor''s current leads its voltage by 90°.', '-j1000', array['-1000j', '-j1000 ohms', '-j1000 ohm', '-j1 kohm', '-1000j ohms']::text[]),
  ('eng-circuits/rms-sinusoid', 'eng-circuits', 15, 'What is the RMS value of v(t) = 170 cos(377t) V?', '≈ 120 V.
For a pure sinusoid, V_rms = V_m/√2 ≈ 0.707·V_m = 170/1.414 ≈ 120.2 V. (377 rad/s = 60 Hz: US household voltage.)
This applies only to a sinusoid with no DC offset. Average power to a resistor: P = V_rms²/R.', '120 V', array['120', '120.2 V', '120.2', '120 volts', '120 volt', '170/sqrt(2)', '170/sqrt2', '120.21']::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'eng-circuits' and id not in ('eng-circuits/resistor-power', 'eng-circuits/passive-sign-convention', 'eng-circuits/voltage-divider', 'eng-circuits/current-divider', 'eng-circuits/node-vs-mesh', 'eng-circuits/superposition-limits', 'eng-circuits/thevenin-deactivate-sources', 'eng-circuits/max-power-transfer', 'eng-circuits/ideal-op-amp-rules', 'eng-circuits/inverting-amplifier-gain', 'eng-circuits/noninverting-amplifier-gain', 'eng-circuits/capacitor-dc-steady-state', 'eng-circuits/inductor-current-continuity', 'eng-circuits/first-order-step-response', 'eng-circuits/capacitor-impedance', 'eng-circuits/rms-sinusoid');

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('eng-statics/moment-varignon-components', 'eng-statics', 0, 'A force with components F_x = 3 kN and F_y = 4 kN acts at point (2 m, 1 m). Its moment about the origin, counterclockwise positive?', '+5 kN·m (counterclockwise).
Varignon''s theorem: add the moments of the components. F_y has arm x = 2 m (CCW, +8); F_x has arm y = 1 m (CW, −3). M_O = xF_y − yF_x = 8 − 3 = 5 kN·m, the z-component of r × F.
Trap: adding both (11 kN·m). Check with M = F·d: F = 5 kN and its line of action passes d = 1 m from O.', '5 kN*m', array['5', '+5', '+5 kN*m', '5 kN-m', '5 kN*m ccw', '5 kN*m counterclockwise', '5k kN*m']::text[]),
  ('eng-statics/couple-moment', 'eng-statics', 1, 'Equal and opposite forces F act along parallel lines a perpendicular distance d apart. What is their moment about any point P?', 'M = Fd, the same about every point.
The pair (a couple) has zero resultant force, and its moment doesn''t depend on the reference point, so a couple moment is a free vector: it can be applied anywhere on a rigid body with the same external effect.
Two couples are equivalent if their moments have the same magnitude and direction.', 'Fd', array['dF', 'M = Fd']::text[]),
  ('eng-statics/triangular-load-resultant', 'eng-statics', 2, 'A distributed load increases linearly from 0 at A to 6 kN/m at B, 3 m away. How far from A does its resultant act?', '2 m from A (1 m from B).
Resultant = area under the load curve = ½(6 kN/m)(3 m) = 9 kN, acting through the centroid of that area. A triangle''s centroid is 1/3 of the length from its tall end, i.e., 2/3 from the zero end.
Uniform load w over length L: resultant wL at the midpoint.', '2 m', array['2', '2 meters', '2 meter', '2 m from A']::text[]),
  ('eng-statics/free-body-diagram-rules', 'eng-statics', 3, 'On a free-body diagram, which forces must you show, and which must you leave off?', 'Show every external force and couple on the isolated body: applied loads, the weight at the center of gravity, and the reactions at every support or connection you cut away.
Leave off internal forces (they cancel in pairs) and forces the body exerts on other bodies.
Assume a sense for each unknown; a negative answer just means it acts the other way.', null, '{}'::text[]),
  ('eng-statics/support-reactions-2d', 'eng-statics', 4, 'In 2D, how many reaction components does each support provide: a roller, a smooth pin, and a fixed support?', 'Roller: 1 (a force normal to the surface). Pin: 2 (force components A_x and A_y; it lets the member rotate, so no moment). Fixed: 3 (A_x, A_y and a couple moment M_A).
Rule: a support exerts a force for each direction of translation it prevents and a couple moment for each rotation it prevents.', null, '{}'::text[]),
  ('eng-statics/equilibrium-equations-2d', 'eng-statics', 5, 'How many independent equilibrium equations can you write for one rigid body in a 2D (coplanar) problem?', '3: ΣF_x = 0, ΣF_y = 0, ΣM_O = 0, so one 2D free-body diagram can solve at most 3 unknowns. In 3D there are 6 (three force sums, three moment sums).
Alternative 2D sets: ΣF_x, ΣM_A, ΣM_B (line AB not perpendicular to x) or ΣM_A, ΣM_B, ΣM_C (A, B, C not collinear).', '3', array['three']::text[]),
  ('eng-statics/two-force-member', 'eng-statics', 6, 'A pin-connected member has no loads between its two ends and negligible weight. What must be true of the forces at its ends?', 'They are equal in magnitude, opposite in direction, and collinear along the line joining the two pins, so the member is in pure tension or compression.
Why: summing moments about one pin forces the other pin''s force to pass through it.
For a curved or bent two-force member, the force still acts along the straight line between the pins, not along the member.', null, '{}'::text[]),
  ('eng-statics/static-determinacy', 'eng-statics', 7, 'A 2D beam is supported by a pin at A and rollers at B and C. What is its degree of static indeterminacy?', '1 (indeterminate to the first degree).
Unknown reactions: 2 + 1 + 1 = 4, but equilibrium gives only 3 equations, so degree = 4 − 3 = 1. The extra equation comes from deformation (compatibility), as in Mechanics of Materials.
Exactly 3 reactions isn''t enough on its own: if they are all parallel or all concurrent, the body is improperly constrained.', '1', array['one', 'first', '1st', 'first degree', '1st degree', 'degree 1', 'first-degree']::text[]),
  ('eng-statics/truss-joints-vs-sections', 'eng-statics', 8, 'Truss analysis: when is the method of sections faster than the method of joints?', 'When you need only a few member forces deep inside the truss.
Sections: cut through no more than 3 members with unknown forces and apply all 3 equilibrium equations to one side; take moments about the point where two unknown forces intersect.
Joints: 2 equations (ΣF_x, ΣF_y) per pin, so start at a joint with at most 2 unknowns. Assume tension; a negative result means compression.', null, '{}'::text[]),
  ('eng-statics/zero-force-member', 'eng-statics', 9, 'A truss joint with no external load or support connects three members, two of them collinear. What is the force in the third member?', 'Zero.
Sum forces perpendicular to the collinear pair: only the third member has a component in that direction, so its force must be 0.
Other rule: an unloaded, unsupported joint with only two non-collinear members makes both zero-force members. They still matter: they brace the truss and carry load if the loading changes.', '0', array['zero', '0 N', '0 kN', 'zero force', 'zero-force member']::text[]),
  ('eng-statics/friction-angle-incline', 'eng-statics', 10, 'A block on an incline is on the verge of sliding when the incline angle reaches θ. What is the coefficient of static friction?', 'μ_s = tan θ.
Along the slope: W sin θ = μ_s N; normal to it: N = W cos θ. Dividing gives μ_s = tan θ, independent of the weight.
This θ is the angle of repose, equal to the friction angle φ_s = tan⁻¹ μ_s.', 'tan(theta)', array['tan theta', 'sin(theta)/cos(theta)', 'sin theta/cos theta', 'mu_s = tan(theta)', 'mu = tan(theta)']::text[]),
  ('eng-statics/tipping-vs-sliding', 'eng-statics', 11, 'A uniform crate is pushed horizontally. How do you decide whether it slides or tips first?', 'Find the push P for each case separately; the smaller P happens first.
Sliding: static friction (F ≤ μ_s N) reaches its maximum, so P = μ_s W (level floor).
Tipping: the normal force and friction shift to the leading bottom corner; moments about that corner give P·h = W·b/2 (base width b, push at height h).
If a computed normal-force location falls outside the base, tipping governs.', null, '{}'::text[]),
  ('eng-statics/belt-friction', 'eng-statics', 12, 'A rope wrapped around a fixed drum is on the verge of slipping. How is the tight-side tension T₂ related to the slack-side tension T₁?', 'T₂ = T₁·e^(μ_s·β), where β is the contact angle in RADIANS (each full wrap adds 2π) and T₂ is on the side toward which slipping impends.
Tension grows exponentially with wrap: with μ_s = 0.3, two full wraps (β = 4π) give T₂/T₁ = e^3.77 ≈ 43, which is how a capstan lets one person hold a heavy load.
It doesn''t depend on the drum''s radius.', null, '{}'::text[]),
  ('eng-statics/composite-area-centroid', 'eng-statics', 13, 'How do you find the centroid of a composite area that has a hole cut out of it?', 'x̄ = Σx̃A/ΣA (same for ȳ), where x̃ is the centroid of each simple part.
Treat the hole as a negative area: subtract both its A and its x̃A.
Handy parts: rectangle at its middle, triangle at h/3 from its base, semicircle at 4r/(3π) from its diameter. The centroid lies on any axis of symmetry.', null, '{}'::text[]),
  ('eng-statics/moment-about-axis', 'eng-statics', 14, 'How do you find the moment of a force F about a specified axis a, rather than about a point?', 'M_a = u_a·(r × F), a scalar triple product: u_a is the unit vector along the axis, and r runs from ANY point on the axis to ANY point on F''s line of action.
Only the part of F perpendicular to the axis that doesn''t intersect it causes rotation about it: a force parallel to the axis, or one crossing it, has zero moment about that axis.', null, '{}'::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'eng-statics' and id not in ('eng-statics/moment-varignon-components', 'eng-statics/couple-moment', 'eng-statics/triangular-load-resultant', 'eng-statics/free-body-diagram-rules', 'eng-statics/support-reactions-2d', 'eng-statics/equilibrium-equations-2d', 'eng-statics/two-force-member', 'eng-statics/static-determinacy', 'eng-statics/truss-joints-vs-sections', 'eng-statics/zero-force-member', 'eng-statics/friction-angle-incline', 'eng-statics/tipping-vs-sliding', 'eng-statics/belt-friction', 'eng-statics/composite-area-centroid', 'eng-statics/moment-about-axis');

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('eng-materials/elastic-modulus-values', 'eng-materials', 0, 'Hooke''s law σ = Eε: what is the approximate modulus of elasticity of structural steel, and of aluminum alloys?', 'Steel ≈ 200 GPa (29,000 ksi); aluminum ≈ 70 GPa (10,000 ksi), about 1/3 of steel.
So at the same stress, aluminum strains about 3× as much. E is the slope of the linear-elastic part of the σ–ε curve: it measures stiffness, not strength.
σ = Eε holds only up to the proportional limit.', null, '{}'::text[]),
  ('eng-materials/stress-strain-curve-regions', 'eng-materials', 1, 'Tension test of mild steel: name the four regions of the engineering stress–strain curve, in order.', 'Elastic → yielding → strain hardening → necking.
Key points: proportional limit and yield stress σ_Y (end of elastic behavior), ultimate stress σ_u (the peak), then fracture.
Engineering stress drops during necking only because it divides by the original area; the true stress keeps rising until fracture.', null, '{}'::text[]),
  ('eng-materials/poisson-lateral-strain', 'eng-materials', 2, 'A bar stretched axially to a longitudinal strain of 0.001 has Poisson''s ratio ν = 0.3. What is its lateral strain?', '−0.0003 (−300 × 10⁻⁶): it gets thinner as it stretches.
ν = −ε_lat/ε_long, so ε_lat = −ν·ε_long. The minus sign is the usual trap.
Hibbeler: 0 ≤ ν ≤ 0.5. Metals are about 0.25–0.35 (steel ≈ 0.3); ν = 0.5 means incompressible (rubber-like).', '-0.0003', array['-.0003', '-3e-4', '-300e-6', '-3*10^-4', '-3x10^-4', '-300 microstrain', '-0.0003 mm/mm', '-3*10^(-4)']::text[]),
  ('eng-materials/axial-deformation', 'eng-materials', 3, 'A steel rod (E = 200 GPa) with A = 100 mm² and L = 2 m carries an axial load of 10 kN. How much does it elongate?', '1 mm.
δ = PL/(AE) = (10,000 N)(2000 mm)/[(100 mm²)(200,000 N/mm²)] = 1 mm. N and mm are convenient because 1 MPa = 1 N/mm², so 200 GPa = 200,000 N/mm².
Valid in the linear-elastic range with constant P, A and E; otherwise sum PL/(AE) over segments.', '1 mm', array['1', '1.0 mm', '0.001 m', '1 millimeter', '1 millimeters', '1.0']::text[]),
  ('eng-materials/thermal-stress-fixed-bar', 'eng-materials', 4, 'A steel bar (E = 200 GPa, α = 12 × 10⁻⁶/°C) is held between rigid walls and heated 50 °C. Magnitude of the thermal stress?', '120 MPa, compressive.
The free thermal strain αΔT = 600 × 10⁻⁶ is completely prevented, so σ = EαΔT = (200,000 MPa)(600 × 10⁻⁶) = 120 MPa.
The bar''s length and area don''t matter. If the bar were free to expand, the stress would be zero: thermal strain alone causes no stress.', '120 MPa', array['120', '-120 MPa', '-120', '120 MPa compression', '120 MPa compressive', '120 MPa (C)']::text[]),
  ('eng-materials/shear-modulus-relation', 'eng-materials', 5, 'Hooke''s law in shear is τ = Gγ. How is G related to E and Poisson''s ratio ν for an isotropic material?', 'G = E/[2(1 + ν)].
Steel: 200/(2·1.3) ≈ 77 GPa (Hibbeler''s A-36 table value: 75 GPa). Since 0 ≤ ν ≤ 0.5, G always lies between E/3 and E/2.
γ is the shear strain in radians: the change in an originally right angle.', 'E/(2(1+v))', array['E/(2(1+nu))', 'E/2(1+v)', 'E/2(1+nu)', 'E/(2+2v)', 'E/(2+2nu)']::text[]),
  ('eng-materials/polar-moment-solid-shaft', 'eng-materials', 6, 'What is the polar moment of inertia J of a solid circular shaft of diameter d?', 'J = πd⁴/32 = πc⁴/2 (c = radius).
It sets the torsion stress τ = Tρ/J, which grows linearly from 0 at the center to τ_max = Tc/J at the surface.
Hollow shaft: J = (π/2)(c_o⁴ − c_i⁴). Trap: πd⁴/64 is I about a diameter; J = 2I.', 'pi*d^4/32', array['(pi*d^4)/32', '(pi/32)d^4', 'pi/32*d^4', 'pi*c^4/2', 'pi*r^4/2', '(pi/2)c^4', '(pi/2)r^4']::text[]),
  ('eng-materials/angle-of-twist', 'eng-materials', 7, 'Angle of twist φ of a uniform circular shaft of length L under torque T (shear modulus G)?', 'φ = TL/(GJ), in radians.
Same pattern as axial δ = PL/(AE). For several segments, sum TᵢLᵢ/(GᵢJᵢ) using each segment''s internal torque, positive by the right-hand rule when the thumb points out of the cut section.
Valid for linear-elastic circular shafts.', 'TL/(GJ)', array['TL/GJ', '(TL)/(GJ)', 'TL/(JG)', 'TL/JG']::text[]),
  ('eng-materials/torsion-fracture-ductile-brittle', 'eng-materials', 8, 'Twisted to failure, how does the fracture surface of a ductile shaft differ from that of a brittle one?', 'Ductile (mild steel): a flat break perpendicular to the axis. It fails in shear, which is maximum on transverse planes.
Brittle (cast iron, chalk): a 45° helix. It fails in tension, because pure shear produces σ₁ = τ on planes at 45°.
Ductile = large plastic strain before fracture; brittle = little or no yielding, and much stronger in compression than in tension.', null, '{}'::text[]),
  ('eng-materials/load-shear-moment-relations', 'eng-materials', 9, 'Beam relations: how is the bending moment M related to the shear V, and V to the distributed load w?', 'dM/dx = V and dV/dx = −w, with w the downward load intensity (Hibbeler takes w positive upward and writes dV/dx = w).
So M has a local max or min where V = 0, the change in M between two points = area under the V diagram, and ΔV = −(area under the downward load).
A point force makes V jump; a concentrated couple makes M jump.', null, '{}'::text[]),
  ('eng-materials/rectangle-moment-of-inertia', 'eng-materials', 10, 'Area moment of inertia of a b × h rectangle about its centroidal axis parallel to side b?', 'I = bh³/12, where h is the dimension perpendicular to the bending axis.
A 50 × 200 mm board is 16× stiffer on edge than laid flat: (200/50)² = 16.
Other parallel axes: I = Ī + Ad², with Ī about the centroid (e.g., bh³/3 about the base).', 'bh^3/12', array['(bh^3)/12', '(1/12)bh^3', '1/12bh^3']::text[]),
  ('eng-materials/flexure-formula', 'eng-materials', 11, 'Flexure formula: what is the bending stress at distance y above the neutral axis, and which side is compressed by a positive moment?', 'σ = −My/I (Hibbeler: y measured upward, positive M = sagging, concave up). A positive moment compresses the top and stretches the bottom.
Stress varies linearly: zero at the neutral axis (through the centroid), maximum σ = Mc/I at the extreme fiber.
Assumes linear-elastic, homogeneous material and a section symmetric about the plane of loading.', null, '{}'::text[]),
  ('eng-materials/max-shear-rectangular-beam', 'eng-materials', 12, 'From τ = VQ/(It), what is the maximum transverse shear stress in a rectangular section of area A carrying shear V?', 'τ_max = 1.5V/A, at the neutral axis; the distribution is parabolic, zero at the top and bottom.
Q = ȳ′A′, the first moment about the neutral axis of the area beyond the point; t = section width there. At the NA, Q = bh²/8, so τ = V(bh²/8)/[(bh³/12)b] = 1.5V/(bh).
Trap: V/A is only the average.', '1.5V/A', array['3V/(2A)', '3V/2A', '(3/2)V/A', '3/2 V/A']::text[]),
  ('eng-materials/cantilever-tip-deflection', 'eng-materials', 13, 'Maximum deflection of a cantilever (length L, flexural rigidity EI) carrying a point load P at its free end?', 'δ_max = PL³/(3EI), at the free end (slope there: PL²/(2EI)).
Deflection ∝ L³: doubling the length gives 8× the deflection.
Compare a simply supported beam with P at midspan: PL³/(48EI). Mnemonic: each half acts like a cantilever of length L/2 carrying P/2.', 'PL^3/(3EI)', array['PL^3/3EI', '(PL^3)/(3EI)', '(PL^3)/3EI']::text[]),
  ('eng-materials/mohrs-circle-in-plane-shear', 'eng-materials', 14, 'Plane stress: σ_x = 100 MPa, σ_y = 20 MPa, τ_xy = 30 MPa. What is the maximum in-plane shear stress?', '50 MPa, the radius of Mohr''s circle.
Center σ_avg = (σ_x + σ_y)/2 = 60 MPa; R = √[((σ_x − σ_y)/2)² + τ_xy²] = √(40² + 30²) = 50 MPa. Principal stresses: 60 ± 50 = 110 and 10 MPa.
Both are tensile, so the absolute maximum shear (out of plane, with σ₃ = 0) is 110/2 = 55 MPa.', '50 MPa', array['50']::text[]),
  ('eng-materials/euler-buckling-load', 'eng-materials', 15, 'Euler critical load of a long, slender column of length L with both ends pinned?', 'P_cr = π²EI/L², with I the SMALLEST moment of inertia (it buckles about the weak axis).
Other end conditions: P_cr = π²EI/(KL)² with K = 2 (fixed–free), 0.7 (fixed–pinned), 0.5 (fixed–fixed).
Valid only if σ_cr = P_cr/A stays below the proportional limit (elastic buckling).', 'pi^2EI/L^2', array['(pi^2EI)/L^2', 'pi^2EI/(L^2)', '(pi^2)EI/L^2', '(pi^2EI)/(L^2)']::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'eng-materials' and id not in ('eng-materials/elastic-modulus-values', 'eng-materials/stress-strain-curve-regions', 'eng-materials/poisson-lateral-strain', 'eng-materials/axial-deformation', 'eng-materials/thermal-stress-fixed-bar', 'eng-materials/shear-modulus-relation', 'eng-materials/polar-moment-solid-shaft', 'eng-materials/angle-of-twist', 'eng-materials/torsion-fracture-ductile-brittle', 'eng-materials/load-shear-moment-relations', 'eng-materials/rectangle-moment-of-inertia', 'eng-materials/flexure-formula', 'eng-materials/max-shear-rectangular-beam', 'eng-materials/cantilever-tip-deflection', 'eng-materials/mohrs-circle-in-plane-shear', 'eng-materials/euler-buckling-load');

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('eng-thermo/isolated-system', 'eng-thermo', 0, 'What type of thermodynamic system allows neither mass nor energy to cross its boundary?', 'An isolated system.
Closed system (control mass): energy can cross as heat or work, but mass cannot, e.g., gas in a piston–cylinder.
Open system (control volume): both mass and energy cross, e.g., turbines, nozzles, pumps.', 'isolated', array['isolated system']::text[]),
  ('eng-thermo/state-vs-path-functions', 'eng-thermo', 1, 'Are heat and work state (point) functions or path functions, and what does that mean?', 'Path functions: their amounts depend on the process path, not just the end states. Write δQ and δW, and Q₁₂ or W₁₂, never ΔQ or ΔW.
Properties (P, T, v, u, h, s) are state functions: ΔU depends only on the end states, so ∮dU = 0 over a cycle, while the net work of a cycle generally isn''t zero.', null, '{}'::text[]),
  ('eng-thermo/first-law-closed-system', 'eng-thermo', 2, 'A closed system receives 50 kJ of heat and does 20 kJ of work on its surroundings. What is ΔU (no KE or PE change)?', '+30 kJ.
Sign convention used (Çengel): Q − W = ΔU + ΔKE + ΔPE, with Q = net heat transfer TO the system and W = net work done BY the system: 50 − 20 = 30 kJ.
Many chemistry texts write ΔU = Q + W with W done ON the system: same physics, opposite sign on W.', '30 kJ', array['30', '+30 kJ', '+30']::text[]),
  ('eng-thermo/saturated-mixture-quality', 'eng-thermo', 3, 'What is the quality x of a saturated liquid–vapor mixture, and how do you find it from the specific volume v?', 'x = m_vapor/m_total (0 = saturated liquid, 1 = saturated vapor); it''s defined only under the vapor dome.
v = v_f + x·v_fg, so x = (v − v_f)/(v_g − v_f). Same pattern for u, h and s.
Example, water at 100 °C: v_f = 0.001043, v_g = 1.6720 m³/kg; v = 0.5 m³/kg gives x ≈ 0.30.', null, '{}'::text[]),
  ('eng-thermo/ideal-gas-cp-cv', 'eng-thermo', 4, 'For an ideal gas, what does c_p − c_v equal?', 'R, the specific gas constant (R = R_u/M, with R_u = 8.314 kJ/kmol·K).
Air: R = 0.287, c_p ≈ 1.005 and c_v ≈ 0.718 kJ/kg·K at room temperature, so k = c_p/c_v ≈ 1.4.
Ideal-gas u and h depend on T only: Δu = c_v ΔT and Δh = c_p ΔT for ANY process (constant specific heats), not just constant-volume or constant-pressure ones.', 'R', array['gas constant', 'specific gas constant']::text[]),
  ('eng-thermo/isothermal-boundary-work', 'eng-thermo', 5, 'Boundary work done by an ideal gas expanding isothermally in a closed system from V₁ to V₂?', 'W_b = mRT ln(V₂/V₁) = P₁V₁ ln(V₂/V₁) = mRT ln(P₁/P₂).
It''s ∫P dV with P = mRT/V. In general W_b = area under the process curve on a P–V diagram (constant P: P(V₂ − V₁); 1 kPa·m³ = 1 kJ).
Isothermal ideal gas: ΔU = 0, so Q = W_b.', 'mRT ln(V2/V1)', array['P1V1 ln(V2/V1)', 'nRT ln(V2/V1)', 'nRuT ln(V2/V1)', 'mRT ln(P1/P2)', 'P1V1 ln(P1/P2)', 'PV ln(V2/V1)']::text[]),
  ('eng-thermo/enthalpy-flow-work', 'eng-thermo', 6, 'Why do control-volume (open-system) energy balances use enthalpy h instead of internal energy u?', 'h = u + Pv, and Pv is the flow work (flow energy) needed to push each kilogram of fluid across the boundary.
So each unit mass of flowing fluid carries energy h + V²/2 + gz.
Ideal gas: Δh = c_p ΔT. For a closed system at constant pressure with only boundary work, Q = ΔH.', null, '{}'::text[]),
  ('eng-thermo/nozzle-exit-velocity', 'eng-thermo', 7, 'Air enters an adiabatic nozzle at negligible velocity, and its enthalpy drops by 20 kJ/kg. What is the exit velocity?', '200 m/s.
Steady flow, no work or heat, ΔPE ≈ 0: V₂²/2 = h₁ − h₂ = 20 kJ/kg = 20,000 m²/s², so V₂ = √40,000 = 200 m/s.
Trap: forgetting 1 kJ/kg = 1000 m²/s² gives √40 ≈ 6.3 m/s. A diffuser does the reverse: it slows the flow and raises h and P.', '200 m/s', array['200', '200 m/sec', '200 meters per second']::text[]),
  ('eng-thermo/throttling-valve', 'eng-thermo', 8, 'Across an adiabatic throttling valve (no work, negligible KE and PE change), which property stays constant?', 'Enthalpy: h₁ = h₂ (isenthalpic).
For an ideal gas h = h(T), so T stays constant too. A real fluid such as a refrigerant drops sharply in pressure and temperature, partly flashing to vapor: that''s the expansion valve in a refrigerator.
Entropy increases: throttling is highly irreversible.', 'enthalpy', array['h', 'h1 = h2', 'specific enthalpy', 'enthalpy (h)', 'constant enthalpy']::text[]),
  ('eng-thermo/second-law-statements', 'eng-thermo', 9, 'State the Kelvin–Planck and the Clausius statements of the second law.', 'Kelvin–Planck: no device operating in a cycle can receive heat from a single reservoir and produce a net amount of work, so no heat engine has η_th = 100%.
Clausius: no cyclic device can have, as its sole effect, heat transfer from a colder body to a hotter one, so a refrigerator needs a work input.
The two are equivalent: violating one violates the other.', null, '{}'::text[]),
  ('eng-thermo/carnot-efficiency', 'eng-thermo', 10, 'Maximum possible thermal efficiency of a heat engine operating between reservoirs at 527 °C and 27 °C?', '62.5%.
η_Carnot = 1 − T_L/T_H with ABSOLUTE temperatures: 1 − 300 K/800 K = 0.625.
Trap: plugging in °C gives 1 − 27/527 ≈ 95%. Every real (irreversible) engine between the same two reservoirs does worse.', '62.5%', array['0.625', '62.5', '62.5 percent', '.625']::text[]),
  ('eng-thermo/heat-pump-cop', 'eng-thermo', 11, 'A refrigeration cycle has COP_R = 3. What is its COP when the same cycle (same Q_L, Q_H, W) is used as a heat pump?', '4.
COP_R = Q_L/W_in and COP_HP = Q_H/W_in = (Q_L + W_in)/W_in = COP_R + 1.
COPs above 1 are normal; COP isn''t an efficiency. Reversible (Carnot) limits, with absolute temperatures: COP_R = T_L/(T_H − T_L) and COP_HP = T_H/(T_H − T_L).', '4', array['four', '4.0']::text[]),
  ('eng-thermo/entropy-generation-sign', 'eng-thermo', 12, 'An analysis of a proposed process gives entropy generation S_gen < 0. What can you conclude?', 'The process is impossible: it violates the second law.
S_gen > 0: irreversible (every real process); S_gen = 0: reversible (an idealization); S_gen < 0: impossible.
Trap: a system''s own entropy CAN decrease when heat leaves it. Only S_gen, equivalently ΔS of an isolated system, can never be negative.', 'impossible', array['it is impossible', 'it''s impossible', 'impossible process', 'not possible', 'violates the second law', 'violates second law', 'violates the 2nd law']::text[]),
  ('eng-thermo/isentropic-ideal-gas', 'eng-thermo', 13, 'For an ideal gas with constant specific heats undergoing an isentropic process, what combination of P and V stays constant?', 'PVᵏ (equivalently Pvᵏ), with k = c_p/c_v ≈ 1.4 for air.
Also T₂/T₁ = (P₂/P₁)^((k−1)/k) = (v₁/v₂)^(k−1).
Isentropic = reversible AND adiabatic. Trap: PV = constant is the isothermal ideal-gas process, not the isentropic one.', 'PV^k', array['PV^gamma', 'PV^k = constant', 'PV^k = const', 'PV^k = C']::text[]),
  ('eng-thermo/otto-cycle-efficiency', 'eng-thermo', 14, 'Cold-air-standard Otto cycle: thermal efficiency in terms of compression ratio r and specific heat ratio k?', 'η = 1 − 1/r^(k−1).
r = V_max/V_min. Example: r = 8, k = 1.4 gives 1 − 8^(−0.4) ≈ 0.565 (56.5%).
Efficiency rises with r, but real spark-ignition engines can''t raise r much because of engine knock (autoignition of the fuel–air mixture).', '1 - 1/r^(k-1)', array['1-r^(1-k)', '1-1/(r^(k-1))', '1-(1/r)^(k-1)', '1-r^-(k-1)']::text[]),
  ('eng-thermo/rankine-cycle-components', 'eng-thermo', 15, 'List the four components of the ideal Rankine cycle in flow order, with the ideal process in each.', 'Pump (isentropic compression of liquid) → boiler (constant-pressure heat addition) → turbine (isentropic expansion) → condenser (constant-pressure heat rejection).
Pump work is tiny next to turbine work because liquid v is small: w_pump ≈ v(P₂ − P₁).
η_th = w_net/q_in = 1 − q_out/q_in.', null, '{}'::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'eng-thermo' and id not in ('eng-thermo/isolated-system', 'eng-thermo/state-vs-path-functions', 'eng-thermo/first-law-closed-system', 'eng-thermo/saturated-mixture-quality', 'eng-thermo/ideal-gas-cp-cv', 'eng-thermo/isothermal-boundary-work', 'eng-thermo/enthalpy-flow-work', 'eng-thermo/nozzle-exit-velocity', 'eng-thermo/throttling-valve', 'eng-thermo/second-law-statements', 'eng-thermo/carnot-efficiency', 'eng-thermo/heat-pump-cop', 'eng-thermo/entropy-generation-sign', 'eng-thermo/isentropic-ideal-gas', 'eng-thermo/otto-cycle-efficiency', 'eng-thermo/rankine-cycle-components');

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('eng-fluids/specific-gravity', 'eng-fluids', 0, 'A liquid has density 850 kg/m³. What is its specific gravity?', '0.85.
SG = ρ/ρ_water, with ρ_water = 1000 kg/m³ (at 4 °C); it''s dimensionless.
Specific weight is different: γ = ρg, in N/m³. Water: γ ≈ 9.81 kN/m³; this liquid: 850·9.81 ≈ 8.34 kN/m³.', '0.85', array['.85']::text[]),
  ('eng-fluids/no-slip-condition', 'eng-fluids', 1, 'What does the no-slip condition say about a viscous fluid in contact with a solid surface?', 'The fluid sticks to the surface: its velocity relative to the surface is zero (at a stationary wall, u = 0).
This creates the steep velocity gradient near walls (the boundary layer), hence wall shear stress τ_w = μ(du/dy) at the wall, friction drag and pipe head loss.
Inviscid (Bernoulli) analyses can''t satisfy it.', null, '{}'::text[]),
  ('eng-fluids/newtonian-shear-stress', 'eng-fluids', 2, 'Oil (μ = 0.1 Pa·s) fills a 2 mm gap between a fixed wall and a plate moving at 0.4 m/s. Shear stress on the plate (linear profile)?', '20 Pa.
Newton''s law of viscosity: τ = μ du/dy. No-slip makes the velocity go from 0 to 0.4 m/s across the gap: du/dy = 0.4/0.002 = 200 s⁻¹, so τ = 0.1·200 = 20 Pa.
Units: 1 Pa·s = 1 N·s/m² = 1 kg/(m·s). Newtonian fluids (water, air, oils) have τ linear in du/dy.', '20 Pa', array['20', '20 N/m^2', '20 N/m2', '20 pascals', '20 pascal']::text[]),
  ('eng-fluids/kinematic-viscosity', 'eng-fluids', 3, 'Kinematic viscosity ν equals the dynamic viscosity μ divided by what?', 'Density: ν = μ/ρ, in m²/s (1 stoke = 1 cm²/s).
At 20 °C: water ≈ 1.0 × 10⁻⁶ m²/s, air ≈ 1.5 × 10⁻⁵ m²/s. Air''s ν is ~15× water''s even though its μ is ~55× smaller, because air is ~830× less dense.', 'density', array['rho', 'fluid density', 'mass density', 'density of the fluid']::text[]),
  ('eng-fluids/viscosity-vs-temperature', 'eng-fluids', 4, 'As temperature rises, what happens to the viscosity of a liquid, and of a gas?', 'Liquid: decreases. Gas: increases.
Liquid viscosity comes mainly from cohesive forces between molecules, which weaken as the molecules move faster. Gas viscosity comes from molecular collisions carrying momentum between layers, which intensify with temperature.
That''s why motor oil thins out when hot.', null, '{}'::text[]),
  ('eng-fluids/hydrostatic-gauge-pressure', 'eng-fluids', 5, 'What is the gauge pressure at the bottom of a 10 m deep open tank of fresh water?', '≈ 98.1 kPa (gauge).
P = P_atm + ρgh, so P_gauge = ρgh = 1000·9.81·10 = 98,100 Pa. Absolute: ≈ 101.3 + 98.1 = 199.4 kPa at sea level.
P_abs = P_atm + P_gauge; below atmospheric, P_abs = P_atm − P_vac. Pressure depends only on depth, not on the container''s shape.', '98.1 kPa', array['98.1', '98 kPa', '98', '98100 Pa', '98,100 Pa', '98000 Pa', '98.1 kPa gauge', '98.1 kPa gage', '98.1 kPag', '98,000 Pa']::text[]),
  ('eng-fluids/buoyancy-floating-fraction', 'eng-fluids', 6, 'A wooden block of density 600 kg/m³ floats in fresh water. What fraction of its volume is submerged?', '0.6 (60%).
Archimedes: buoyant force = weight of the displaced fluid, F_B = ρ_fluid·g·V_sub, acting up through the centroid of the displaced volume. Floating: F_B = W, so ρ_w·V_sub = ρ_b·V, giving V_sub/V = ρ_b/ρ_w.
Trap: F_B uses the FLUID''s density and the submerged volume, not the body''s.', '0.6', array['.6', '0.60', '60%', '60 percent', '3/5']::text[]),
  ('eng-fluids/center-of-pressure-gate', 'eng-fluids', 7, 'A vertical rectangular gate 3 m tall has its top edge at the water''s free surface. At what depth does the resultant hydrostatic force act?', '2 m deep (2/3 of the height), below the centroid at 1.5 m.
Magnitude uses the centroid depth: F_R = ρg·h_C·A. Location (gauge pressure): y_P = y_C + I_xx,C/(y_C·A) = 1.5 + (b·3³/12)/(1.5·3b) = 2 m.
On any non-horizontal plane surface the center of pressure lies below the centroid, approaching it as the surface goes deeper.', '2 m', array['2', '2 meters', '2 meter', '2 m deep', '2 m below the surface']::text[]),
  ('eng-fluids/continuity-pipe-contraction', 'eng-fluids', 8, 'Water flows at 2 m/s in a 10 cm diameter pipe that narrows to 5 cm diameter. What is the velocity in the narrow section?', '8 m/s.
Incompressible continuity: Q = A₁V₁ = A₂V₂, so V₂ = V₁(D₁/D₂)² = 2·(10/5)² = 8 m/s.
Trap: halving the diameter quarters the area, so the velocity rises 4×, not 2×. For compressible flow, conserve the mass flow rate ṁ = ρAV instead.', '8 m/s', array['8', '8 m/sec']::text[]),
  ('eng-fluids/bernoulli-assumptions', 'eng-fluids', 9, 'What four assumptions must hold to use the Bernoulli equation P/ρ + V²/2 + gz = constant?', '1) Steady flow. 2) Incompressible flow. 3) Negligible friction (viscous effects). 4) Applied along a streamline.
Also: no pump, turbine or heat transfer between the two points.
It fails in boundary layers, in long pipes with friction and across a pump or fan; use the energy equation with head loss h_L instead.', null, '{}'::text[]),
  ('eng-fluids/pitot-static-velocity', 'eng-fluids', 10, 'A Pitot-static tube in air (ρ = 1.2 kg/m³) reads stagnation minus static pressure = 240 Pa. What is the air speed?', '20 m/s.
Bernoulli from the free stream to the stagnation point (V = 0): P₀ = P + ½ρV², so V = √(2(P₀ − P)/ρ) = √(2·240/1.2) = √400 = 20 m/s.
Trap: use the density of the flowing fluid (air), not that of the manometer liquid.', '20 m/s', array['20', '20 m/sec']::text[]),
  ('eng-fluids/reynolds-number-pipe', 'eng-fluids', 11, 'Water (ν = 1.0 × 10⁻⁶ m²/s) flows at 0.1 m/s in a 2 cm diameter pipe. What is the Reynolds number?', '2000, so laminar.
Re = VD/ν = ρVD/μ = (0.1)(0.02)/(10⁻⁶) = 2000: the ratio of inertial to viscous forces.
Circular pipes (Çengel): laminar for Re ≲ 2300, transitional ≈ 2300–4000, turbulent for Re ≳ 4000. These are approximate; transition depends on disturbances, wall roughness and vibration.', '2000', array['2,000', '2e3', '2x10^3', '2*10^3']::text[]),
  ('eng-fluids/laminar-friction-factor', 'eng-fluids', 12, 'Darcy friction factor for fully developed laminar flow in a circular pipe?', 'f = 64/Re.
In laminar flow it doesn''t depend on wall roughness. Trap: the Fanning friction factor is 1/4 of Darcy''s (16/Re), so check which one a chart or formula uses.
Turbulent: f depends on Re and relative roughness ε/D (Colebrook equation or Moody chart).', '64/Re', array['f = 64/Re']::text[]),
  ('eng-fluids/darcy-weisbach-head-loss', 'eng-fluids', 13, 'Darcy–Weisbach equation: head loss h_L in a pipe of length L, diameter D, mean velocity V and friction factor f?', 'h_L = f(L/D)(V²/2g), in meters of fluid; as a pressure drop, ΔP_L = ρg·h_L = f(L/D)(ρV²/2).
Valid for laminar and turbulent flow. Laminar (f = 64/Re): h_L ∝ V. Fully rough turbulent (f constant): h_L ∝ V².
At a fixed flow rate in fully rough flow, h_L ∝ 1/D⁵: a slightly bigger pipe cuts losses a lot.', null, '{}'::text[]),
  ('eng-fluids/hydraulic-diameter', 'eng-fluids', 14, 'What is the hydraulic diameter of a noncircular duct, and what does it reduce to for a circular pipe and for a square duct of side a?', 'D_h = 4A_c/p, where A_c is the flow area and p the wetted perimeter.
Circle: 4(πD²/4)/(πD) = D. Square: 4a²/(4a) = a.
Use D_h in place of D in Re and the Darcy–Weisbach equation. Laminar flow in noncircular ducts has its own f·Re value (≈ 57 for a square duct instead of 64).', null, '{}'::text[]),
  ('eng-fluids/drag-force-scaling', 'eng-fluids', 15, 'Drag force F_D = ½ρV²·C_D·A. If the speed doubles with C_D unchanged, by what factor does the drag force change?', '4× (it quadruples).
F_D ∝ V², and the power needed to overcome drag, F_D·V, rises 8×.
A is the frontal area for blunt bodies (cars, spheres) but the planform area for wings and plates parallel to the flow. C_D itself varies with Re, so the V² scaling assumes C_D stays roughly constant.', '4', array['4x', 'x4', '4 times', 'four', 'four times', 'quadruples', 'quadruple', 'quadrupled', 'factor of 4']::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'eng-fluids' and id not in ('eng-fluids/specific-gravity', 'eng-fluids/no-slip-condition', 'eng-fluids/newtonian-shear-stress', 'eng-fluids/kinematic-viscosity', 'eng-fluids/viscosity-vs-temperature', 'eng-fluids/hydrostatic-gauge-pressure', 'eng-fluids/buoyancy-floating-fraction', 'eng-fluids/center-of-pressure-gate', 'eng-fluids/continuity-pipe-contraction', 'eng-fluids/bernoulli-assumptions', 'eng-fluids/pitot-static-velocity', 'eng-fluids/reynolds-number-pipe', 'eng-fluids/laminar-friction-factor', 'eng-fluids/darcy-weisbach-head-loss', 'eng-fluids/hydraulic-diameter', 'eng-fluids/drag-force-scaling');

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('eng-digital-logic/binary-to-hex', 'eng-digital-logic', 0, 'Convert the binary number 11010110 to hexadecimal.', 'D6 (= 214 in decimal).
Group the bits in fours starting from the binary point: 1101 0110 → D, 6. Pad the leftmost group with leading zeros if needed.
Check: 13·16 + 6 = 214 = 128 + 64 + 16 + 4 + 2.', 'D6', array['0xD6', 'D6h', 'D6 hex', 'D6_16', '(D6)16']::text[]),
  ('eng-digital-logic/twos-complement-negation', 'eng-digital-logic', 1, 'What is −6 in 8-bit two''s complement?', '1111 1010.
Negate by inverting every bit and adding 1: +6 = 0000 0110 → 1111 1001 → 1111 1010.
Shortcut: copy the bits from the right up to and including the first 1, then invert the rest. Check: −128 + 122 = −6.', '11111010', array['0xFA', 'FA']::text[]),
  ('eng-digital-logic/twos-complement-range', 'eng-digital-logic', 2, 'What range of integers can an 8-bit two''s complement number represent?', '−128 to +127.
n bits: −2ⁿ⁻¹ to 2ⁿ⁻¹ − 1. There''s one more negative value because zero uses a ''positive'' pattern; −128 = 1000 0000 has no positive partner (negating it gives itself).
Unsigned 8-bit: 0 to 255. Sign-magnitude and 1''s complement: −127 to +127 (they have two zeros).', '-128 to 127', array['-128 to +127', '-128 through 127', '-128..127', '[-128, 127]', '-128, 127', '-2^7 to 2^7-1']::text[]),
  ('eng-digital-logic/twos-complement-overflow', 'eng-digital-logic', 3, 'When adding two n-bit two''s complement numbers, how do you detect overflow?', 'Overflow occurs when both operands have the same sign but the sum''s sign bit differs. Hardware test: V = C_n ⊕ C_(n−1), i.e., the carry out of the MSB differs from the carry into it.
Adding numbers of opposite signs can never overflow.
Example, 4 bits: 0111 + 0001 = 1000, i.e., 7 + 1 → −8. The final carry-out alone does NOT indicate signed overflow.', null, '{}'::text[]),
  ('eng-digital-logic/de-morgan-product', 'eng-digital-logic', 4, 'By De Morgan''s theorem, the complement of a product, (AB)′, equals what?', 'A′ + B′.
Break the bar and change the operator: (AB)′ = A′ + B′ and (A + B)′ = A′B′. Works for any number of variables.
So a NAND gate is equivalent to an OR gate with inverted (bubbled) inputs, and a NOR gate to an AND gate with bubbled inputs.', 'A''+B''', array['B''+A''', '~A+~B', '!A+!B', 'A'' or B''', 'not A or not B', '(A''+B'')']::text[]),
  ('eng-digital-logic/nand-only-or-gate', 'eng-digital-logic', 5, 'What is the minimum number of 2-input NAND gates needed to build a 2-input OR gate?', '3.
A + B = (A′B′)′: two NANDs with tied inputs make A′ and B′, and a third NAND combines them.
NOT takes 1 NAND and AND takes 2, so NAND alone can build any Boolean function: it''s a universal gate. NOR is universal too (by duality).', '3', array['three']::text[]),
  ('eng-digital-logic/even-parity-bit', 'eng-digital-logic', 6, 'What even-parity bit should be appended to the 7-bit data word 1011001?', '0.
Even parity makes the total number of 1s even. The data already has four 1s, so P = 1⊕0⊕1⊕1⊕0⊕0⊕1 = 0.
A multi-input XOR outputs 1 when an odd number of its inputs are 1, which is why XOR trees generate and check parity. One parity bit detects any single-bit error, but not a double one.', '0', array['zero']::text[]),
  ('eng-digital-logic/minterm-simplification', 'eng-digital-logic', 7, 'Simplify F(A, B, C) = Σm(1, 3, 5, 7) to a minimal sum of products.', 'F = C.
Minterms 1, 3, 5, 7 (001, 011, 101, 111) are exactly the rows where C = 1; A and B take every value, so they drop out.
Minterm mᵢ is a product term equal to 1 only in row i; maxterm Mᵢ is a sum term equal to 0 only in row i, and Mᵢ = mᵢ′. Same function in POS form: F = ΠM(0, 2, 4, 6).', 'C', array['F = C']::text[]),
  ('eng-digital-logic/karnaugh-map-grouping', 'eng-digital-logic', 8, 'What are the rules for grouping 1s on a Karnaugh map to get a minimal sum of products?', 'Groups must be rectangles of 1, 2, 4, 8… cells (powers of 2). Adjacency wraps around the map''s edges (Gray-code order 00, 01, 11, 10).
Make each group as large as possible and use as few groups as possible; groups may overlap; every 1 must be covered.
Don''t-cares (X) may be included when they enlarge a group. A group of 2ᵏ cells eliminates k variables.', null, '{}'::text[]),
  ('eng-digital-logic/full-adder-equations', 'eng-digital-logic', 9, 'Full adder with inputs A, B and C_in: what are the Boolean expressions for the sum S and the carry C_out?', 'S = A ⊕ B ⊕ C_in; C_out = AB + C_in(A ⊕ B), equivalent to the majority function AB + AC_in + BC_in.
It can be built from two half adders (each: S = A ⊕ B, C = AB) plus an OR gate on their carries.
Chaining n full adders makes an n-bit ripple-carry adder.', null, '{}'::text[]),
  ('eng-digital-logic/mux-select-lines', 'eng-digital-logic', 10, 'How many select lines does a 16-to-1 multiplexer need?', '4, since 2⁴ = 16: n select lines choose one of 2ⁿ data inputs.
A 2ⁿ-to-1 mux can implement any n-variable function by wiring the truth-table outputs to its data inputs.
Compare a decoder: n inputs, 2ⁿ outputs, each output one minterm, so a decoder plus an OR gate also implements any function.', '4', array['four']::text[]),
  ('eng-digital-logic/sr-latch-forbidden-input', 'eng-digital-logic', 11, 'In an SR latch built from NOR gates, which input combination is not allowed, and why?', 'S = R = 1.
It forces both Q and Q′ to 0, so they''re no longer complements; if S and R then return to 0 together, the next state is unpredictable (a race).
NAND (S′R′) latch: the forbidden input is S′ = R′ = 0. The JK flip-flop removes the problem: J = K = 1 toggles.', null, '{}'::text[]),
  ('eng-digital-logic/jk-flip-flop-equation', 'eng-digital-logic', 12, 'Characteristic equation of a JK flip-flop: Q(t+1) = ?', 'Q(t+1) = JQ′ + K′Q.
JK = 00 hold, 10 set, 01 reset, 11 toggle.
Compare D: Q(t+1) = D (it just stores the input at the clock edge), and T: Q(t+1) = T ⊕ Q.', 'JQ''+K''Q', array['K''Q+JQ''', 'JQ''+QK''', 'QK''+JQ''', 'Q''J+K''Q', 'Q''J+QK''']::text[]),
  ('eng-digital-logic/setup-and-hold-time', 'eng-digital-logic', 13, 'Flip-flop timing: what are setup time and hold time?', 'Setup time: how long the input must be stable BEFORE the active clock edge. Hold time: how long it must stay stable AFTER the edge.
Violating either can make the flip-flop metastable.
Setup limits clock speed: T_clk ≥ t_clk-to-Q + t_logic,max + t_setup. Hold is checked on the shortest path: t_clk-to-Q + t_logic,min ≥ t_hold.', null, '{}'::text[]),
  ('eng-digital-logic/moore-vs-mealy', 'eng-digital-logic', 14, 'In which type of finite-state machine do the outputs depend only on the present state, not on the current inputs?', 'Moore machine.
Mealy: outputs depend on the present state AND the inputs, so they can react within the same clock cycle and often need fewer states, but they can glitch when inputs change.
In a Moore state diagram the outputs are written inside the states; in a Mealy diagram, on the transitions (input/output).', 'Moore', array['Moore machine', 'Moore model', 'Moore FSM']::text[]),
  ('eng-digital-logic/counter-flip-flop-count', 'eng-digital-logic', 15, 'Minimum number of flip-flops needed for a mod-10 (decade) counter?', '4.
n flip-flops have 2ⁿ states: 2³ = 8 < 10 ≤ 16 = 2⁴, so n = ⌈log₂ 10⌉ = 4.
A BCD counter counts 0000 to 1001 and returns to 0000 on the next clock; 6 of its 16 states (1010–1111) are unused. A mod-N counter divides the clock frequency by N.', '4', array['four']::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'eng-digital-logic' and id not in ('eng-digital-logic/binary-to-hex', 'eng-digital-logic/twos-complement-negation', 'eng-digital-logic/twos-complement-range', 'eng-digital-logic/twos-complement-overflow', 'eng-digital-logic/de-morgan-product', 'eng-digital-logic/nand-only-or-gate', 'eng-digital-logic/even-parity-bit', 'eng-digital-logic/minterm-simplification', 'eng-digital-logic/karnaugh-map-grouping', 'eng-digital-logic/full-adder-equations', 'eng-digital-logic/mux-select-lines', 'eng-digital-logic/sr-latch-forbidden-input', 'eng-digital-logic/jk-flip-flop-equation', 'eng-digital-logic/setup-and-hold-time', 'eng-digital-logic/moore-vs-mealy', 'eng-digital-logic/counter-flip-flop-count');

