-- Software
insert into public.packs (id, category_id, title, course, description, position) values
  ('sw-data-structures', 'software', 'Big-O & Data Structures', 'Data Structures', 'O/Ω/Θ, array inserts and amortized appends, linked lists, stacks and queues, hash tables, BSTs vs AVL/red-black, heaps, tries, graphs, union–find.', 0),
  ('sw-algorithms', 'software', 'Core Algorithms', 'Algorithms', 'Sorting trade-offs and the n log n lower bound, master theorem, BFS/DFS, topological sort, Dijkstra, Bellman–Ford, Floyd–Warshall, MSTs, DP vs greedy.', 1),
  ('sw-git', 'software', 'Git Essentials', 'Software Tools', 'Staging and diffs, branches, fast-forward vs merge commits, conflicts, merge vs rebase, fetch vs pull, stash, amend, reset modes, revert, cherry-pick, reflog.', 2),
  ('sw-sql', 'software', 'SQL & Databases', 'Databases', 'Clause order, WHERE vs HAVING, joins, keys, NULL traps, UNION ALL, ACID, isolation levels, B-tree indexes, normal forms, SQL injection, CAP theorem.', 3),
  ('sw-web', 'software', 'HTTP & the Web', 'Web Development', 'Safe vs idempotent methods, key status codes, TLS and ports, DNS, TCP vs UDP, cookie flags, CORS preflight, REST, caching, XSS vs CSRF, JWTs.', 4),
  ('sw-oop', 'software', 'OOP & Design Principles', 'Software Engineering', 'Encapsulation, polymorphism, overloading vs overriding, interfaces vs abstract classes, all five SOLID principles, key GoF patterns, test levels, and TDD.', 5),
  ('sw-os', 'software', 'Operating Systems', 'Operating Systems', 'Processes vs threads, process states, fork(), system calls, CPU scheduling, race conditions, mutexes and semaphores, deadlock, paging, TLBs, page replacement.', 6)
on conflict (id) do update set category_id = excluded.category_id, title = excluded.title, course = excluded.course, description = excluded.description, position = excluded.position;

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('sw-data-structures/asymptotic-notation', 'sw-data-structures', 0, 'Big-O, Big-Ω, Big-Θ: which is an upper bound, which a lower bound, and which a tight bound?', 'O = upper bound: f(n) ≤ c·g(n) for all n ≥ n₀ (some c > 0). Ω = lower bound: f(n) ≥ c·g(n). Θ = tight: f is both O(g) and Ω(g).
Traps: O needn''t be tight (5n + 3 = O(n²) is true), and O doesn''t mean worst case; any case can get an O, Ω, or Θ bound.', null, '{}'::text[]),
  ('sw-data-structures/array-middle-insert', 'sw-data-structures', 1, 'Worst-case time to insert a value at an arbitrary index of an array that holds n elements?', 'O(n).
Every element after the insertion point shifts one slot right; inserting at index 0 moves all n. Contrast: reading or overwriting a[i] is O(1), because its address is computed directly as base + i·size.', 'O(n)', array['n', 'Theta(n)', 'linear', 'linear time']::text[]),
  ('sw-data-structures/dynamic-array-append', 'sw-data-structures', 2, 'Amortized time per append on a dynamic array that doubles its capacity whenever it fills up?', 'O(1) amortized, even though an append that triggers a resize costs O(n).
Doubling means n appends copy fewer than 2n elements in total. Any constant growth factor > 1 works (Java''s ArrayList grows 1.5×); growing by a fixed +k slots makes appends O(n) amortized.', 'O(1)', array['1', 'constant', 'constant time', 'O(1) amortized', 'amortized O(1)', 'Theta(1)']::text[]),
  ('sw-data-structures/linked-list-insert-search', 'sw-data-structures', 3, 'Singly linked list with only a head pointer: time to insert at the front, and to search for a value?', 'Insert at front: O(1); just point the new node at the old head. Search: O(n); you must walk node by node.
Even a sorted linked list can''t be binary-searched efficiently: there''s no O(1) access to the middle node.', null, '{}'::text[]),
  ('sw-data-structures/stack-vs-queue', 'sw-data-structures', 4, 'Stack vs queue: what removal order does each follow, and what do push/pop and enqueue/dequeue cost?', 'Stack: LIFO (last in, first out), push and pop at the top. Queue: FIFO (first in, first out), enqueue at the back, dequeue at the front. All O(1).
Trap: a queue on a plain array that shifts every element on dequeue makes dequeue O(n); use a circular buffer or a linked list with a tail pointer.', null, '{}'::text[]),
  ('sw-data-structures/hash-load-factor', 'sw-data-structures', 5, 'A hash table stores n keys in m buckets (slots). What is its load factor α?', 'α = n/m, the average number of keys per bucket.
Implementations resize when α passes a threshold (0.75 in Java''s HashMap): allocate more buckets and rehash every key in O(n), so average operations stay O(1).', 'n/m', array['keys/buckets', 'keys/slots', 'alpha = n/m', 'α = n/m']::text[]),
  ('sw-data-structures/hash-search-average-vs-worst', 'sw-data-structures', 6, 'Hash table with chaining: average-case vs worst-case search time, and what causes the worst case?', 'Average: Θ(1 + α) under simple uniform hashing, i.e. O(1) while the load factor α stays bounded. Worst: Θ(n), when all n keys hash to the same bucket (a poor hash function or adversarial keys).
So ''hash lookups are O(1)'' is an average-case claim.', null, '{}'::text[]),
  ('sw-data-structures/chaining-vs-open-addressing', 'sw-data-structures', 7, 'How does chaining differ from open addressing in resolving hash collisions?', 'Chaining: each bucket holds a list of all keys that hash there, so α can exceed 1. Open addressing: every key lives in the table array itself; on a collision, probe other slots (linear, quadratic, double hashing), so α ≤ 1 and should stay well below it.
Open-addressing deletes need a ''deleted'' marker (tombstone) so later searches don''t stop early.', null, '{}'::text[]),
  ('sw-data-structures/bst-unbalanced-worst-case', 'sw-data-structures', 8, 'Worst-case time to search a binary search tree with n nodes when the tree isn''t kept balanced?', 'O(n).
BST operations take O(h) for tree height h. Inserting keys in sorted order builds a degenerate chain with h = n − 1. Randomly built BSTs have expected height O(log n), but that''s not a guarantee.', 'O(n)', array['n', 'Theta(n)', 'linear', 'linear time']::text[]),
  ('sw-data-structures/balanced-bst-guarantee', 'sw-data-structures', 9, 'What worst-case time do AVL and red-black trees guarantee for search, insert, and delete with n keys?', 'O(log n) worst case, because rotations keep the height logarithmic.
AVL: every node''s two subtree heights differ by at most 1. Red-black: the coloring rules guarantee height ≤ 2·log₂(n + 1). AVL is more rigidly balanced; red-black does less rebalancing (≤ 2 rotations per insert, ≤ 3 per delete).', 'O(log n)', array['log n', 'O(lg n)', 'lg n', 'Theta(log n)', 'O(log2 n)', 'O(log(n))', 'log(n)']::text[]),
  ('sw-data-structures/binary-heap-operations', 'sw-data-structures', 10, 'Binary min-heap with n elements: worst-case time for insert, extract-min, and peeking at the minimum?', 'Insert: O(log n), append at the end and sift up. Extract-min: O(log n), move the last element to the root and sift down. Peek: O(1), the minimum is always at the root.
The tree is complete, so its height is ⌊log₂ n⌋. Searching for an arbitrary key is still O(n).', null, '{}'::text[]),
  ('sw-data-structures/heap-left-child-index', 'sw-data-structures', 11, 'In a 0-indexed array storing a binary heap, what is the index of the left child of the node at index i?', '2i + 1. Right child: 2i + 2; parent: ⌊(i − 1)/2⌋.
CLRS uses 1-indexed arrays instead: left 2i, right 2i + 1, parent ⌊i/2⌋. Always check which convention a question uses.', '2i+1', array['1+2i', 'i*2+1']::text[]),
  ('sw-data-structures/build-heap-linear', 'sw-data-structures', 12, 'Time to build a binary heap from an unsorted array of n elements with bottom-up heapify (sift down from the last parent to the root)?', 'O(n), not O(n log n).
Most nodes sit near the bottom and sift down only a few levels: at most ⌈n/2^(h+1)⌉ nodes have height h, and Σ h/2^h converges, so the total is O(n). Inserting the n elements one at a time costs O(n log n) in the worst case.', 'O(n)', array['n', 'Theta(n)', 'linear', 'linear time']::text[]),
  ('sw-data-structures/trie-lookup', 'sw-data-structures', 13, 'Time to look up a key of length L in a trie (prefix tree) that holds n keys?', 'O(L), independent of n, assuming O(1) child lookup per character (e.g. an array indexed by letter).
Tries make prefix queries like autocomplete fast; the cost is memory, since every node stores child pointers.', 'O(L)', array['L', 'Theta(L)']::text[]),
  ('sw-data-structures/adjacency-list-vs-matrix', 'sw-data-structures', 14, 'Space needed for a graph with V vertices and E edges: adjacency list vs adjacency matrix?', 'List: Θ(V + E). Matrix: Θ(V²).
A matrix answers ''is (u, v) an edge?'' in O(1) but wastes space on sparse graphs. A list makes iterating u''s neighbors O(deg u), which is why BFS and DFS run in O(V + E) on lists but O(V²) on a matrix.', null, '{}'::text[]),
  ('sw-data-structures/union-find-complexity', 'sw-data-structures', 15, 'Union–find (disjoint sets) with union by rank and path compression: amortized time per operation on n elements?', 'O(α(n)) amortized, where α is the inverse Ackermann function; α(n) ≤ 4 for any practical n, so it''s effectively constant.
With neither optimization, trees can degenerate into chains and a find costs O(n).', 'O(alpha(n))', array['alpha(n)', 'O(α(n))', 'α(n)', 'inverse ackermann', 'inverse ackermann function', 'O(inverse ackermann)']::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'sw-data-structures' and id not in ('sw-data-structures/asymptotic-notation', 'sw-data-structures/array-middle-insert', 'sw-data-structures/dynamic-array-append', 'sw-data-structures/linked-list-insert-search', 'sw-data-structures/stack-vs-queue', 'sw-data-structures/hash-load-factor', 'sw-data-structures/hash-search-average-vs-worst', 'sw-data-structures/chaining-vs-open-addressing', 'sw-data-structures/bst-unbalanced-worst-case', 'sw-data-structures/balanced-bst-guarantee', 'sw-data-structures/binary-heap-operations', 'sw-data-structures/heap-left-child-index', 'sw-data-structures/build-heap-linear', 'sw-data-structures/trie-lookup', 'sw-data-structures/adjacency-list-vs-matrix', 'sw-data-structures/union-find-complexity');

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('sw-algorithms/merge-sort-profile', 'sw-algorithms', 0, 'Merge sort on n elements: worst-case time, extra space, and is it stable?', 'Θ(n log n) in every case (best, average, worst); Θ(n) auxiliary space for merging arrays; stable, as long as ties are taken from the left half first.
That extra memory is its main drawback, which is why in-place sorts like quicksort and heapsort exist.', null, '{}'::text[]),
  ('sw-algorithms/quicksort-worst-case', 'sw-algorithms', 1, 'Worst-case running time of quicksort with a fixed pivot position (e.g. always the last element)?', 'O(n²): every partition is maximally unbalanced (sizes n − 1 and 0), e.g. already-sorted input with a last-element pivot.
The average case is O(n log n). It sorts in place but isn''t stable. Random pivots make the worst case unlikely, not impossible.', 'O(n^2)', array['n^2', 'Theta(n^2)', 'O(n2)', 'n2', 'O(n*n)', 'quadratic']::text[]),
  ('sw-algorithms/heapsort-in-place', 'sw-algorithms', 2, 'Among the classic textbook sorts, which guarantees O(n log n) worst-case time with only O(1) extra space?', 'Heapsort.
Build a max-heap in O(n), then n − 1 times swap the root (the max) to the end of the array and sift down, O(log n) each. Downsides: not stable and cache-unfriendly, so quicksort is usually faster in practice.', 'heapsort', array['heap-sort']::text[]),
  ('sw-algorithms/insertion-sort-sorted-input', 'sw-algorithms', 3, 'Running time of insertion sort on an array of n elements that is already sorted?', 'Θ(n): each element is compared once with its predecessor and stays put.
In general it runs in Θ(n + d), where d is the number of inversions, so nearly sorted input is near-linear; reverse-sorted input is the Θ(n²) worst case.', 'O(n)', array['n', 'Theta(n)', 'linear', 'linear time']::text[]),
  ('sw-algorithms/comparison-sort-lower-bound', 'sw-algorithms', 4, 'Lower bound on the worst-case number of comparisons for any comparison-based sort of n elements?', 'Ω(n log n).
Model the sort as a binary decision tree: it needs at least n! leaves (one per input ordering), so its height is at least log₂(n!) = Θ(n log n). Counting and radix sort beat it only because they don''t compare keys.', 'Omega(n log n)', array['n log n', 'Omega(n lg n)', 'n lg n', 'Ω(n log n)', 'Ω(n lg n)', 'log(n!)', 'lg(n!)', 'Omega(n log(n))', 'Ω(n log(n))', 'n log(n)']::text[]),
  ('sw-algorithms/counting-sort', 'sw-algorithms', 5, 'Counting sort on n integers in the range 0 to k: running time, and when does it beat comparison sorts?', 'Θ(n + k) time and Θ(n + k) extra space, and it''s stable. It beats Θ(n log n) when k = O(n).
Radix sort runs a stable counting sort on each digit, least significant first: d digits in base b take Θ(d·(n + b)).', null, '{}'::text[]),
  ('sw-algorithms/master-theorem-example', 'sw-algorithms', 6, 'Solve T(n) = 2T(n/2) + Θ(n) with the master theorem.', 'Θ(n log n).
a = 2, b = 2, so n^(log_b a) = n. f(n) = Θ(n) matches it exactly (case 2), giving Θ(n log n). This is merge sort''s recurrence: log n levels of recursion, Θ(n) work per level.', 'Theta(n log n)', array['n log n', 'O(n log n)', 'n lg n', 'Theta(n lg n)', 'O(n lg n)', 'Theta(n log(n))', 'O(n log(n))', 'n log(n)']::text[]),
  ('sw-algorithms/bfs-unweighted-shortest-paths', 'sw-algorithms', 7, 'Which graph traversal finds shortest paths (fewest edges) from a source in an unweighted graph in O(V + E)?', 'Breadth-first search (BFS).
Its FIFO queue finishes each distance layer before starting the next, so every vertex is first discovered via a shortest path. DFS gives no such guarantee. For non-negative edge weights, use Dijkstra instead.', 'BFS', array['breadth-first search', 'breadth first search', 'breadth-first', 'breadth first']::text[]),
  ('sw-algorithms/dfs-cycle-detection', 'sw-algorithms', 8, 'How does depth-first search detect a cycle in a directed graph?', 'It finds a back edge: an edge u → v where v is gray (discovered but not finished, i.e. still on the recursion stack). Edges to black (finished) vertices don''t imply a cycle.
Runs in O(V + E). In an undirected graph, any edge to an already-visited vertex other than the parent signals a cycle.', null, '{}'::text[]),
  ('sw-algorithms/topological-sort-dag', 'sw-algorithms', 9, 'A topological ordering of a directed graph exists if and only if the graph is what kind of graph?', 'A DAG (directed acyclic graph): a cycle would force some vertex to come before itself.
Two O(V + E) methods: DFS, listing vertices in decreasing finish time, or Kahn''s algorithm, repeatedly removing a vertex with in-degree 0.', 'DAG', array['directed acyclic graph', 'acyclic', 'acyclic graph', 'directed acyclic']::text[]),
  ('sw-algorithms/dijkstra-negative-edges', 'sw-algorithms', 10, 'Dijkstra''s shortest-path algorithm can give wrong answers when a graph contains what kind of edges?', 'Negative-weight edges.
Dijkstra permanently finalizes the closest unvisited vertex, assuming no later path can be shorter; a negative edge breaks that. With a binary-heap priority queue it runs in O((V + E) log V).', 'negative', array['negative weight', 'negative-weight', 'negative weights', 'negative edges', 'negative edge', 'negative-weight edges', 'negative weight edges', 'negative edge weights', 'negatively weighted']::text[]),
  ('sw-algorithms/bellman-ford-time', 'sw-algorithms', 11, 'Running time of Bellman–Ford single-source shortest paths on a graph with V vertices and E edges?', 'O(VE): relax every edge V − 1 times.
It handles negative edge weights, and one extra pass that still improves some distance proves that a negative-weight cycle is reachable from the source.', 'O(VE)', array['VE', 'O(EV)', 'EV', 'Theta(VE)', 'O(|V||E|)']::text[]),
  ('sw-algorithms/floyd-warshall-time', 'sw-algorithms', 12, 'Running time of the Floyd–Warshall all-pairs shortest-paths algorithm on a graph with V vertices?', 'Θ(V³): three nested loops over an intermediate vertex k, then i, then j, applying dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]).
It allows negative edges; a negative cycle shows up as dist[i][i] < 0.', 'O(V^3)', array['V^3', 'Theta(V^3)', 'O(V3)', 'O(n^3)', 'n^3', 'O(|V|^3)']::text[]),
  ('sw-algorithms/kruskal-vs-prim', 'sw-algorithms', 13, 'Kruskal''s vs Prim''s minimum spanning tree algorithms: how does each grow the tree?', 'Kruskal: sort all edges by weight; add the lightest edge that doesn''t create a cycle, checked with union–find. O(E log V).
Prim: grow one tree from a start vertex, always adding the lightest edge leaving it, via a priority queue. O(E log V) with a binary heap.
Both are greedy and rely on the cut property.', null, '{}'::text[]),
  ('sw-algorithms/dp-requirements', 'sw-algorithms', 14, 'What two properties must a problem have for dynamic programming to pay off?', 'Optimal substructure: an optimal solution is built from optimal solutions to subproblems. Overlapping subproblems: the same subproblems recur, so storing their results (memoization or a bottom-up table) avoids recomputation.
Without the overlap, plain divide and conquer (like merge sort) is enough.', null, '{}'::text[]),
  ('sw-algorithms/greedy-choice-property', 'sw-algorithms', 15, 'Besides optimal substructure, what property must a problem have for a greedy algorithm to be optimal?', 'The greedy-choice property: some optimal solution begins with the locally best choice, so committing to it never has to be undone.
Counterexample: coins {1, 3, 4} and amount 6. Greedy takes 4 + 1 + 1 (3 coins), but 3 + 3 uses only 2.', null, '{}'::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'sw-algorithms' and id not in ('sw-algorithms/merge-sort-profile', 'sw-algorithms/quicksort-worst-case', 'sw-algorithms/heapsort-in-place', 'sw-algorithms/insertion-sort-sorted-input', 'sw-algorithms/comparison-sort-lower-bound', 'sw-algorithms/counting-sort', 'sw-algorithms/master-theorem-example', 'sw-algorithms/bfs-unweighted-shortest-paths', 'sw-algorithms/dfs-cycle-detection', 'sw-algorithms/topological-sort-dag', 'sw-algorithms/dijkstra-negative-edges', 'sw-algorithms/bellman-ford-time', 'sw-algorithms/floyd-warshall-time', 'sw-algorithms/kruskal-vs-prim', 'sw-algorithms/dp-requirements', 'sw-algorithms/greedy-choice-property');

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('sw-git/init-vs-clone', 'sw-git', 0, 'git init vs git clone <url>: what does each one do?', 'git init creates a new, empty repository (a .git directory) in the current folder.
git clone copies an existing repository with its full history, sets up a remote named origin pointing at the source, and checks out the default branch.', null, '{}'::text[]),
  ('sw-git/git-add-staging', 'sw-git', 1, 'Which command stages a file''s current changes so they''re included in the next commit?', 'git add <path>.
The staging area (index) is a snapshot of what the next commit will contain; git commit records only what''s staged. git status shows staged vs unstaged changes, and git add -p stages individual hunks.', 'git add', array['add', 'git add <file>', 'git add file', 'git add filename', 'git stage']::text[]),
  ('sw-git/diff-staged', 'sw-git', 2, 'Which command shows the changes you''ve staged but not yet committed?', 'git diff --staged (synonym: --cached) compares the index with HEAD.
Plain git diff compares the working tree with the index, so it shows only unstaged changes; git diff HEAD shows both together.', 'git diff --staged', array['git diff --cached']::text[]),
  ('sw-git/gitignore-tracked-file', 'sw-git', 3, 'A file is already tracked by Git. Does adding its name to .gitignore stop Git from tracking changes to it?', 'No. .gitignore only affects untracked files.
Stop tracking it while keeping it on disk with git rm --cached <file>, then commit. Typical case: an accidentally committed .env file or build folder.', 'No', '{}'::text[]),
  ('sw-git/create-and-switch-branch', 'sw-git', 4, 'One command to create a new branch named feature and switch to it?', 'git switch -c feature (older equivalent: git checkout -b feature).
git branch feature only creates the branch; you stay where you are. Move between existing branches with git switch <name>.', 'git switch -c feature', array['git checkout -b feature', 'git switch --create feature']::text[]),
  ('sw-git/fast-forward-merge', 'sw-git', 5, 'When does git merge fast-forward instead of creating a merge commit?', 'When the current branch''s tip is an ancestor of the branch being merged (your branch has no commits the other branch lacks): Git just moves the branch pointer forward.
If both sides have new commits, Git creates a merge commit with two parents. --no-ff forces a merge commit even when a fast-forward is possible.', null, '{}'::text[]),
  ('sw-git/merge-conflict-markers', 'sw-git', 6, 'In a merge conflict, what do the sections between <<<<<<<, =======, and >>>>>>> contain?', '<<<<<<< HEAD to =======: your current branch''s version. ======= to >>>>>>> other: the incoming branch''s version.
Edit to the final content, delete every marker, git add the file, then git commit (or git merge --continue). During a rebase the sides swap: HEAD is the branch you''re rebasing onto.', null, '{}'::text[]),
  ('sw-git/merge-vs-rebase', 'sw-git', 7, 'Merge vs rebase: how does each integrate another branch''s work, and what''s the golden rule of rebasing?', 'Merge ties the histories together with a merge commit; existing commits are untouched. Rebase replays your commits on top of the other branch as new commits with new hashes, giving a linear history.
Golden rule: never rebase commits others already have (pushed, shared); it rewrites history they''ve built on.', null, '{}'::text[]),
  ('sw-git/fetch-vs-pull', 'sw-git', 8, 'Which command downloads new commits from a remote without changing your current branch or working tree?', 'git fetch. It only updates remote-tracking branches such as origin/main.
git pull = git fetch, then integrate the fetched commits into your current branch by fast-forward, merge, or rebase (--rebase or the pull.rebase setting). Fetch first if you want to inspect before integrating.', 'git fetch', array['fetch', 'git fetch origin']::text[]),
  ('sw-git/stash-pop', 'sw-git', 9, 'Command to reapply your most recently stashed changes and remove that entry from the stash list?', 'git stash pop.
git stash apply reapplies but keeps the entry. If pop hits a conflict, the entry is kept; remove it with git stash drop after resolving. git stash -u also stashes untracked files.', 'git stash pop', array['stash pop']::text[]),
  ('sw-git/commit-amend', 'sw-git', 10, 'Command that replaces your most recent commit, e.g. to fix its message or add a forgotten staged file?', 'git commit --amend.
It creates a new commit (new hash) that replaces the old one. Fine before pushing; amending a commit that''s already pushed rewrites shared history and requires a force push.', 'git commit --amend', array['commit --amend', 'git commit --amend -m']::text[]),
  ('sw-git/reset-modes', 'sw-git', 11, 'git reset --soft, --mixed, and --hard HEAD~1: what does each do to the index and working tree?', 'All three move the current branch back to HEAD~1.
--soft: index and working tree untouched; the undone commit''s changes stay staged. --mixed (the default): index reset, working tree kept; changes become unstaged. --hard: both reset; uncommitted changes to tracked files are discarded.', null, '{}'::text[]),
  ('sw-git/revert-shared-commit', 'sw-git', 12, 'Safest way to undo a commit that''s already pushed to a shared branch, without rewriting history?', 'git revert <commit>: makes a new commit that applies the inverse of that commit''s changes, so history is preserved and collaborators aren''t disrupted.
git reset instead moves the branch pointer back, rewriting history: fine for local commits, harmful once pushed.', 'git revert', array['git revert <commit>', 'git revert <hash>', 'revert']::text[]),
  ('sw-git/cherry-pick', 'sw-git', 13, 'Command to apply the changes from one specific commit on another branch onto your current branch?', 'git cherry-pick <commit>.
It creates a new commit with the same changes and message but a new hash. Typical use: porting a bug fix from main to a release branch without merging everything else.', 'git cherry-pick', array['git cherry-pick <commit>', 'git cherry-pick <hash>', 'cherry-pick']::text[]),
  ('sw-git/detached-head', 'sw-git', 14, 'What is HEAD, and what does it mean to be in ''detached HEAD'' state?', 'HEAD is the ref for what you have checked out, normally a branch name (HEAD → branch → commit).
Detached: HEAD points straight at a commit, e.g. after git checkout <hash> or checking out a tag. New commits there belong to no branch; run git switch -c <name> before leaving, or they become hard to find.', null, '{}'::text[]),
  ('sw-git/reflog-recovery', 'sw-git', 15, 'After a bad git reset --hard, which command lists where HEAD has recently pointed so you can recover lost commits?', 'git reflog.
It records every recent position of HEAD (HEAD@{0}, HEAD@{1}, …). Recover with git reset --hard HEAD@{1} or git branch rescue <hash>. The reflog is local only, and old entries expire (90 days by default; 30 for unreachable commits).', 'git reflog', array['reflog', 'git reflog show', 'git log -g', 'git log --walk-reflogs']::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'sw-git' and id not in ('sw-git/init-vs-clone', 'sw-git/git-add-staging', 'sw-git/diff-staged', 'sw-git/gitignore-tracked-file', 'sw-git/create-and-switch-branch', 'sw-git/fast-forward-merge', 'sw-git/merge-conflict-markers', 'sw-git/merge-vs-rebase', 'sw-git/fetch-vs-pull', 'sw-git/stash-pop', 'sw-git/commit-amend', 'sw-git/reset-modes', 'sw-git/revert-shared-commit', 'sw-git/cherry-pick', 'sw-git/detached-head', 'sw-git/reflog-recovery');

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('sw-sql/logical-query-order', 'sw-sql', 0, 'Put these clauses in logical processing order: SELECT, ORDER BY, HAVING, FROM, LIMIT, WHERE, GROUP BY.', 'FROM (with JOINs) → WHERE → GROUP BY → HAVING → SELECT → ORDER BY → LIMIT.
That''s why WHERE can''t use a column alias defined in SELECT, but ORDER BY can.', null, '{}'::text[]),
  ('sw-sql/where-vs-having', 'sw-sql', 1, 'Which clause keeps only the groups that meet a condition after aggregation, e.g. departments with more than 5 employees?', 'HAVING, as in GROUP BY dept HAVING COUNT(*) > 5.
WHERE filters individual rows before grouping and can''t contain aggregate functions; HAVING filters whole groups after GROUP BY.', 'HAVING', array['HAVING clause']::text[]),
  ('sw-sql/group-by-select-rule', 'sw-sql', 2, 'In a query with GROUP BY dept, which columns may appear in the SELECT list?', 'Only grouping columns, aggregates (COUNT, SUM, AVG, …), and expressions built from them.
SELECT dept, name, COUNT(*) … GROUP BY dept is an error in PostgreSQL: which name would each group show? Exception: columns functionally dependent on a grouped primary key.', null, '{}'::text[]),
  ('sw-sql/inner-vs-left-join', 'sw-sql', 3, 'INNER JOIN vs LEFT JOIN: what happens to a left-table row that has no match in the right table?', 'INNER JOIN drops it; LEFT JOIN keeps it, filling the right table''s columns with NULL. FULL OUTER JOIN keeps unmatched rows from both sides.
Trap: a WHERE filter on a right-table column (WHERE o.status = ''paid'') discards those NULL rows, turning the LEFT JOIN into an inner join in effect; put it in the ON clause instead.', null, '{}'::text[]),
  ('sw-sql/key-constraints', 'sw-sql', 4, 'Primary key vs unique constraint vs foreign key: what does each enforce?', 'Primary key: uniquely identifies each row and can''t be NULL; at most one per table. Unique: no duplicate values, but NULLs are allowed (PostgreSQL permits several by default); many per table. Foreign key: each non-NULL value must match a primary-key or unique value in the referenced table (referential integrity).', null, '{}'::text[]),
  ('sw-sql/null-comparison', 'sw-sql', 5, 'Which WHERE predicate correctly finds the rows whose email column holds NULL?', 'email IS NULL.
email = NULL never matches: any comparison with NULL yields UNKNOWN, and WHERE keeps only rows where the condition is TRUE. Even NULL = NULL is UNKNOWN.', 'email IS NULL', array['IS NULL', 'WHERE email IS NULL', 'email IS NULL;']::text[]),
  ('sw-sql/count-column-nulls', 'sw-sql', 6, 'A table has 10 rows, and 3 of them have NULL in the email column. What does COUNT(email) return?', '7. COUNT(column) counts only non-NULL values; COUNT(*) counts every row and would return 10.
SUM, AVG, MIN and MAX also ignore NULLs. Over zero rows, COUNT returns 0 but SUM returns NULL.', '7', array['seven']::text[]),
  ('sw-sql/not-in-null-trap', 'sw-sql', 7, 'How many rows does SELECT * FROM t WHERE x NOT IN (1, 2, NULL) return?', 'None. x NOT IN (1, 2, NULL) means x <> 1 AND x <> 2 AND x <> NULL; the last comparison is always UNKNOWN, so the condition is never TRUE.
The same trap hits NOT IN (subquery) when the subquery returns a NULL; NOT EXISTS avoids it.', '0', array['none', 'zero', 'no rows', '0 rows', 'zero rows']::text[]),
  ('sw-sql/union-all', 'sw-sql', 8, 'Which set operator stacks two queries'' results without removing duplicate rows?', 'UNION ALL.
Plain UNION removes duplicates, which costs an extra sort or hash step, so prefer UNION ALL when duplicates are impossible or wanted. Both need the same number of columns with compatible types.', 'UNION ALL', '{}'::text[]),
  ('sw-sql/acid-properties', 'sw-sql', 9, 'What does each letter of ACID guarantee for a database transaction?', 'Atomicity: all of its changes happen or none do (ROLLBACK undoes everything since BEGIN). Consistency: it moves the database from one valid state to another; constraints hold. Isolation: concurrent transactions don''t see each other''s partial work. Durability: once COMMIT succeeds, the changes survive a crash.', null, '{}'::text[]),
  ('sw-sql/read-anomalies', 'sw-sql', 10, 'Dirty read vs non-repeatable read vs phantom read: what does each one mean?', 'Dirty read: seeing another transaction''s uncommitted changes. Non-repeatable read: re-reading a row returns different values because another transaction committed an update in between. Phantom read: re-running a query with a WHERE condition returns a different set of rows because another transaction committed inserts or deletes.', null, '{}'::text[]),
  ('sw-sql/repeatable-read-level', 'sw-sql', 11, 'Lowest SQL-standard isolation level at which re-reading the same row within a transaction is guaranteed to return the same values?', 'REPEATABLE READ.
Standard ladder: READ UNCOMMITTED (allows dirty reads) → READ COMMITTED (no dirty reads; PostgreSQL''s default) → REPEATABLE READ (no non-repeatable reads; the standard still allows phantoms, PostgreSQL prevents them) → SERIALIZABLE (no anomalies).', 'REPEATABLE READ', array['repeatable-read']::text[]),
  ('sw-sql/btree-index-tradeoff', 'sw-sql', 12, 'What does a B-tree index on a column speed up, and what does it cost?', 'Speeds up equality and range lookups (=, <, BETWEEN), ORDER BY, and joins on that column: an O(log n) descent instead of a full table scan.
Costs: extra storage and slower writes, since INSERTs, UPDATEs, and DELETEs may also have to modify the index. Index what you filter, join, or sort on, not every column.', null, '{}'::text[]),
  ('sw-sql/second-normal-form', 'sw-sql', 13, 'Enrollment(student_id, course_id, student_name) has key (student_id, course_id). What is the lowest normal form it fails?', '2NF: student_name depends on student_id alone, a partial dependency on the composite key. Fix: move it to Students(student_id, student_name).
1NF: atomic values. 2NF: no partial dependencies. 3NF: also no transitive ones (non-key → non-key). ''The key, the whole key, and nothing but the key.''', '2NF', array['second normal form', '2nd normal form', 'second', '2nd']::text[]),
  ('sw-sql/sql-injection-defense', 'sw-sql', 14, 'What''s the standard defense against SQL injection when a query must include user input?', 'Parameterized queries (prepared statements): the SQL has placeholders (WHERE email = ?) and the values are sent separately, so input is always treated as data, never as SQL.
String concatenation lets input like '' OR ''1''=''1 rewrite the query. Hand-escaping is error-prone; use the driver''s parameters.', 'parameterized queries', array['parameterized query', 'parameterised queries', 'parameterised query', 'parametrized queries', 'parametrized query', 'prepared statements', 'prepared statement', 'bind parameters', 'query parameters', 'parameterized statements']::text[]),
  ('sw-sql/cap-theorem', 'sw-sql', 15, 'CAP theorem: during a network partition, a distributed data store must choose between which two guarantees?', 'Consistency (every read sees the most recent write, i.e. linearizability) and availability (every request to a non-failed node gets a non-error response).
Partitions can''t be ruled out in real networks, so P isn''t really optional. When there''s no partition, a system can provide both C and A.', null, '{}'::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'sw-sql' and id not in ('sw-sql/logical-query-order', 'sw-sql/where-vs-having', 'sw-sql/group-by-select-rule', 'sw-sql/inner-vs-left-join', 'sw-sql/key-constraints', 'sw-sql/null-comparison', 'sw-sql/count-column-nulls', 'sw-sql/not-in-null-trap', 'sw-sql/union-all', 'sw-sql/acid-properties', 'sw-sql/read-anomalies', 'sw-sql/repeatable-read-level', 'sw-sql/btree-index-tradeoff', 'sw-sql/second-normal-form', 'sw-sql/sql-injection-defense', 'sw-sql/cap-theorem');

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('sw-web/post-not-idempotent', 'sw-web', 0, 'Of GET, POST, PUT, and DELETE, which method is neither safe nor idempotent?', 'POST. Safe = read-only semantics (GET, HEAD, OPTIONS, TRACE). Idempotent = repeating the request has the same effect on the server as sending it once: the safe methods plus PUT and DELETE.
Two identical POSTs may create two orders, so clients shouldn''t auto-retry them. PATCH isn''t guaranteed idempotent either.', 'POST', '{}'::text[]),
  ('sw-web/status-201-created', 'sw-web', 1, 'Status code for a successful POST that created a new resource?', '201 Created, usually with a Location header pointing at the new resource.
Compare 200 OK (success, with a response body) and 204 No Content (success with no body, common for DELETE or PUT).', '201', array['201 Created']::text[]),
  ('sw-web/redirect-301-vs-302', 'sw-web', 2, '301 vs 302 redirects: what does each tell clients and search engines?', '301 Moved Permanently: use the new URL from now on; browsers may cache the redirect and search engines index the new URL. 302 Found: temporary; keep using (and indexing) the original URL.
307 and 308 are the temporary and permanent versions that forbid changing the method (e.g. POST to GET).', null, '{}'::text[]),
  ('sw-web/status-304-not-modified', 'sw-web', 3, 'A client revalidates its cached copy by sending If-None-Match with the resource''s ETag. What status code means it''s still current?', '304 Not Modified, with no body: the client reuses its cached copy, saving bandwidth.
An ETag is a version identifier for the resource; Last-Modified with If-Modified-Since is the date-based alternative.', '304', array['304 Not Modified']::text[]),
  ('sw-web/status-401-vs-403', 'sw-web', 4, 'A logged-in user requests an admin-only page they aren''t allowed to see. Should the server respond 401 or 403?', '403 Forbidden: the server knows who you are and refuses; re-authenticating won''t help.
401 Unauthorized really means unauthenticated: credentials missing or invalid, and the response must include a WWW-Authenticate header. (Some sites return 404 to hide that the resource exists.)', '403', array['403 Forbidden']::text[]),
  ('sw-web/status-409-422-429', 'sw-web', 5, 'What do status codes 409, 422, and 429 each signal?', '409 Conflict: the request clashes with the resource''s current state (edit conflict, username already taken). 422 Unprocessable Content: well-formed but semantically invalid, e.g. failed validation. 429 Too Many Requests: rate limited; may include Retry-After.
All are client errors (4xx); 400 Bad Request covers malformed requests.', null, '{}'::text[]),
  ('sw-web/status-500-502-503', 'sw-web', 6, '500 vs 502 vs 503: what does each server error mean?', '500 Internal Server Error: the server hit an unexpected condition (e.g. an unhandled exception). 502 Bad Gateway: a gateway or proxy got an invalid response from the upstream server. 503 Service Unavailable: temporarily overloaded or down for maintenance; may include Retry-After.
504 Gateway Timeout: the upstream didn''t answer in time.', null, '{}'::text[]),
  ('sw-web/https-tls', 'sw-web', 7, 'HTTPS is HTTP layered over which security protocol?', 'TLS (Transport Layer Security). It provides encryption, integrity, and server authentication via certificates; SSL is its deprecated predecessor.
Default ports: HTTPS 443, HTTP 80. Also worth knowing: SSH 22, DNS 53.', 'TLS', array['Transport Layer Security', 'SSL/TLS', 'TLS/SSL']::text[]),
  ('sw-web/dns-aaaa-record', 'sw-web', 8, 'Which DNS record type maps a hostname to an IPv6 address?', 'AAAA (an IPv6 address is 4× the size of an IPv4 one).
A maps a name to an IPv4 address. CNAME makes a name an alias for another name and can''t coexist with other records at that name, so it can''t sit at the zone apex (example.com).', 'AAAA', array['AAAA record']::text[]),
  ('sw-web/tcp-vs-udp', 'sw-web', 9, 'TCP vs UDP: how do they differ, and what''s a typical use of UDP?', 'TCP: connection-oriented (3-way handshake), reliable, ordered byte stream with retransmission, flow control, and congestion control. UDP: connectionless datagrams with no delivery or ordering guarantees, but less overhead and latency.
UDP suits DNS queries, games, and voice/video calls; HTTP/3 runs on QUIC over UDP.', null, '{}'::text[]),
  ('sw-web/cookie-httponly', 'sw-web', 10, 'Which cookie attribute prevents JavaScript (document.cookie) from reading the cookie?', 'HttpOnly. It limits session theft through XSS.
Secure: sent only over HTTPS. SameSite=Strict or Lax: not sent on cross-site requests (Lax still allows top-level GET navigations), which mitigates CSRF. localStorage has no such protection: any script on the page can read it.', 'HttpOnly', array['Http-Only', 'HttpOnly flag', 'HttpOnly attribute']::text[]),
  ('sw-web/cors-preflight', 'sw-web', 11, 'Before a cross-origin PUT or a JSON POST, the browser sends a CORS preflight request using which HTTP method?', 'OPTIONS, carrying Access-Control-Request-Method/-Headers; the server replies with Access-Control-Allow-* headers.
CORS is enforced by the browser, not the server: curl and server-to-server calls ignore it. Simple requests (GET, HEAD, or form-style POST without custom headers) skip the preflight.', 'OPTIONS', '{}'::text[]),
  ('sw-web/rest-statelessness', 'sw-web', 12, 'What does ''stateless'' mean as a REST constraint?', 'Each request carries everything the server needs to process it (e.g. an auth token); the server keeps no client session state between requests.
Payoff: any server instance can handle any request, so horizontal scaling and failure recovery are simpler. Data in a database is fine; it''s per-client session state that''s excluded.', null, '{}'::text[]),
  ('sw-web/cache-control-no-cache', 'sw-web', 13, 'Cache-Control: no-cache vs no-store: what does each directive mean?', 'no-store: don''t store the response in any cache. no-cache: caches may store it but must revalidate with the origin server (e.g. via ETag) before every reuse.
Trap: no-cache does not mean ''don''t cache''. max-age=N lets a cache reuse the response for N seconds without asking.', null, '{}'::text[]),
  ('sw-web/xss-vs-csrf', 'sw-web', 14, 'XSS vs CSRF: what does each attack do, and what''s a main defense against each?', 'XSS: attacker-supplied script runs inside your site''s pages (via unescaped user input) and acts as the user. Defense: escape/encode output, plus a Content Security Policy.
CSRF: another site makes the victim''s browser send an authenticated request, since cookies attach automatically. Defense: SameSite cookies and anti-CSRF tokens.', null, '{}'::text[]),
  ('sw-web/jwt-structure', 'sw-web', 15, 'What are the three parts of a JWT, and is its payload encrypted?', 'header.payload.signature, each base64url-encoded. The payload is signed, not encrypted: anyone holding the token can decode and read it, so never put secrets in it.
The signature lets the server detect tampering; it hides nothing. Encrypted tokens are a different format (JWE).', null, '{}'::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'sw-web' and id not in ('sw-web/post-not-idempotent', 'sw-web/status-201-created', 'sw-web/redirect-301-vs-302', 'sw-web/status-304-not-modified', 'sw-web/status-401-vs-403', 'sw-web/status-409-422-429', 'sw-web/status-500-502-503', 'sw-web/https-tls', 'sw-web/dns-aaaa-record', 'sw-web/tcp-vs-udp', 'sw-web/cookie-httponly', 'sw-web/cors-preflight', 'sw-web/rest-statelessness', 'sw-web/cache-control-no-cache', 'sw-web/xss-vs-csrf', 'sw-web/jwt-structure');

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('sw-oop/encapsulation', 'sw-oop', 0, 'Which OOP principle bundles data with the methods that operate on it and restricts direct access to that internal state?', 'Encapsulation. E.g. a private balance field that changes only through deposit() and withdraw(), which enforce invariants such as no negative balance.
Don''t confuse it with abstraction: exposing what an object does while hiding how it does it.', 'encapsulation', array['data encapsulation']::text[]),
  ('sw-oop/polymorphism', 'sw-oop', 1, 'Which OOP principle lets shape.area() run Circle''s or Square''s implementation depending on the object''s runtime type?', 'Polymorphism (subtype or runtime polymorphism, via dynamic dispatch). Callers depend only on the Shape type, so new shapes work without changing caller code.
Method overloading is a different, compile-time kind (ad hoc polymorphism).', 'polymorphism', array['subtype polymorphism', 'runtime polymorphism', 'run-time polymorphism', 'dynamic polymorphism']::text[]),
  ('sw-oop/overloading-vs-overriding', 'sw-oop', 2, 'Method overloading vs method overriding: what''s the difference, and when is each resolved?', 'Overloading: same name, different parameter lists; the compiler picks the version at compile time from the argument types. Overriding: a subclass redefines an inherited method with the same signature; the version that runs depends on the object''s runtime type.
In Java, methods that differ only in return type can''t be overloads (compile error).', null, '{}'::text[]),
  ('sw-oop/interface-vs-abstract-class', 'sw-oop', 3, 'In Java, what are the key differences between an interface and an abstract class?', 'A class can implement many interfaces but extend only one class (abstract or not). Abstract classes can have constructors, instance fields, and protected members; interface fields are implicitly public static final constants, though Java 8+ allows default and static methods.
Interface: a capability (Comparable). Abstract class: shared base state and code.', null, '{}'::text[]),
  ('sw-oop/composition-over-inheritance', 'sw-oop', 4, 'Why do designers advise ''favor composition over inheritance''?', 'Inheritance (is-a) binds a subclass to its parent''s implementation at compile time, so parent changes can break subclasses (the fragile base class problem). Composition (has-a) delegates to contained objects behind interfaces, which can be swapped at runtime, giving looser coupling.
E.g. a Car has an Engine field rather than extending Engine.', null, '{}'::text[]),
  ('sw-oop/coupling-vs-cohesion', 'sw-oop', 5, 'Good modular design aims for what level of coupling and what level of cohesion?', 'Low (loose) coupling, high cohesion.
Coupling: how much modules depend on each other''s internals; keep it to narrow interfaces. Cohesion: how closely everything in a module serves one focused purpose. Together they let you change one module without ripple effects.', null, '{}'::text[]),
  ('sw-oop/single-responsibility', 'sw-oop', 6, 'Which SOLID principle says a class should have only one reason to change?', 'Single Responsibility Principle (SRP).
E.g. a Report class that both computes figures and renders PDFs has two reasons to change (business rules vs formatting); split it into ReportCalculator and PdfRenderer.', 'single responsibility', array['single responsibility principle', 'single-responsibility', 'single-responsibility principle', 'SRP']::text[]),
  ('sw-oop/open-closed', 'sw-oop', 7, 'State the Open/Closed Principle and the usual way to follow it.', 'Software entities should be open for extension but closed for modification: add behavior by writing new code (e.g. a new class implementing an existing interface), not by editing existing, tested code.
Smell: a switch on type that grows with every new case; replace it with polymorphism or the Strategy pattern.', null, '{}'::text[]),
  ('sw-oop/liskov-substitution', 'sw-oop', 8, 'A Square subclass of Rectangle breaks code that sets width and height independently. Which SOLID principle does it violate?', 'The Liskov Substitution Principle: objects of a subtype must be usable anywhere the base type is expected without breaking correctness.
Code that sets width = 5, then height = 4, expects area 20; a Square that keeps its sides equal returns 16. Subtypes must honor the base type''s contract.', 'Liskov substitution', array['Liskov substitution principle', 'Liskov''s substitution principle', 'LSP', 'Liskov']::text[]),
  ('sw-oop/interface-segregation', 'sw-oop', 9, 'Which SOLID principle says clients shouldn''t be forced to depend on methods they don''t use?', 'Interface Segregation Principle (ISP).
Split a fat MultiFunctionDevice interface into small role interfaces (Printer, Scanner, Fax) so a basic printer doesn''t have to stub out scan() and fax().', 'interface segregation', array['interface segregation principle', 'ISP']::text[]),
  ('sw-oop/dependency-inversion', 'sw-oop', 10, 'What does the Dependency Inversion Principle say, and which technique commonly applies it?', 'High-level modules shouldn''t depend on low-level modules; both should depend on abstractions, and details should depend on abstractions. E.g. OrderService depends on a PaymentGateway interface, not on StripeClient.
Dependency injection supplies the concrete implementation from outside (constructor or setter), so tests can pass in a fake.', null, '{}'::text[]),
  ('sw-oop/observer-pattern', 'sw-oop', 11, 'Which design pattern defines a one-to-many dependency so that when one object changes state, all its dependents are notified?', 'Observer (also called publish–subscribe). The subject keeps a list of observers and calls their update method on each change; observers can subscribe and unsubscribe at runtime.
Examples: GUI event listeners, addEventListener, model–view updates.', 'Observer', array['observer pattern', 'publish-subscribe', 'publish subscribe', 'pub/sub', 'pub-sub', 'pubsub']::text[]),
  ('sw-oop/strategy-pattern', 'sw-oop', 12, 'Which design pattern encapsulates a family of interchangeable algorithms behind a common interface so they can be swapped at runtime?', 'Strategy. E.g. Checkout takes a ShippingCost strategy (FlatRate, ByWeight) instead of switching on a type field, so adding a new strategy doesn''t touch Checkout.
A Comparator passed to a sort function is a strategy.', 'Strategy', array['strategy pattern']::text[]),
  ('sw-oop/adapter-vs-decorator', 'sw-oop', 13, 'Adapter vs Decorator: both wrap an object, so how do their intents differ?', 'Adapter converts an object''s interface into a different one that clients expect, e.g. wrapping a legacy XML service to fit your DataSource interface. Decorator keeps the same interface and adds responsibilities dynamically, e.g. a BufferedInputStream wrapping a FileInputStream; decorators can be stacked.
Adapter changes the interface; Decorator adds behavior.', null, '{}'::text[]),
  ('sw-oop/unit-integration-e2e', 'sw-oop', 14, 'Unit vs integration vs end-to-end tests: what does each exercise?', 'Unit: one function or class in isolation, with dependencies faked; fast and numerous. Integration: several real components together, e.g. a repository class against a real database. End-to-end: the whole system through its real interface, e.g. a browser clicking through signup.
Test pyramid: many unit, fewer integration, fewest E2E (slowest, most brittle).', null, '{}'::text[]),
  ('sw-oop/tdd-cycle', 'sw-oop', 15, 'Name the three steps of the test-driven development cycle, in order.', 'Red, green, refactor.
Red: write a small test that fails. Green: write the minimum code that makes it pass. Refactor: clean up code and tests while everything stays green. Then repeat with the next test.', 'red green refactor', array['red-green-refactor', 'red, green, refactor', 'red -> green -> refactor', 'red → green → refactor']::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'sw-oop' and id not in ('sw-oop/encapsulation', 'sw-oop/polymorphism', 'sw-oop/overloading-vs-overriding', 'sw-oop/interface-vs-abstract-class', 'sw-oop/composition-over-inheritance', 'sw-oop/coupling-vs-cohesion', 'sw-oop/single-responsibility', 'sw-oop/open-closed', 'sw-oop/liskov-substitution', 'sw-oop/interface-segregation', 'sw-oop/dependency-inversion', 'sw-oop/observer-pattern', 'sw-oop/strategy-pattern', 'sw-oop/adapter-vs-decorator', 'sw-oop/unit-integration-e2e', 'sw-oop/tdd-cycle');

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('sw-os/process-vs-thread', 'sw-os', 0, 'What do threads of the same process share, and what does each thread have of its own?', 'Shared: the process''s address space (code, data, heap) and resources such as open files. Private to each thread: its program counter, registers, and stack.
Processes are isolated from one another (communication needs IPC); threads are cheaper to create and switch, but a bug in one can corrupt the others'' memory.', null, '{}'::text[]),
  ('sw-os/process-states', 'sw-os', 1, 'What are the five process states in the classic model, and what moves a running process back to ready?', 'New, ready, running, waiting (blocked), terminated. Running → ready: an interrupt, e.g. its time slice expires. Running → waiting: it requests I/O or waits for an event; waiting → ready when that completes.
The kernel records each process''s state in its process control block (PCB).', null, '{}'::text[]),
  ('sw-os/fork-return-value', 'sw-os', 2, 'What value does fork() return in the newly created child process?', '0. The parent gets the child''s PID (a positive number); if fork() fails, the parent gets −1 and no child is created.
Both processes continue from the instruction after fork(), each with its own copy of the address space (copy-on-write in practice).', '0', array['zero']::text[]),
  ('sw-os/system-calls-kernel-mode', 'sw-os', 3, 'Why must a user program make a system call to do I/O instead of accessing the device directly?', 'I/O and other privileged instructions can run only in kernel mode (a hardware mode bit). A system call traps into the kernel, which switches to kernel mode, performs the service (e.g. read()), then returns to user mode.
This keeps buggy or malicious programs from touching hardware or other processes'' memory.', null, '{}'::text[]),
  ('sw-os/sjf-optimal', 'sw-os', 4, 'Which CPU-scheduling algorithm gives the minimum average waiting time for a given set of processes?', 'Shortest-Job-First (SJF): running the shortest CPU bursts first minimizes total waiting.
Catch: the next burst length isn''t known in advance, so it''s predicted (e.g. exponential averaging of past bursts), and long jobs can starve. Its preemptive form is shortest-remaining-time-first (SRTF).', 'SJF', array['shortest job first', 'shortest-job-first', 'shortest job next', 'SJN', 'SRTF', 'shortest remaining time first', 'shortest-remaining-time-first']::text[]),
  ('sw-os/round-robin-quantum', 'sw-os', 5, 'Round-robin scheduling: what happens if the time quantum is very large, and if it''s very small?', 'Very large: RR degenerates into FCFS (first-come, first-served). Very small: context switches happen so often that their overhead dominates.
Silberschatz''s rule of thumb: about 80% of CPU bursts should be shorter than the quantum.', null, '{}'::text[]),
  ('sw-os/priority-aging', 'sw-os', 6, 'In priority scheduling, what technique prevents low-priority processes from starving?', 'Aging: gradually raise the priority of processes that have waited a long time, so they eventually run.
Without it, a steady stream of higher-priority work can postpone a low-priority process indefinitely (starvation).', 'aging', array['ageing', 'priority aging']::text[]),
  ('sw-os/race-condition', 'sw-os', 7, 'What is a race condition, and what is a critical section?', 'Race condition: the result depends on how concurrent threads'' accesses to shared data happen to interleave, e.g. two threads running count++ (load, add, store) can lose an update.
Critical section: code that accesses shared data and must not run in more than one thread at a time. A correct solution needs mutual exclusion, progress, and bounded waiting.', null, '{}'::text[]),
  ('sw-os/mutex-vs-semaphore', 'sw-os', 8, 'Mutex lock vs counting semaphore: what does each allow?', 'Mutex: mutual exclusion, one holder at a time; the thread that acquires it releases it. Counting semaphore: an integer; wait() decrements it and blocks when no units remain, signal() increments it. Initialized to N, it admits up to N threads, e.g. a pool of N connections.
A binary semaphore (0/1) can act like a lock but has no owner.', null, '{}'::text[]),
  ('sw-os/coffman-conditions', 'sw-os', 9, 'What are the four necessary conditions for deadlock (the Coffman conditions)?', 'Mutual exclusion, hold and wait, no preemption, and circular wait.
All four must hold at once, so deadlock prevention breaks at least one, e.g. acquiring locks in a fixed global order rules out circular wait.', null, '{}'::text[]),
  ('sw-os/bankers-algorithm', 'sw-os', 10, 'Which deadlock-avoidance algorithm grants a resource request only if the system stays in a safe state?', 'The Banker''s algorithm (Dijkstra). Avoidance requires each process to declare its maximum demand in advance.
Contrast: prevention designs out one Coffman condition; detection lets deadlocks happen, finds them (e.g. a cycle in a wait-for graph), then recovers by aborting processes or preempting resources.', 'Banker''s algorithm', array['bankers algorithm', 'banker algorithm', 'bankers'' algorithm', 'banker''s', 'bankers', 'banker']::text[]),
  ('sw-os/internal-vs-external-fragmentation', 'sw-os', 11, 'Internal vs external fragmentation: what''s the difference?', 'Internal: wasted space inside an allocated block, e.g. a process using only 1 KB of its last 4 KB page. External: enough total free memory exists, but it''s split into non-contiguous holes too small to use.
Paging eliminates external fragmentation but still has internal; variable-size contiguous allocation suffers external fragmentation (fix: compaction).', null, '{}'::text[]),
  ('sw-os/page-fault', 'sw-os', 12, 'What triggers a page fault, and what does the OS do to handle it?', 'Accessing a page whose page-table entry is marked invalid (not in memory). The OS traps, checks the reference is legal (otherwise it terminates the process), finds a free frame or evicts a victim page, reads the page in from disk, updates the page table, and restarts the faulting instruction.', null, '{}'::text[]),
  ('sw-os/tlb', 'sw-os', 13, 'What is the small hardware cache of recent virtual-page-to-physical-frame translations called?', 'TLB (translation lookaside buffer). A hit translates the address without reading the page table from memory; a miss walks the page table and caches the entry.
On a context switch, entries are flushed unless they''re tagged with address-space IDs (ASIDs).', 'TLB', array['translation lookaside buffer', 'translation look-aside buffer']::text[]),
  ('sw-os/beladys-anomaly', 'sw-os', 14, 'Belady''s anomaly (more frames causing more page faults) is the classic weakness of which page-replacement algorithm?', 'FIFO. LRU and OPT are stack algorithms, so they never exhibit it.
OPT (evict the page used farthest in the future) gives the fewest possible faults but needs future knowledge, so it''s a benchmark; LRU approximates it by evicting the page unused for the longest time.', 'FIFO', array['first in first out', 'first-in first-out', 'first-in, first-out', 'first in, first out']::text[]),
  ('sw-os/thrashing', 'sw-os', 15, 'A process without enough frames for its working set spends more time paging than executing. What is this called?', 'Thrashing. CPU utilization collapses, and a scheduler that responds by admitting more processes only makes it worse.
Fix: give each process enough frames for its working set (working-set model, page-fault-frequency control) or lower the degree of multiprogramming.', 'thrashing', array['thrash']::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'sw-os' and id not in ('sw-os/process-vs-thread', 'sw-os/process-states', 'sw-os/fork-return-value', 'sw-os/system-calls-kernel-mode', 'sw-os/sjf-optimal', 'sw-os/round-robin-quantum', 'sw-os/priority-aging', 'sw-os/race-condition', 'sw-os/mutex-vs-semaphore', 'sw-os/coffman-conditions', 'sw-os/bankers-algorithm', 'sw-os/internal-vs-external-fragmentation', 'sw-os/page-fault', 'sw-os/tlb', 'sw-os/beladys-anomaly', 'sw-os/thrashing');

