-- Chemistry
insert into public.packs (id, category_id, title, course, description, position) values
  ('chem-atoms-bonding', 'chemistry', 'Atoms, Trends & Bonding', 'General Chemistry I', 'Electron configurations and their exceptions, periodic trends with reasons, lattice energy, formal charge, VSEPR, hybridization, polarity and IMFs.', 0),
  ('chem-stoich-gases', 'chemistry', 'Stoichiometry & Gas Laws', 'General Chemistry I', 'Molar mass, formulas, limiting reagents, yield, molarity and dilution, oxidation states, ideal and combined gas laws, Dalton, Graham, real gases.', 1),
  ('chem-equilibrium', 'chemistry', 'Equilibrium, Acids & Bases', 'General Chemistry II', 'K expressions, Q vs K, Le Chatelier, Kp vs Kc, Kw and pH, strong acids, Ka·Kb, Lewis acids, buffers, half-equivalence, Ksp and the common-ion effect.', 2),
  ('chem-thermo-kinetics', 'chemistry', 'Thermodynamics & Kinetics', 'General Chemistry II', 'Calorimetry, Hess''s law, formation enthalpies, entropy, ΔG with K and E°, rate laws, first-order half-life, Arrhenius, mechanisms and catalysts.', 3),
  ('chem-organic', 'chemistry', 'Organic Chemistry Foundations', 'Organic Chemistry I', 'Functional groups, unsaturation, acidity and resonance, chirality and CIP, meso compounds, SN1/SN2/E2 with stereochemistry, Markovnikov and hydroboration.', 4)
on conflict (id) do update set category_id = excluded.category_id, title = excluded.title, course = excluded.course, description = excluded.description, position = excluded.position;

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('chem-atoms-bonding/avogadro-number', 'chem-atoms-bonding', 0, 'Avogadro''s number: how many particles are in one mole of a substance?', '6.022×10²³ particles per mole (units: mol⁻¹).
It links atomic mass units to grams: one ¹²C atom has a mass of 12 u, and a mole of them has a mass of 12 g. Trap: 0.50 mol CO₂ is 3.0×10²³ molecules but 9.0×10²³ atoms.', '6.022x10^23', array['6.022e23', '6.022*10^23', '6.02x10^23', '6.02e23', '6.02*10^23']::text[]),
  ('chem-atoms-bonding/isotope-ion-counts', 'chem-atoms-bonding', 1, 'How many protons, neutrons, and electrons are in the ion ³⁷Cl⁻ (Z = 17)?', '17 protons, 20 neutrons, 18 electrons.
Neutrons = mass number − Z = 37 − 17. The 1− charge means one extra electron. ³⁵Cl and ³⁷Cl are isotopes: same Z, different numbers of neutrons, essentially the same chemistry.', null, '{}'::text[]),
  ('chem-atoms-bonding/orbitals-in-n3-shell', 'chem-atoms-bonding', 2, 'How many orbitals are in the n = 3 shell?', '9 (n² orbitals).
ℓ runs from 0 to n − 1 (3s, 3p, 3d) and mℓ from −ℓ to +ℓ, giving 1 + 3 + 5 = 9 orbitals that hold 2n² = 18 electrons. Trap: n = 2, ℓ = 2 is not an allowed set (ℓ ≤ n − 1).', '9', array['nine', '9 orbitals']::text[]),
  ('chem-atoms-bonding/hunds-rule', 'chem-atoms-bonding', 3, 'Which rule says nitrogen''s three 2p electrons occupy separate orbitals with parallel spins instead of pairing up?', 'Hund''s rule.
Electrons enter degenerate orbitals singly, with parallel spins, before any pairing; this minimizes electron–electron repulsion. Its partners: Aufbau (fill the lowest-energy orbitals first) and Pauli (at most 2 electrons per orbital, with opposite spins).', 'Hund''s rule', array['Hund', 'Hund''s', 'Hunds rule', 'Hunds', 'Hund rule']::text[]),
  ('chem-atoms-bonding/cr-cu-exceptions', 'chem-atoms-bonding', 4, 'What are the actual ground-state electron configurations of chromium (Cr) and copper (Cu)?', 'Cr: [Ar] 3d⁵ 4s¹ (not 3d⁴ 4s²). Cu: [Ar] 3d¹⁰ 4s¹ (not 3d⁹ 4s²).
A half-filled or completely filled d subshell is especially stable, so one 4s electron moves into 3d. Mo and Ag follow the same pattern.', null, '{}'::text[]),
  ('chem-atoms-bonding/atomic-radius-trend', 'chem-atoms-bonding', 5, 'Why does atomic radius decrease from left to right across a period but increase down a group?', 'Across: effective nuclear charge (Zeff) rises, pulling the same valence shell closer. Down: each period adds a shell with a higher n, farther from the nucleus.
Protons are added across a period, but same-shell electrons shield each other poorly. Examples: Na > Mg > Cl; Li < Na < K.', null, '{}'::text[]),
  ('chem-atoms-bonding/ionization-energy-exceptions', 'chem-atoms-bonding', 6, 'First ionization energy generally rises across period 2. Why is it lower for O than for N, and for B than for Be?', 'O: its fourth 2p electron is paired, and the extra electron–electron repulsion makes it easier to remove (N''s half-filled 2p³ has no pairs). B: its outer electron is in 2p, higher in energy and partly shielded by the 2s electrons.
Overall: IE₁ rises across a period (Zeff up) and falls down a group (larger atoms).', null, '{}'::text[]),
  ('chem-atoms-bonding/successive-ionization-jump', 'chem-atoms-bonding', 7, 'An element has IE₁ = 738, IE₂ = 1451 and IE₃ = 7733 kJ/mol. Which group of the periodic table is it in?', 'Group 2 (the alkaline earth metals); it''s Mg.
The huge jump after IE₂ means the third electron would have to come from the noble-gas core. The number of electrons removed before the big jump equals the number of valence electrons.', '2', array['group 2', '2A', 'IIA', 'II', 'group 2A', 'group IIA', 'group II', 'alkaline earth metals', 'alkaline earth metal', 'alkaline earth', 'alkaline-earth metals']::text[]),
  ('chem-atoms-bonding/electronegativity-order', 'chem-atoms-bonding', 8, 'Arrange Si, C, N, O, and F in order of increasing electronegativity.', 'Si < C < N < O < F.
Electronegativity rises across a period and up a group (Si sits below C): higher Zeff and a smaller radius let the nucleus pull bonding electrons harder. F (≈ 4.0 on the Pauling scale) is the most electronegative element.', null, '{}'::text[]),
  ('chem-atoms-bonding/lattice-energy-charge', 'chem-atoms-bonding', 9, 'Which has the largest lattice energy (in magnitude): KCl, NaCl, NaF, or MgO?', 'MgO (roughly 3800–3900 kJ/mol, vs about 790 for NaCl).
Coulomb''s law: lattice energy ∝ q₁q₂/r. Mg²⁺ and O²⁻ give 4× the charge product of a 1+/1− pair, and both ions are small. Among the 1+/1− salts, smaller ions win: NaF > NaCl > KCl.', 'MgO', array['magnesium oxide']::text[]),
  ('chem-atoms-bonding/formal-charge-co', 'chem-atoms-bonding', 10, 'In the best Lewis structure of carbon monoxide, :C≡O:, what is the formal charge on carbon?', '−1.
FC = valence e⁻ − nonbonding e⁻ − ½(bonding e⁻) = 4 − 2 − 3 = −1, and O is +1. The triple bond gives both atoms an octet, which matters more than putting the negative charge on the more electronegative atom.', '-1', array['1-', 'negative 1', 'minus 1', 'negative one']::text[]),
  ('chem-atoms-bonding/sf4-molecular-geometry', 'chem-atoms-bonding', 11, 'What is the molecular geometry (shape) of SF₄?', 'Seesaw.
S has 5 electron domains (4 bonds + 1 lone pair), so the electron geometry is trigonal bipyramidal. Lone pairs take equatorial positions, which have fewer 90° repulsions. Same logic: ClF₃ is T-shaped and XeF₂ is linear.', 'seesaw', array['see-saw', 'sawhorse', 'seesaw shape']::text[]),
  ('chem-atoms-bonding/hybridization-water-oxygen', 'chem-atoms-bonding', 12, 'What is the hybridization of the oxygen atom in H₂O?', 'sp³.
Count electron domains, not bonded atoms: 2 bonds + 2 lone pairs = 4 domains → sp³ (2 → sp, 3 → sp², 4 → sp³). Trap: calling it sp because O has only two bonds.', 'sp3', array['sp^3']::text[]),
  ('chem-atoms-bonding/sigma-pi-count-hcn', 'chem-atoms-bonding', 13, 'How many σ bonds and how many π bonds are in HCN (H–C≡N)?', '2 σ and 2 π.
Every single bond is one σ; a double bond is σ + π; a triple bond is σ + 2π. σ bonds form by head-on overlap, π bonds by side-by-side overlap of unhybridized p orbitals, which is why π bonds block rotation.', null, '{}'::text[]),
  ('chem-atoms-bonding/polar-molecule-choice', 'chem-atoms-bonding', 14, 'Which of these molecules is polar: CO₂, BF₃, CCl₄, or SO₂?', 'SO₂.
The lone pair on S makes it bent, so the S–O bond dipoles don''t cancel. CO₂ (linear), BF₃ (trigonal planar) and CCl₄ (tetrahedral) all have polar bonds, but their symmetric shapes make the dipoles cancel.', 'SO2', array['sulfur dioxide', 'sulphur dioxide']::text[]),
  ('chem-atoms-bonding/imf-boiling-point-ranking', 'chem-atoms-bonding', 15, 'Rank by boiling point: propane (CH₃CH₂CH₃), dimethyl ether (CH₃OCH₃), ethanol (CH₃CH₂OH). All have molar masses near 45 g/mol.', 'Propane (−42 °C) < dimethyl ether (−24 °C) < ethanol (78 °C).
Similar size means similar dispersion forces, so the extra force decides: dipole–dipole for the ether, hydrogen bonding for ethanol. The ether has O but no O–H, so it can''t H-bond with itself. An H-bond donor needs H bonded directly to N, O, or F.', null, '{}'::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'chem-atoms-bonding' and id not in ('chem-atoms-bonding/avogadro-number', 'chem-atoms-bonding/isotope-ion-counts', 'chem-atoms-bonding/orbitals-in-n3-shell', 'chem-atoms-bonding/hunds-rule', 'chem-atoms-bonding/cr-cu-exceptions', 'chem-atoms-bonding/atomic-radius-trend', 'chem-atoms-bonding/ionization-energy-exceptions', 'chem-atoms-bonding/successive-ionization-jump', 'chem-atoms-bonding/electronegativity-order', 'chem-atoms-bonding/lattice-energy-charge', 'chem-atoms-bonding/formal-charge-co', 'chem-atoms-bonding/sf4-molecular-geometry', 'chem-atoms-bonding/hybridization-water-oxygen', 'chem-atoms-bonding/sigma-pi-count-hcn', 'chem-atoms-bonding/polar-molecule-choice', 'chem-atoms-bonding/imf-boiling-point-ranking');

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('chem-stoich-gases/molar-mass-parentheses', 'chem-stoich-gases', 0, 'Molar mass of Ca(NO₃)₂? (Use Ca 40.08, N 14.01, O 16.00 g/mol.)', '164.10 g/mol.
40.08 + 2(14.01) + 6(16.00) = 164.10. A subscript outside parentheses multiplies everything inside, so there are 2 N and 6 O. Trap: counting only one NO₃ gives 102.09.', '164.1', array['164.10', '164.09', '164', '164.1 g/mol', '164.10 g/mol']::text[]),
  ('chem-stoich-gases/empirical-formula-from-percent', 'chem-stoich-gases', 1, 'A compound is 40.0% C, 6.7% H and 53.3% O by mass. What is its empirical formula?', 'CH₂O.
Assume 100 g: 40.0/12.01 = 3.33 mol C, 6.7/1.008 = 6.6 mol H, 53.3/16.00 = 3.33 mol O. Divide by the smallest: 1 : 2 : 1. If a ratio lands near 1.5 or 1.33, multiply all of them by 2 or 3.', null, '{}'::text[]),
  ('chem-stoich-gases/molecular-formula-from-empirical', 'chem-stoich-gases', 2, 'A compound has empirical formula CH₂O and a molar mass of 180 g/mol. What is its molecular formula?', 'C₆H₁₂O₆.
One CH₂O unit is 30.03 g/mol, and 180 ÷ 30.03 ≈ 6, so multiply every subscript by 6. Empirical = simplest whole-number ratio; molecular = actual atom counts, always a whole-number multiple of it.', 'C6H12O6', '{}'::text[]),
  ('chem-stoich-gases/limiting-reagent', 'chem-stoich-gases', 3, '2H₂ + O₂ → 2H₂O. If 4.0 mol H₂ is mixed with 3.0 mol O₂, which reactant is limiting?', 'H₂.
All 3.0 mol O₂ would need 6.0 mol H₂, but only 4.0 mol is present. H₂ gives 4.0 mol H₂O and leaves 1.0 mol O₂ unused. Trap: having fewer moles (O₂ here) doesn''t make a reactant limiting; compare moles divided by coefficients.', 'H2', array['hydrogen', 'hydrogen gas', 'H2 gas']::text[]),
  ('chem-stoich-gases/percent-yield', 'chem-stoich-gases', 4, 'The theoretical yield is 12.0 g, but you isolate 9.60 g of product. What is the percent yield?', '80.0%.
Percent yield = (actual ÷ theoretical) × 100 = (9.60 ÷ 12.0) × 100. The theoretical yield must be calculated from the limiting reagent. A yield over 100% usually means a wet or impure product.', null, '{}'::text[]),
  ('chem-stoich-gases/molarity-definition', 'chem-stoich-gases', 5, 'What is the molarity of 0.500 mol NaCl dissolved in enough water to make 250. mL of solution?', '2.00 M.
Molarity = moles of solute ÷ liters of solution = 0.500 mol ÷ 0.250 L. Traps: convert mL to L, and use the final volume of solution, not the volume of water added.', null, '{}'::text[]),
  ('chem-stoich-gases/dilution-m1v1', 'chem-stoich-gases', 6, 'How many mL of 12.0 M HCl are needed to prepare 500. mL of 0.600 M HCl?', '25.0 mL.
M₁V₁ = M₂V₂, so V₁ = (0.600 M × 500. mL) ÷ 12.0 M. Dilution doesn''t change the moles of solute, so any volume unit works if both sides match. Dilute to 500. mL, adding the acid to water.', '25', array['25.0', '25 mL', '25.0 mL']::text[]),
  ('chem-stoich-gases/oxidation-state-dichromate', 'chem-stoich-gases', 7, 'What is the oxidation state of Cr in K₂Cr₂O₇?', '+6.
K is +1 (2 × +1 = +2) and O is −2 (7 × −2 = −14); the total must be 0, so 2 Cr = +12. Rules: free elements 0; F always −1; O usually −2 (−1 in peroxides like H₂O₂); H +1 with nonmetals, −1 in metal hydrides.', '+6', array['6', '6+', 'VI']::text[]),
  ('chem-stoich-gases/gas-constant-atm', 'chem-stoich-gases', 8, 'Value of R in PV = nRT when pressure is in atm and volume is in liters?', '0.08206 L·atm/(mol·K).
Use 8.314 J/(mol·K) in energy equations (or with P in Pa and V in m³). R''s units must match your P and V units, and T must always be in kelvin.', '0.08206', array['0.0821', '.08206', '.0821', '0.082057']::text[]),
  ('chem-stoich-gases/kelvin-charles-law', 'chem-stoich-gases', 9, 'A gas at 27 °C is heated at constant pressure until its volume doubles. What is its new temperature in °C?', '327 °C.
Charles''s law (V ∝ T) only works in kelvin: 27 °C = 300 K, and doubling gives 600 K = 327 °C. Trap: doubling the Celsius value to 54 °C. Every gas-law temperature must be in K.', '327', array['327 C', '327 °C', '327 degrees', '327 degrees C', '327.15']::text[]),
  ('chem-stoich-gases/combined-gas-law', 'chem-stoich-gases', 10, 'A gas occupies 2.00 L at 1.00 atm and 300. K. What volume does it occupy at 2.00 atm and 450. K?', '1.50 L.
P₁V₁/T₁ = P₂V₂/T₂, so V₂ = 2.00 L × (1.00 atm ÷ 2.00 atm) × (450. K ÷ 300. K). Doubling P halves V; raising T 1.5-fold raises V 1.5-fold. Check each factor''s direction.', '1.5', array['1.50', '1.5 L', '1.50 L']::text[]),
  ('chem-stoich-gases/dalton-partial-pressure', 'chem-stoich-gases', 11, 'A mixture of 2.0 mol N₂ and 3.0 mol O₂ has a total pressure of 1.50 atm. What is the partial pressure of O₂?', '0.90 atm.
Dalton''s law: P(total) is the sum of the partial pressures, and P(O₂) = X(O₂) × P(total), with mole fraction X(O₂) = 3.0 ÷ 5.0 = 0.60. For a gas collected over water, subtract water''s vapor pressure from the total.', '0.9', array['0.90', '.9', '.90', '0.9 atm', '0.90 atm']::text[]),
  ('chem-stoich-gases/graham-effusion', 'chem-stoich-gases', 12, 'At the same temperature, by what factor does H₂ effuse faster than O₂?', 'About 4 times faster: √(32.00 ÷ 2.016) ≈ 3.98.
Graham''s law: rate₁/rate₂ = √(M₂/M₁), so lighter gases effuse faster. At the same T all gases have the same average kinetic energy, so lighter molecules must move faster.', '4', array['3.98', '4 times', '4 times faster', '3.98 times', '4x', '3.98x', '~4', 'about 4', 'four']::text[]),
  ('chem-stoich-gases/kmt-kinetic-energy', 'chem-stoich-gases', 13, 'Kinetic molecular theory: the average kinetic energy of gas particles is directly proportional to what?', 'The absolute (kelvin) temperature.
Other assumptions: the particles'' own volume is negligible; there are no attractions or repulsions between them; collisions are perfectly elastic; motion is constant and random. Doubling T in kelvin doubles the average kinetic energy.', null, '{}'::text[]),
  ('chem-stoich-gases/real-gas-deviations', 'chem-stoich-gases', 14, 'Under what conditions do real gases deviate most from ideal behavior, and why?', 'High pressure and low temperature.
At high P, the molecules'' own volume is a significant fraction of the container. At low T, molecules move slowly, so intermolecular attractions matter. Gases behave most ideally at low P and high T.', null, '{}'::text[]),
  ('chem-stoich-gases/van-der-waals-a-b', 'chem-stoich-gases', 15, 'In the van der Waals equation, (P + a·n²/V²)(V − nb) = nRT, what do the constants a and b correct for?', 'a corrects for intermolecular attractions, which make the measured pressure lower than ideal. b corrects for the volume the molecules themselves occupy.
Larger, more polarizable or polar molecules have larger a values; bigger molecules have larger b values.', null, '{}'::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'chem-stoich-gases' and id not in ('chem-stoich-gases/molar-mass-parentheses', 'chem-stoich-gases/empirical-formula-from-percent', 'chem-stoich-gases/molecular-formula-from-empirical', 'chem-stoich-gases/limiting-reagent', 'chem-stoich-gases/percent-yield', 'chem-stoich-gases/molarity-definition', 'chem-stoich-gases/dilution-m1v1', 'chem-stoich-gases/oxidation-state-dichromate', 'chem-stoich-gases/gas-constant-atm', 'chem-stoich-gases/kelvin-charles-law', 'chem-stoich-gases/combined-gas-law', 'chem-stoich-gases/dalton-partial-pressure', 'chem-stoich-gases/graham-effusion', 'chem-stoich-gases/kmt-kinetic-energy', 'chem-stoich-gases/real-gas-deviations', 'chem-stoich-gases/van-der-waals-a-b');

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('chem-equilibrium/k-expression-solids', 'chem-equilibrium', 0, 'Write Kc for CaCO₃(s) ⇌ CaO(s) + CO₂(g).', 'Kc = [CO₂].
Pure solids and pure liquids are left out of K: their activity is 1 because their concentration is fixed by their density. Likewise Kp = P(CO₂), so at a given temperature the CO₂ pressure is fixed no matter how much solid is present.', '[CO2]', array['Kc=[CO2]', 'K=[CO2]']::text[]),
  ('chem-equilibrium/q-versus-k', 'chem-equilibrium', 1, 'A reaction mixture has Q < K. In which direction does the reaction proceed to reach equilibrium?', 'Forward (to the right), forming more products until Q rises to equal K.
Q has the same form as K but uses the current concentrations. If Q > K, the reaction runs in reverse (toward reactants); if Q = K, it is already at equilibrium.', null, '{}'::text[]),
  ('chem-equilibrium/le-chatelier-compression', 'chem-equilibrium', 2, 'N₂(g) + 3H₂(g) ⇌ 2NH₃(g) is at equilibrium. Which way does it shift when the container volume is decreased?', 'To the right, toward NH₃ (2 mol of gas vs 4 mol on the left).
Compression raises the pressure, and the system relieves it by forming fewer gas molecules. K stays the same. Adding an inert gas at constant volume causes no shift, since the partial pressures don''t change.', null, '{}'::text[]),
  ('chem-equilibrium/what-changes-k', 'chem-equilibrium', 3, 'Which kind of change alters the numerical value of an equilibrium constant K?', 'A change in temperature, and nothing else.
Changing concentrations, pressure or volume shifts the position (Q ≠ K) but leaves K alone; a catalyst speeds both directions equally and shifts nothing. Raising T lowers K for an exothermic reaction and raises it for an endothermic one.', 'temperature', array['T', 'temp', 'temperature change', 'change in temperature', 'changing temperature', 'changing the temperature', 'changing T']::text[]),
  ('chem-equilibrium/kp-kc-delta-n', 'chem-equilibrium', 4, 'In Kp = Kc(RT)^Δn, what is Δn for PCl₅(g) ⇌ PCl₃(g) + Cl₂(g)?', '+1.
Δn = (moles of gaseous products) − (moles of gaseous reactants) = 2 − 1. Use R = 0.08206 L·atm/(mol·K) and T in kelvin. If Δn = 0, as in H₂ + I₂ ⇌ 2HI, then Kp = Kc.', '1', array['+1', 'one']::text[]),
  ('chem-equilibrium/strong-acids-list', 'chem-equilibrium', 5, 'Name the six common strong acids.', 'HCl, HBr, HI, HNO₃, HClO₄, H₂SO₄ (first proton only).
They ionize essentially 100% in water, so for a monoprotic strong acid [H₃O⁺] equals the acid concentration. Trap: HF is a weak acid despite fluorine''s electronegativity; the H–F bond is very strong.', null, '{}'::text[]),
  ('chem-equilibrium/kw-at-25c', 'chem-equilibrium', 6, 'What is the value of Kw, the ion-product constant of water, at 25 °C?', '1.0×10⁻¹⁴.
Kw = [H₃O⁺][OH⁻]; in pure water both equal 1.0×10⁻⁷ M, so neutral pH is 7.00. Water''s autoionization is endothermic, so Kw grows with temperature: neutral pH at 50 °C is about 6.6, yet the water is still neutral.', '1.0x10^-14', array['1x10^-14', '1.0e-14', '1e-14', '1.0*10^-14', '1*10^-14', '10^-14']::text[]),
  ('chem-equilibrium/ph-from-hydroxide', 'chem-equilibrium', 7, 'At 25 °C a solution has [OH⁻] = 1.0×10⁻⁴ M. What is its pH?', '10.00.
pOH = −log(1.0×10⁻⁴) = 4.00, and pH + pOH = 14.00 at 25 °C. Equivalently, [H₃O⁺] = Kw/[OH⁻] = 1.0×10⁻¹⁰ M and pH = −log[H₃O⁺]. Trap: reporting 4.00, which is the pOH.', '10', array['10.0', '10.00']::text[]),
  ('chem-equilibrium/ka-kb-conjugate-pair', 'chem-equilibrium', 8, 'Acetic acid has Ka = 1.8×10⁻⁵. What is Kb for its conjugate base, acetate (CH₃COO⁻), at 25 °C?', '5.6×10⁻¹⁰.
For any conjugate acid–base pair, Ka × Kb = Kw = 1.0×10⁻¹⁴, so Kb = 1.0×10⁻¹⁴ ÷ 1.8×10⁻⁵. Equivalently pKa + pKb = 14.00. The stronger the acid, the weaker its conjugate base.', '5.6x10^-10', array['5.6e-10', '5.6*10^-10', '5.56x10^-10', '5.56e-10', '5.56*10^-10']::text[]),
  ('chem-equilibrium/lewis-acid-bf3', 'chem-equilibrium', 9, 'In the reaction BF₃ + NH₃ → F₃B–NH₃, which reactant acts as the Lewis acid?', 'BF₃.
A Lewis acid accepts an electron pair (here into boron''s empty 2p orbital); NH₃ donates its lone pair as the Lewis base. No H⁺ moves, so this isn''t a Brønsted–Lowry reaction (acid = proton donor, base = proton acceptor).', 'BF3', array['boron trifluoride']::text[]),
  ('chem-equilibrium/henderson-hasselbalch-buffer', 'chem-equilibrium', 10, 'A buffer is 0.20 M CH₃COO⁻ and 0.10 M CH₃COOH (pKa = 4.74). What is its pH?', '5.04.
Henderson–Hasselbalch: pH = pKa + log([A⁻]/[HA]) = 4.74 + log(2.0) = 4.74 + 0.30. More base than acid puts the pH above the pKa. Trap: flipping the ratio gives 4.44.', '5.04', array['5.041']::text[]),
  ('chem-equilibrium/buffer-added-acid', 'chem-equilibrium', 11, 'In an acetic acid/acetate buffer, which species reacts with added strong acid, and what does it form?', 'Acetate: CH₃COO⁻ + H₃O⁺ → CH₃COOH + H₂O.
Added OH⁻ is consumed by the weak acid instead: CH₃COOH + OH⁻ → CH₃COO⁻ + H₂O. Only the ratio [A⁻]/[HA] changes a little, so the pH barely moves. Buffers work best within pH = pKa ± 1.', null, '{}'::text[]),
  ('chem-equilibrium/half-equivalence-point', 'chem-equilibrium', 12, 'In a weak acid–strong base titration, what does the pH equal at the half-equivalence point?', 'The pKa of the weak acid.
Halfway to equivalence, half of the HA has become A⁻, so [HA] = [A⁻] and log(1) = 0 in Henderson–Hasselbalch. That''s how Ka is read from a titration curve. At the equivalence point itself the pH is above 7 (A⁻ is basic).', 'pKa', array['pKa of the acid', 'pKa of the weak acid', 'pKa of HA', 'pH=pKa']::text[]),
  ('chem-equilibrium/ksp-molar-solubility', 'chem-equilibrium', 13, 'For PbCl₂(s) ⇌ Pb²⁺ + 2Cl⁻, express Ksp in terms of the molar solubility s.', 'Ksp = 4s³.
Dissolving s mol/L gives [Pb²⁺] = s and [Cl⁻] = 2s, so Ksp = (s)(2s)² = 4s³. Trap: forgetting to square the 2s. Compare Ksp values directly only for salts with the same ion ratio.', '4s^3', array['4s3', 's(2s)^2', 'Ksp=4s^3']::text[]),
  ('chem-equilibrium/common-ion-effect', 'chem-equilibrium', 14, 'How does dissolving NaCl in the water change the molar solubility of AgCl, and why?', 'It decreases it (the common-ion effect).
Extra Cl⁻ pushes AgCl(s) ⇌ Ag⁺ + Cl⁻ to the left. Ksp itself doesn''t change. AgCl is thousands of times less soluble in 0.10 M NaCl than in pure water.', null, '{}'::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'chem-equilibrium' and id not in ('chem-equilibrium/k-expression-solids', 'chem-equilibrium/q-versus-k', 'chem-equilibrium/le-chatelier-compression', 'chem-equilibrium/what-changes-k', 'chem-equilibrium/kp-kc-delta-n', 'chem-equilibrium/strong-acids-list', 'chem-equilibrium/kw-at-25c', 'chem-equilibrium/ph-from-hydroxide', 'chem-equilibrium/ka-kb-conjugate-pair', 'chem-equilibrium/lewis-acid-bf3', 'chem-equilibrium/henderson-hasselbalch-buffer', 'chem-equilibrium/buffer-added-acid', 'chem-equilibrium/half-equivalence-point', 'chem-equilibrium/ksp-molar-solubility', 'chem-equilibrium/common-ion-effect');

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('chem-thermo-kinetics/specific-heat-water', 'chem-thermo-kinetics', 0, 'What is the specific heat capacity of liquid water, in J/(g·°C)?', '4.184 J/(g·°C), the same value per kelvin (1 cal/(g·°C)).
Use it in q = mcΔT: warming 50.0 g of water by 10.0 °C takes 50.0 × 4.184 × 10.0 = 2.09 kJ. Trap: using 4.184 for ice or steam, which are about half that.', '4.184', array['4.18']::text[]),
  ('chem-thermo-kinetics/calorimeter-sign', 'chem-thermo-kinetics', 1, 'During a reaction in a coffee-cup calorimeter, the water''s temperature rises. What is the sign of ΔH for the reaction?', 'Negative: the reaction is exothermic.
Heat released by the system is absorbed by the solution, so q(rxn) = −q(solution) = −mcΔT. An endothermic reaction (ΔH > 0) would make the solution colder. At constant pressure, ΔH = q.', null, '{}'::text[]),
  ('chem-thermo-kinetics/hess-law-manipulation', 'chem-thermo-kinetics', 2, 'A + B → C has ΔH = −100 kJ. What is ΔH for 2C → 2A + 2B?', '+200 kJ.
Hess''s law: enthalpy is a state function, so ΔH values add along any path. Reversing a reaction flips the sign of ΔH; multiplying its coefficients by n multiplies ΔH by n.', '+200', array['200', '+200 kJ', '200 kJ']::text[]),
  ('chem-thermo-kinetics/enthalpy-of-formation-calc', 'chem-thermo-kinetics', 3, 'ΔH°f (kJ/mol): CH₄(g) −74.6, CO₂(g) −393.5, H₂O(l) −285.8. What is ΔH° for CH₄ + 2O₂ → CO₂ + 2H₂O(l)?', '−890.5 kJ.
ΔH°rxn = ΣnΔH°f(products) − ΣnΔH°f(reactants) = [−393.5 + 2(−285.8)] − [−74.6 + 0]. O₂(g) is an element in its standard state, so its ΔH°f = 0. Traps: reactants minus products, or dropping the coefficient 2.', '-890.5', array['-890.5 kJ', '-890.5 kJ/mol', '-890', '-891']::text[]),
  ('chem-thermo-kinetics/entropy-sign-prediction', 'chem-thermo-kinetics', 4, 'Predict the sign of ΔS° for 2SO₂(g) + O₂(g) → 2SO₃(g).', 'Negative: 3 mol of gas become 2 mol.
Entropy increases with more moles of gas, solid → liquid → gas, higher temperature, larger volume, dissolving a solid, and more complex molecules. A change in moles of gas usually dominates.', null, '{}'::text[]),
  ('chem-thermo-kinetics/gibbs-four-cases', 'chem-thermo-kinetics', 5, 'ΔG = ΔH − TΔS. If ΔH < 0 and ΔS < 0, when is the process spontaneous?', 'Only at low temperatures (below T = ΔH/ΔS).
All four cases: ΔH−, ΔS+ → always; ΔH+, ΔS− → never; ΔH−, ΔS− → low T; ΔH+, ΔS+ → high T. Example: water freezing (ΔH < 0, ΔS < 0) is spontaneous only below 0 °C.', null, '{}'::text[]),
  ('chem-thermo-kinetics/delta-g-to-k', 'chem-thermo-kinetics', 6, 'At 298 K a reaction has ΔG° = −11.4 kJ/mol. Estimate K using ΔG° = −RT ln K.', 'K ≈ 100.
ln K = 11,400 ÷ (8.314 × 298) ≈ 4.6, and e^4.6 ≈ 100. Shortcut: at 298 K, every −5.7 kJ/mol multiplies K by 10. ΔG° < 0 ↔ K > 1. Use R = 8.314 J/(mol·K) here, not 0.08206.', '100', array['99', '99.4', '99.6', '~100', 'about 100', '1x10^2', '1.0x10^2', '10^2', '1e2']::text[]),
  ('chem-thermo-kinetics/faraday-constant', 'chem-thermo-kinetics', 7, 'What is the Faraday constant F, used in ΔG° = −nFE°, in coulombs per mole of electrons?', '96,485 C/mol e⁻ (≈ 96,500).
n = moles of electrons transferred, and 1 C·V = 1 J. Positive E° → negative ΔG° → spontaneous (galvanic) cell. Example: Zn/Cu cell, n = 2, E° = 1.10 V: ΔG° = −2 × 96,485 × 1.10 J ≈ −212 kJ.', '96485', array['96,485', '96500', '96,500', '9.65x10^4', '9.6485x10^4', '96485 C/mol']::text[]),
  ('chem-thermo-kinetics/rate-law-from-experiment', 'chem-thermo-kinetics', 8, '2NO(g) + 2H₂(g) → N₂(g) + 2H₂O(g) has rate = k[NO]²[H₂]. Why isn''t the exponent on H₂ equal to its coefficient, 2?', 'Rate laws are determined by experiment; overall coefficients give the orders only for a single elementary step.
This reaction occurs in several steps, and the slow step (with any steps before it) sets the orders. Find orders from data, e.g., the method of initial rates.', null, '{}'::text[]),
  ('chem-thermo-kinetics/initial-rates-order', 'chem-thermo-kinetics', 9, 'Holding [B] constant, doubling [A] makes the initial rate four times faster. What is the reaction order in A?', 'Second order.
Rate ratio = (concentration ratio)^order, so 2ⁿ = 4 and n = 2. Doubling [A] with no rate change → zero order; rate doubles → first order; rate ×8 → third order.', '2', array['second', 'second order', '2nd', '2nd order', 'two']::text[]),
  ('chem-thermo-kinetics/first-order-half-life', 'chem-thermo-kinetics', 10, 'A first-order reaction has k = 0.0693 min⁻¹. What is its half-life?', '10.0 min.
t½ = ln 2/k = 0.693/k, independent of the starting concentration: each half-life halves whatever is left (100% → 50% → 25% → 12.5%). Zero- and second-order half-lives do depend on [A]₀.', '10', array['10.0', '10 min', '10.0 min', '10 minutes']::text[]),
  ('chem-thermo-kinetics/first-order-linear-plot', 'chem-thermo-kinetics', 11, 'Which plot gives a straight line for a first-order reaction, and what is its slope?', 'ln[A] versus time, with slope = −k.
It comes from the integrated rate law ln[A]t = −kt + ln[A]₀. Compare: zero order → [A] vs t (slope −k); second order → 1/[A] vs t (slope +k).', null, '{}'::text[]),
  ('chem-thermo-kinetics/arrhenius-plot-slope', 'chem-thermo-kinetics', 12, 'Arrhenius plot: what is the slope of ln k versus 1/T?', '−Ea/R.
Taking ln of k = A·e^(−Ea/RT) gives ln k = −(Ea/R)(1/T) + ln A, a straight line. So Ea = −slope × 8.314 J/(mol·K). Two-point form: ln(k₂/k₁) = (Ea/R)(1/T₁ − 1/T₂).', '-Ea/R', array['-Ea/8.314', '-(Ea/R)']::text[]),
  ('chem-thermo-kinetics/rate-determining-step', 'chem-thermo-kinetics', 13, 'Mechanism: NO₂ + NO₂ → NO₃ + NO (slow), then NO₃ + CO → NO₂ + CO₂ (fast). What is the rate law?', 'Rate = k[NO₂]².
The slow, rate-determining step controls the overall rate, and for an elementary step the coefficients give the orders. CO reacts only after the slow step, so the reaction is zero order in CO. NO₃ is an intermediate.', null, '{}'::text[]),
  ('chem-thermo-kinetics/catalyst-activation-energy', 'chem-thermo-kinetics', 14, 'A catalyst speeds up a reaction by lowering what?', 'The activation energy (Ea).
It provides a different mechanism with a lower barrier, speeding the forward and reverse reactions equally. It doesn''t change ΔH, ΔG°, K or the equilibrium yield, and it isn''t consumed.', 'activation energy', array['Ea', 'energy of activation', 'activation barrier', 'activation energy barrier', 'energy barrier']::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'chem-thermo-kinetics' and id not in ('chem-thermo-kinetics/specific-heat-water', 'chem-thermo-kinetics/calorimeter-sign', 'chem-thermo-kinetics/hess-law-manipulation', 'chem-thermo-kinetics/enthalpy-of-formation-calc', 'chem-thermo-kinetics/entropy-sign-prediction', 'chem-thermo-kinetics/gibbs-four-cases', 'chem-thermo-kinetics/delta-g-to-k', 'chem-thermo-kinetics/faraday-constant', 'chem-thermo-kinetics/rate-law-from-experiment', 'chem-thermo-kinetics/initial-rates-order', 'chem-thermo-kinetics/first-order-half-life', 'chem-thermo-kinetics/first-order-linear-plot', 'chem-thermo-kinetics/arrhenius-plot-slope', 'chem-thermo-kinetics/rate-determining-step', 'chem-thermo-kinetics/catalyst-activation-energy');

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('chem-organic/functional-group-ester', 'chem-organic', 0, 'Which functional group is in CH₃CO₂CH₂CH₃?', 'Ester (RCO₂R′): a carbonyl carbon bonded to an O–R group.
Don''t confuse it with a carboxylic acid RCO₂H (O–H instead of O–R), ether R–O–R′ (no C=O), ketone RCOR′, aldehyde RCHO, or amide RCONR₂ (N on the carbonyl carbon; an amine has no C=O).', 'ester', array['esters']::text[]),
  ('chem-organic/degree-of-unsaturation', 'chem-organic', 1, 'How many degrees of unsaturation does C₅H₅N have?', '4.
DoU = (2C + 2 + N − H − X)/2 = (10 + 2 + 1 − 5)/2 = 4. Each ring or π bond counts 1 (a triple bond counts 2); ignore oxygen. Pyridine fits: one ring plus three π bonds.', '4', array['four']::text[]),
  ('chem-organic/acidity-resonance', 'chem-organic', 2, 'Why is a carboxylic acid (pKa ≈ 4–5) so much more acidic than an alcohol (pKa ≈ 16–18)?', 'Its conjugate base is resonance-stabilized: a carboxylate''s negative charge is shared equally by two O atoms, while an alkoxide''s charge sits on one O.
Other rough pKa values: phenol ≈ 10, terminal alkyne ≈ 25, alkane ≈ 50. The more stable the conjugate base, the stronger the acid.', null, '{}'::text[]),
  ('chem-organic/chirality-centers-count', 'chem-organic', 3, 'How many chirality centers does 3-methylhexane have?', '1 (C3).
C3 carries four different groups: H, CH₃, CH₂CH₃ and CH₂CH₂CH₃. Every other carbon is a CH₂ or CH₃ with at least two identical H''s. Trap: missing that ethyl and propyl count as different groups.', '1', array['one']::text[]),
  ('chem-organic/cip-priority-ranking', 'chem-organic', 4, 'Rank these substituents by CIP priority: –CH₂OH, –CH(CH₃)₂, –CH₂Br, –OH.', '–OH > –CH₂Br > –CH₂OH > –CH(CH₃)₂.
First compare the directly attached atoms (O beats C). For ties, compare the sets of atoms at the next position and stop at the first difference: {Br,H,H} > {O,H,H} > {C,C,H}. One heavy atom beats several lighter ones.', null, '{}'::text[]),
  ('chem-organic/diastereomer-relationship', 'chem-organic', 5, 'How are (2R,3R)-2,3-dibromopentane and (2S,3R)-2,3-dibromopentane related?', 'Diastereomers.
Only one of the two chirality centers differs. Enantiomers have every center inverted, e.g., (2R,3R) and (2S,3S), and are nonsuperimposable mirror images. Diastereomers are not mirror images and have different physical properties.', 'diastereomers', array['diastereomer', 'diastereoisomers', 'diastereoisomer']::text[]),
  ('chem-organic/meso-stereoisomer-count', 'chem-organic', 6, 'How many stereoisomers does 2,3-dibromobutane have?', '3, not 2² = 4.
(2R,3R) and (2S,3S) are a pair of enantiomers. (2R,3S) is meso: an internal mirror plane makes it achiral and identical to (2S,3R). Meso compounds have chirality centers but are optically inactive.', '3', array['three']::text[]),
  ('chem-organic/sn2-stereochemistry', 'chem-organic', 7, 'In an SN2 reaction, what happens to the configuration of the carbon that is attacked?', 'Inversion of configuration (Walden inversion).
The nucleophile attacks from the back side, 180° from the leaving group, in one concerted step. Example: (R)-2-bromobutane + CN⁻ → (S)-2-methylbutanenitrile. Careful: R/S flips only when the nucleophile ranks where the leaving group did.', 'inversion', array['inversion of configuration', 'Walden inversion', 'inversion of stereochemistry', 'inverted', 'inverts', 'it inverts', 'it is inverted']::text[]),
  ('chem-organic/sn2-rate-and-substrate', 'chem-organic', 8, 'SN2: what is the rate law, and how do methyl, 1°, 2° and 3° alkyl halides rank in reactivity?', 'Rate = k[RX][Nu⁻], second order overall. Methyl > 1° > 2° ≫ 3°; 3° essentially doesn''t react.
Bulky groups block the backside attack (steric hindrance). Doubling either the substrate or the nucleophile concentration doubles the rate.', null, '{}'::text[]),
  ('chem-organic/solvent-sn1-vs-sn2', 'chem-organic', 9, 'Which solvent type favors SN2, and which favors SN1?', 'SN2: polar aprotic (DMSO, DMF, acetone, acetonitrile). SN1: polar protic (water, alcohols).
Aprotic solvents can''t H-bond to an anionic nucleophile, leaving it ''naked'' and reactive. Protic solvents stabilize the carbocation and the leaving group by solvation, speeding ionization.', null, '{}'::text[]),
  ('chem-organic/sn1-racemization', 'chem-organic', 10, 'What is the stereochemical outcome when (R)-3-bromo-3-methylhexane undergoes SN1 solvolysis in water?', 'Racemization: a nearly 50:50 mix of R and S alcohols.
The leaving group departs first (rate = k[RX], unimolecular), giving a planar sp² carbocation that water attacks from either face. Often there''s a slight excess of inversion, since the departing Br⁻ briefly shields one face.', 'racemization', array['racemisation', 'racemic', 'racemic mixture', 'racemic product', 'racemate', 'racemized', 'racemised']::text[]),
  ('chem-organic/e2-anti-periplanar', 'chem-organic', 11, 'For E2 on a cyclohexane ring, what positions must the leaving group and the β-hydrogen occupy?', 'Both axial, on opposite faces (trans-diaxial), which makes them anti-periplanar (180°).
E2 is concerted, so the breaking C–H and C–X bonds must line up. If the leaving group sits equatorial, the ring must flip to put it axial before E2 can occur. E2 needs a strong base: rate = k[RX][base].', null, '{}'::text[]),
  ('chem-organic/zaitsev-vs-hofmann', 'chem-organic', 12, '2-Bromo-2-methylbutane + potassium tert-butoxide (a bulky base): what is the major alkene product?', '2-Methyl-1-butene, the less substituted (Hofmann) alkene.
The bulky base removes the most accessible H, on a CH₃ group. A small strong base such as NaOEt mainly gives the more substituted (Zaitsev) alkene, 2-methyl-2-butene.', '2-methyl-1-butene', array['2-methylbut-1-ene', '2 methyl 1 butene']::text[]),
  ('chem-organic/markovnikov-hbr', 'chem-organic', 13, 'Propene reacts with HBr (no peroxides present). What is the major product?', '2-Bromopropane.
Markovnikov: H⁺ adds to the CH₂ end (the carbon with more H''s) to give the more stable 2° carbocation, which Br⁻ then attacks. With peroxides (ROOR), HBr adds by a radical path, anti-Markovnikov, giving 1-bromopropane.', '2-bromopropane', array['isopropyl bromide', '2 bromopropane']::text[]),
  ('chem-organic/carbocation-rearrangement', 'chem-organic', 14, 'HBr adds to 3-methyl-1-butene. What is the major product?', '2-Bromo-2-methylbutane.
Protonation gives a 2° carbocation; a 1,2-hydride shift from the neighboring CH makes a more stable 3° carbocation, which Br⁻ traps. Stability: 3° > 2° > 1° > methyl (hyperconjugation, induction). Unrearranged 2-bromo-3-methylbutane is minor.', '2-bromo-2-methylbutane', array['2 bromo 2 methylbutane']::text[]),
  ('chem-organic/hydroboration-oxidation', 'chem-organic', 15, 'Propene is treated with (1) BH₃·THF, then (2) H₂O₂, NaOH. What is the major product?', '1-Propanol (anti-Markovnikov OH).
Boron adds to the less substituted carbon and H to the more substituted one in a concerted syn addition, so no carbocation forms and nothing rearranges. Oxidation swaps B for OH with retention. Acid-catalyzed hydration instead gives 2-propanol.', '1-propanol', array['propan-1-ol', '1 propanol', 'n-propanol', 'propyl alcohol', 'n-propyl alcohol']::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'chem-organic' and id not in ('chem-organic/functional-group-ester', 'chem-organic/degree-of-unsaturation', 'chem-organic/acidity-resonance', 'chem-organic/chirality-centers-count', 'chem-organic/cip-priority-ranking', 'chem-organic/diastereomer-relationship', 'chem-organic/meso-stereoisomer-count', 'chem-organic/sn2-stereochemistry', 'chem-organic/sn2-rate-and-substrate', 'chem-organic/solvent-sn1-vs-sn2', 'chem-organic/sn1-racemization', 'chem-organic/e2-anti-periplanar', 'chem-organic/zaitsev-vs-hofmann', 'chem-organic/markovnikov-hbr', 'chem-organic/carbocation-rearrangement', 'chem-organic/hydroboration-oxidation');

