-- Physics
insert into public.packs (id, category_id, title, course, description, position) values
  ('phys-kinematics', 'physics', 'Kinematics & Newton''s Laws', 'Physics I: Mechanics', 'Constant-acceleration equations, free fall, projectiles, relative velocity, Newton''s laws, friction, inclines, Atwood machines, circular motion and drag.', 0),
  ('phys-energy-momentum', 'physics', 'Energy, Momentum & Rotation', 'Physics I: Mechanics', 'Work, energy conservation, power, impulse, collisions, torque, moments of inertia, rolling, angular momentum, gravitation, escape speed and SHM periods.', 1),
  ('phys-em', 'physics', 'Electricity & Magnetism', 'Physics II: E&M', 'Coulomb''s and Gauss''s laws, conductors, potential, capacitors and dielectrics, resistivity, magnetic forces, wire and solenoid fields, Lenz''s law, motional emf.', 2),
  ('phys-waves-modern', 'physics', 'Waves, Optics & Modern Physics', 'Physics II', 'Sound and standing waves, decibels, Doppler, refraction and critical angle, thin lenses, double slit, time dilation, photons, photoelectric effect and decay.', 3)
on conflict (id) do update set category_id = excluded.category_id, title = excluded.title, course = excluded.course, description = excluded.description, position = excluded.position;

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('phys-kinematics/constant-accel-no-time', 'phys-kinematics', 0, 'With constant acceleration, which kinematic equation relates v, v₀, a and displacement Δx without involving time?', 'v² = v₀² + 2aΔx
Use it when time is neither given nor asked for. Like every constant-acceleration equation, it fails when a varies (e.g., with air drag).', null, '{}'::text[]),
  ('phys-kinematics/free-fall-acceleration', 'phys-kinematics', 1, 'What is the standard magnitude of the free-fall acceleration g near Earth''s surface, in SI units?', 'g = 9.81 m/s², directed downward.
It''s the same for every object, whatever its mass, when air resistance is negligible. With up as positive, a = −g for the whole flight, rising or falling.', '9.81 m/s^2', array['9.81', '9.8', '9.8 m/s^2', '9.81 m/s2', '9.8 m/s2', '9.81 N/kg', '9.8 N/kg', '9.80665', '9.807', '9.81 m/s/s', '9.81 m s^-2']::text[]),
  ('phys-kinematics/top-of-vertical-throw', 'phys-kinematics', 2, 'A ball is thrown straight up. At its highest point, what are its velocity and its acceleration? (Neglect air resistance.)', 'Velocity 0; acceleration still g = 9.8 m/s² downward.
Classic trap: zero velocity doesn''t mean zero acceleration. The acceleration is the same at every instant of the flight; if it were 0 at the top, the ball would hover there.', null, '{}'::text[]),
  ('phys-kinematics/projectile-horizontal-velocity', 'phys-kinematics', 3, 'In projectile motion with no air resistance, how does the horizontal component of the velocity change during the flight?', 'It doesn''t: vₓ = v₀ cos θ stays constant (θ = launch angle).
Gravity acts only vertically (aₓ = 0, a_y = −g). So at the peak the velocity isn''t zero; it equals v₀ cos θ, pointing horizontally.', null, '{}'::text[]),
  ('phys-kinematics/projectile-time-of-flight', 'phys-kinematics', 4, 'A ball is launched from level ground at 20 m/s, 30° above the horizontal. How long is it in the air? (g = 9.8 m/s², no air resistance)', '≈ 2.0 s (2.04 s).
T = 2v₀ sin θ / g = 2(20)(0.50)/9.8. Only vertical motion sets the time: the 10 m/s vertical velocity reaches zero after 1.02 s, and the fall takes as long. Valid only for landing at launch height.', '2.04 s', array['2.04', '2.0 s', '2.0', '2 s', '2', '2.04 seconds', '2.0 seconds', '2 seconds', '2.04 sec']::text[]),
  ('phys-kinematics/complementary-launch-angles', 'phys-kinematics', 5, 'On level ground (no air resistance), a projectile launched at 30° has range R. What other launch angle at the same speed also gives R?', '60°.
R = v₀² sin 2θ / g, and sin 60° = sin 120°, so complementary angles (θ and 90° − θ) give equal ranges. The maximum range comes at 45°, where sin 2θ = 1.', '60', array['60 degrees', '60 degree', '60 deg', '60°', 'pi/3']::text[]),
  ('phys-kinematics/river-crossing-relative-velocity', 'phys-kinematics', 6, 'A boat points straight across a river at 3.0 m/s relative to the water; the current is 4.0 m/s. What is its speed relative to the shore?', '5.0 m/s.
Velocities add as vectors: v_boat/shore = v_boat/water + v_water/shore. The parts are perpendicular, so √(3.0² + 4.0²) = 5.0 m/s. The current carries it downstream, but the crossing time is still width ÷ 3.0 m/s.', '5 m/s', array['5', '5.0 m/s', '5.0', '5 meters per second']::text[]),
  ('phys-kinematics/net-force-constant-velocity', 'phys-kinematics', 7, 'A hockey puck slides across frictionless ice at constant velocity. What is the net force on it?', 'Zero.
Newton''s first law: constant velocity (a = 0) means ΣF = 0. Trap: no force is needed to keep an object moving; a net force changes its velocity. (Valid in inertial reference frames.)', '0', array['zero', '0 N', '0 newtons', '0 newton', 'zero newtons', 'no net force', 'none']::text[]),
  ('phys-kinematics/third-law-pairs-dont-cancel', 'phys-kinematics', 8, 'Newton''s third-law force pairs are equal in magnitude and opposite in direction. Why don''t they cancel each other out?', 'They act on different bodies, and only forces on the same body add up to its net force.
A pair is always the same type of force (e.g., both gravitational). A book''s weight and the table''s normal force on it both act on the book, so they are NOT a third-law pair.', null, '{}'::text[]),
  ('phys-kinematics/elevator-apparent-weight', 'phys-kinematics', 9, 'A 60 kg person stands on a scale in an elevator accelerating upward at 2.0 m/s². What does the scale read? (g = 9.8 m/s²)', '708 N (≈ 710 N), more than mg = 588 N.
With up positive, N − mg = ma, so N = m(g + a). Only the acceleration matters, not the direction of motion: moving down while slowing at 2.0 m/s² gives the same reading. In free fall (a = −g) the scale reads 0.', '708 N', array['708', '710 N', '710', '708 newtons', '708 newton']::text[]),
  ('phys-kinematics/incline-gravity-component', 'phys-kinematics', 10, 'A block sits on a ramp inclined at angle θ above the horizontal. What is the component of its weight parallel to the ramp?', 'mg sin θ, pointing down the slope.
The perpendicular component is mg cos θ, balanced by the normal force (N = mg cos θ if nothing else pushes perpendicular). Check the limits: θ = 0 gives no downslope pull; θ = 90° gives all of mg.', 'mg sin(theta)', array['mg sin theta', 'W sin(theta)', 'W sin theta']::text[]),
  ('phys-kinematics/static-friction-not-max', 'phys-kinematics', 11, 'A crate on a floor has μ_s = 0.50 and normal force 100 N. You push it horizontally with 30 N and it stays put. What is the friction force?', '30 N, opposing your push.
Static friction is only as large as needed, up to f_s,max = μ_s N = 50 N. Trap: μ_s N is the maximum, not the actual value. Once the crate slides, kinetic friction f_k = μ_k N takes over (usually μ_k < μ_s).', '30 N', array['30', '30 newtons', '30 newton']::text[]),
  ('phys-kinematics/atwood-acceleration', 'phys-kinematics', 12, 'In an ideal Atwood machine with masses m₁ > m₂ (massless string, frictionless massless pulley), what is the acceleration''s magnitude?', 'a = (m₁ − m₂)g / (m₁ + m₂)
The net driving force (m₁ − m₂)g accelerates the total mass m₁ + m₂. The tension T = 2m₁m₂g/(m₁ + m₂) lies between m₂g and m₁g; it is not simply the heavier weight.', '(m1-m2)g/(m1+m2)', array['g(m1-m2)/(m1+m2)', '(m1-m2)/(m1+m2)*g', '((m1-m2)/(m1+m2))g']::text[]),
  ('phys-kinematics/centripetal-acceleration', 'phys-kinematics', 13, 'An object moves at constant speed v around a circle of radius r. What is the magnitude of its acceleration?', 'a = v²/r, directed toward the center.
The speed is constant but the velocity keeps changing direction, so the object accelerates. Equivalent form: ω²r. Example: 10 m/s on a 5.0 m radius gives 20 m/s².', 'v^2/r', array['(v^2)/r', 'omega^2 r', 'w^2 r', 'ω^2 r']::text[]),
  ('phys-kinematics/flat-curve-friction', 'phys-kinematics', 14, 'A car rounds a flat, unbanked curve at constant speed. Which force provides the centripetal force?', 'Static friction from the road on the tires, pointing toward the center of the curve.
It''s static because the tires don''t slide sideways. Centripetal force is never an extra force on a free-body diagram; it''s the name for the net inward force. Top speed: v_max = √(μ_s g r).', null, '{}'::text[]),
  ('phys-kinematics/terminal-speed', 'phys-kinematics', 15, 'An object of mass m falls through air with drag force D = ½CρAv². What is its terminal speed?', 'v_t = √(2mg / (CρA))
At terminal speed, drag balances weight (½CρAv_t² = mg), so the net force and acceleration are zero. A heavier object of the same size and shape falls faster; in a vacuum there''s no terminal speed.', null, '{}'::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'phys-kinematics' and id not in ('phys-kinematics/constant-accel-no-time', 'phys-kinematics/free-fall-acceleration', 'phys-kinematics/top-of-vertical-throw', 'phys-kinematics/projectile-horizontal-velocity', 'phys-kinematics/projectile-time-of-flight', 'phys-kinematics/complementary-launch-angles', 'phys-kinematics/river-crossing-relative-velocity', 'phys-kinematics/net-force-constant-velocity', 'phys-kinematics/third-law-pairs-dont-cancel', 'phys-kinematics/elevator-apparent-weight', 'phys-kinematics/incline-gravity-component', 'phys-kinematics/static-friction-not-max', 'phys-kinematics/atwood-acceleration', 'phys-kinematics/centripetal-acceleration', 'phys-kinematics/flat-curve-friction', 'phys-kinematics/terminal-speed');

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('phys-energy-momentum/work-at-an-angle', 'phys-energy-momentum', 0, 'A 50 N force pulls a sled 10 m across level ground, with the force directed 60° above the horizontal. How much work does the force do?', '250 J.
W = Fd cos θ = (50 N)(10 m)(cos 60°). Only the force component along the displacement does work; a force perpendicular to the motion, like the normal force here, does zero work.', '250 J', array['250', '250 joules', '250 joule', '250 N*m']::text[]),
  ('phys-energy-momentum/braking-distance-scaling', 'phys-energy-momentum', 1, 'With the same constant braking force, by what factor does a car''s stopping distance change if its initial speed doubles?', '4× (it quadruples).
Work–energy theorem: W_net = ΔK, so f·d = ½mv² and d ∝ v². Doubling v quadruples the kinetic energy that friction must remove.', '4', array['4x', 'x4', 'four', '4 times', 'four times', 'quadruples', 'quadruple', 'quadrupled', 'factor of 4']::text[]),
  ('phys-energy-momentum/spring-potential-energy', 'phys-energy-momentum', 2, 'An ideal spring with k = 200 N/m is stretched 0.10 m from its relaxed length. How much elastic potential energy does it store?', '1.0 J.
U = ½kx² = ½(200 N/m)(0.10 m)². Common mistakes: using kx (that''s the 20 N force) or dropping the ½. Doubling the stretch quadruples the energy.', '1 J', array['1', '1.0 J', '1.0', '1 joule', '1 joules', '1.0 joules']::text[]),
  ('phys-energy-momentum/frictionless-ramp-speed', 'phys-energy-momentum', 3, 'A block slides from rest down a frictionless ramp, dropping a vertical height h. What is its speed at the bottom?', 'v = √(2gh), independent of the mass and of the ramp''s shape.
Only gravity does work (the normal force is perpendicular to the motion), so mechanical energy is conserved: mgh = ½mv². With friction, some energy becomes thermal and v is smaller.', 'sqrt(2gh)', array['(2gh)^0.5', '(2gh)^(1/2)', 'sqrt 2gh']::text[]),
  ('phys-energy-momentum/power-force-velocity', 'phys-energy-momentum', 4, 'A winch pulls a load at a constant 2.0 m/s using a 500 N force along the direction of motion. What power does it deliver?', '1000 W (1.0 kW).
P = dW/dt = Fv = (500 N)(2.0 m/s). If the force is at angle θ to the velocity, P = Fv cos θ. For scale, 1 hp ≈ 746 W.', '1000 W', array['1000', '1,000 W', '1,000', '1 kW', '1.0 kW', '1000 watts', '1000 watt', '1 kilowatt', '1e3 W']::text[]),
  ('phys-energy-momentum/impulse-on-bounce', 'phys-energy-momentum', 5, 'A 0.15 kg ball hits a wall at 20 m/s and rebounds straight back at 20 m/s. What is the magnitude of the impulse on the ball?', '6.0 N·s (= 6.0 kg·m/s).
J = Δp = m(v_f − v_i) = (0.15 kg)(20 − (−20)) m/s. Trap: the velocity reverses, so Δv = 40 m/s, not 0. A bounce takes twice the impulse of just stopping.', '6 N*s', array['6', '6.0', '6.0 N*s', '6 kg*m/s', '6.0 kg*m/s', '6 N-s']::text[]),
  ('phys-energy-momentum/perfectly-inelastic-collision', 'phys-energy-momentum', 6, 'A 3.0 kg cart moving at 4.0 m/s hits and sticks to a 1.0 kg cart at rest on a frictionless track. What is their speed afterward?', '3.0 m/s.
Momentum is conserved (no net external horizontal force): (3.0)(4.0) = (4.0)v. Kinetic energy is not: it falls from 24 J to 18 J. Sticking together (perfectly inelastic) loses the most K that momentum conservation allows.', '3 m/s', array['3', '3.0 m/s', '3.0']::text[]),
  ('phys-energy-momentum/elastic-collision-equal-masses', 'phys-energy-momentum', 7, 'In a head-on elastic collision, a moving ball strikes an identical ball at rest. What are their velocities just afterward?', 'The first ball stops; the second moves off with the first ball''s original velocity.
Elastic means momentum and kinetic energy are both conserved, and for equal masses only this swap satisfies both. In an inelastic collision only momentum is conserved.', null, '{}'::text[]),
  ('phys-energy-momentum/torque-on-wrench', 'phys-energy-momentum', 8, 'A 20 N force is applied at the end of a 0.50 m wrench, at 30° to the handle. What torque does it exert about the bolt?', '5.0 N·m.
τ = rF sin θ = (0.50 m)(20 N)(sin 30°), where θ is the angle between r (axis to point of application) and F. Pushing perpendicular to the handle maximizes τ; pushing along it gives zero.', '5 N*m', array['5', '5.0', '5.0 N*m', '5 m*N', '5 newton meters', '5 newton-meters', '5 N-m']::text[]),
  ('phys-energy-momentum/parallel-axis-rod', 'phys-energy-momentum', 9, 'What is the moment of inertia of a thin uniform rod of mass M and length L about a perpendicular axis through one end?', 'I = (1/3)ML².
Parallel-axis theorem: I = I_cm + Md² = (1/12)ML² + M(L/2)² = (1/3)ML². Of all parallel axes, the one through the center of mass gives the smallest I.', null, '{}'::text[]),
  ('phys-energy-momentum/rolling-race', 'phys-energy-momentum', 10, 'A hoop, a solid disk and a solid sphere roll without slipping from rest down the same incline. Which reaches the bottom first?', 'The solid sphere, then the disk, then the hoop.
Rolling without slipping (v = ωR) gives Mgh = ½Mv²(1 + I/MR²), with I/MR² = 2/5 (sphere), 1/2 (disk), 1 (hoop). Less energy tied up in rotation means faster translation. Mass and radius cancel.', null, '{}'::text[]),
  ('phys-energy-momentum/skater-spin-up', 'phys-energy-momentum', 11, 'A spinning skater pulls her arms in, halving her moment of inertia. What happens to her angular speed? (Ignore friction.)', 'It doubles.
No external torque, so L = Iω is conserved: I₁ω₁ = (I₁/2)ω₂ gives ω₂ = 2ω₁. Her rotational KE (L²/2I) also doubles; the extra energy comes from the work her muscles do pulling her arms in.', null, '{}'::text[]),
  ('phys-energy-momentum/gravity-inverse-square', 'phys-energy-momentum', 12, 'Two masses attract gravitationally. If the distance between their centers triples, the force becomes what fraction of its original value?', '1/9.
Newton''s law of gravitation: F = Gm₁m₂/r², with G = 6.67×10⁻¹¹ N·m²/kg². Tripling r divides F by 3² = 9. Measure r between centers, not between surfaces.', '1/9', array['one ninth', 'one-ninth', 'ninth', '1/9th', '0.111', '0.11']::text[]),
  ('phys-energy-momentum/escape-speed', 'phys-energy-momentum', 13, 'What is the escape speed from the surface of a planet of mass M and radius R? (Ignore air resistance.)', 'v_esc = √(2GM/R), about 11.2 km/s for Earth.
Set the total energy to zero: ½mv² − GMm/R = 0. It doesn''t depend on the escaping object''s mass or launch direction. It''s √2 times the speed of a circular orbit at that radius.', 'sqrt(2GM/R)', array['(2GM/R)^0.5', '(2GM/R)^(1/2)', 'sqrt 2GM/R', 'sqrt(2gR)']::text[]),
  ('phys-energy-momentum/mass-spring-period', 'phys-energy-momentum', 14, 'What is the period of an ideal mass–spring oscillator with mass m and spring constant k?', 'T = 2π√(m/k)
It doesn''t depend on the amplitude, or on g: hanging vertically gives the same period. Angular frequency ω = √(k/m). Quadrupling the mass doubles the period.', '2*pi*sqrt(m/k)', array['2pi(m/k)^0.5', '2pi(m/k)^(1/2)', '2pi sqrt m/k']::text[]),
  ('phys-energy-momentum/pendulum-period', 'phys-energy-momentum', 15, 'What is the period of a simple pendulum of length L swinging with small amplitude?', 'T = 2π√(L/g)
Valid for small angles (sin θ ≈ θ, roughly under 15°). It''s independent of the bob''s mass and, to this approximation, of the amplitude. Quadrupling L doubles T; on the Moon (smaller g) it swings more slowly.', null, '{}'::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'phys-energy-momentum' and id not in ('phys-energy-momentum/work-at-an-angle', 'phys-energy-momentum/braking-distance-scaling', 'phys-energy-momentum/spring-potential-energy', 'phys-energy-momentum/frictionless-ramp-speed', 'phys-energy-momentum/power-force-velocity', 'phys-energy-momentum/impulse-on-bounce', 'phys-energy-momentum/perfectly-inelastic-collision', 'phys-energy-momentum/elastic-collision-equal-masses', 'phys-energy-momentum/torque-on-wrench', 'phys-energy-momentum/parallel-axis-rod', 'phys-energy-momentum/rolling-race', 'phys-energy-momentum/skater-spin-up', 'phys-energy-momentum/gravity-inverse-square', 'phys-energy-momentum/escape-speed', 'phys-energy-momentum/mass-spring-period', 'phys-energy-momentum/pendulum-period');

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('phys-em/coulomb-force-two-charges', 'phys-em', 0, 'Two +1.0 μC point charges are 0.10 m apart. What is the magnitude of the electric force between them?', '0.90 N, repulsive.
F = k|q₁q₂|/r² = (8.99×10⁹ N·m²/C²)(1.0×10⁻⁶ C)²/(0.10 m)² ≈ 0.899 N, with k = 1/(4πε₀). Traps: convert μC to C, and square the distance.', '0.9 N', array['0.9', '0.90 N', '0.90', '0.899 N', '0.899', '.9 N', '.9', '0.9 newtons']::text[]),
  ('phys-em/gauss-law-flux', 'phys-em', 1, 'According to Gauss''s law, the net electric flux through any closed surface equals what?', 'Φ_E = ∮E·dA = q_enc/ε₀: the net enclosed charge divided by ε₀ = 8.85×10⁻¹² C²/(N·m²).
Charges outside contribute zero net flux, and the surface''s shape doesn''t matter. It''s a quick route to E only with high symmetry (spherical, cylindrical, planar).', null, '{}'::text[]),
  ('phys-em/conductor-interior-field', 'phys-em', 2, 'What is the electric field inside the material of a conductor in electrostatic equilibrium?', 'Zero.
If it weren''t, the free charges would move until it was. So any excess charge sits on the surface, the whole conductor is at one potential, and just outside, E is perpendicular to the surface with magnitude σ/ε₀.', '0', array['zero', '0 N/C', '0 V/m']::text[]),
  ('phys-em/point-charge-potential', 'phys-em', 3, 'Taking V = 0 at infinity, what is the electric potential at distance r from a point charge q?', 'V = kq/r, a scalar that falls off as 1/r and is negative for negative q.
Contrast the field E = kq/r², a vector. They''re linked by E = −dV/dr, so E points toward decreasing V. The potentials of several charges add as plain numbers.', 'kq/r', array['q/(4*pi*epsilon0*r)', 'q/(4pi e0 r)', 'q/(4πε0r)']::text[]),
  ('phys-em/electron-volt-energy', 'phys-em', 4, 'An electron starts from rest and is accelerated through a potential difference of 100 V. How much kinetic energy does it gain?', '100 eV, which is 1.60×10⁻¹⁷ J.
ΔK = −ΔU = −qΔV; with q = −e, the electron gains energy moving toward higher potential. 1 eV = 1.602×10⁻¹⁹ J, the energy a charge e gains through 1 V.', '100 eV', array['100', '100 electron volts', '100 electron-volts', '1.6e-17 J', '1.60e-17 J', '1.6e-17', '1.6x10^-17 J', '1.6*10^-17 J']::text[]),
  ('phys-em/parallel-plate-capacitance', 'phys-em', 5, 'What is the capacitance of an ideal parallel-plate capacitor with plate area A, plate separation d and vacuum between the plates?', 'C = ε₀A/d
It depends only on geometry, not on the charge or voltage. Halving d or doubling A doubles C; filling the gap with a dielectric multiplies C by κ.', null, '{}'::text[]),
  ('phys-em/capacitors-in-series', 'phys-em', 6, 'Two 6.0 μF capacitors are connected in series. What is their equivalent capacitance?', '3.0 μF.
Series: 1/C_eq = 1/C₁ + 1/C₂, so C_eq is smaller than either (the reverse of resistors). In parallel they''d add to 12 μF. Capacitors in series all carry the same charge.', '3 uF', array['3', '3.0', '3.0 uF', '3 μF', '3.0 μF', '3 microfarads', '3 microfarad', '3e-6 F']::text[]),
  ('phys-em/capacitor-stored-energy', 'phys-em', 7, 'How much energy is stored in a capacitor of capacitance C charged to a potential difference V?', 'U = ½CV² (equivalently Q²/2C or ½QV).
The battery does work QV, but only half is stored; the rest is dissipated in the circuit while charging. The energy resides in the field, with density u = ½ε₀E².', null, '{}'::text[]),
  ('phys-em/dielectric-isolated-capacitor', 'phys-em', 8, 'A charged capacitor is disconnected from its battery; then a κ = 3 dielectric fills the gap. Its new voltage is what fraction of the old?', '1/3.
Isolated means Q is fixed, while C rises to κC₀ = 3C₀; so V = Q/C drops 3×, and so do E and U = Q²/2C. If the battery stays connected instead, V is fixed and Q and U triple.', '1/3', array['one third', 'one-third', 'third', '0.33', '0.333', 'divided by 3', 'factor of 1/3', '1/3rd']::text[]),
  ('phys-em/stretched-wire-resistance', 'phys-em', 9, 'A metal wire is drawn out to twice its original length at constant volume. By what factor does its resistance change?', 'It quadruples (4×).
R = ρL/A. At constant volume, doubling L halves A, so R = ρ(2L)/(A/2) = 4ρL/A. Resistivity ρ (in Ω·m) depends on the material and temperature, not the shape.', '4', array['4x', 'x4', 'four', '4 times', 'four times', 'quadruples', 'quadruple', 'quadrupled', 'factor of 4']::text[]),
  ('phys-em/magnetic-force-no-work', 'phys-em', 10, 'Why can a static magnetic field never change the speed of a moving charged particle?', 'F = qv × B is always perpendicular to v, so the magnetic force does no work (F·v = 0); it only changes the direction of motion.
A charge at rest, or one moving parallel to B, feels no magnetic force at all.', null, '{}'::text[]),
  ('phys-em/cyclotron-radius', 'phys-em', 11, 'A particle with charge q and mass m moves at speed v perpendicular to a uniform magnetic field B. What is the radius of its path?', 'r = mv/(|q|B)
The magnetic force supplies the centripetal force: |q|vB = mv²/r. The period T = 2πm/(|q|B) doesn''t depend on speed, the principle behind the cyclotron. Faster or heavier particles make bigger circles.', 'mv/(qB)', array['mv/qB', 'mv/(Bq)', 'mv/Bq', 'mv/(|q|B)', 'p/(qB)', 'p/qB']::text[]),
  ('phys-em/long-wire-field', 'phys-em', 12, 'What is the magnitude of the magnetic field at distance r from a long, straight wire carrying current I?', 'B = μ₀I/(2πr), with μ₀ = 4π×10⁻⁷ T·m/A.
Ampère''s law (∮B·ds = μ₀I_enc) around a circle gives B(2πr) = μ₀I. The field lines circle the wire (right-hand rule: thumb along I, fingers curl with B), and B falls off as 1/r.', null, '{}'::text[]),
  ('phys-em/solenoid-field', 'phys-em', 13, 'What is the magnetic field inside a long, ideal solenoid with n turns per unit length carrying current I?', 'B = μ₀nI, uniform and along the axis.
n = N/L is turns per meter. B doesn''t depend on the radius or on where you are inside; outside an ideal solenoid B ≈ 0. It follows from Ampère''s law with a rectangular loop.', 'mu0*n*I', array['u0nI', 'μ0nI', 'mu_0nI', 'mu0NI/L', 'μ0NI/L']::text[]),
  ('phys-em/lenz-law-approaching-magnet', 'phys-em', 14, 'The north pole of a bar magnet is pushed toward a wire loop. Seen from the magnet''s side, which way does the induced current circulate?', 'Counterclockwise.
Faraday: ε = −dΦ_B/dt. The flux through the loop (pointing away from the magnet) is increasing, so by Lenz''s law the induced current makes a field pointing back toward the magnet. That face of the loop becomes a north pole and repels the magnet.', 'counterclockwise', array['counter-clockwise', 'anticlockwise', 'anti-clockwise', 'ccw']::text[]),
  ('phys-em/motional-emf', 'phys-em', 15, 'A 0.20 m rod moves at 5.0 m/s through a 0.50 T field, with B, the rod and v all mutually perpendicular. What emf is induced across it?', '0.50 V.
Motional emf ε = BLv = (0.50 T)(0.20 m)(5.0 m/s). If the rod slides on rails that close a circuit, the induced current feels a magnetic force opposing the motion (Lenz), so you must keep pushing to hold v constant.', '0.5 V', array['0.5', '0.50 V', '0.50', '.5 V', '.5', '0.5 volts', '0.5 volt']::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'phys-em' and id not in ('phys-em/coulomb-force-two-charges', 'phys-em/gauss-law-flux', 'phys-em/conductor-interior-field', 'phys-em/point-charge-potential', 'phys-em/electron-volt-energy', 'phys-em/parallel-plate-capacitance', 'phys-em/capacitors-in-series', 'phys-em/capacitor-stored-energy', 'phys-em/dielectric-isolated-capacitor', 'phys-em/stretched-wire-resistance', 'phys-em/magnetic-force-no-work', 'phys-em/cyclotron-radius', 'phys-em/long-wire-field', 'phys-em/solenoid-field', 'phys-em/lenz-law-approaching-magnet', 'phys-em/motional-emf');

insert into public.pack_cards (id, pack_id, position, title, body, answer, accepted_answers) values
  ('phys-waves-modern/sound-wavelength', 'phys-waves-modern', 0, 'What is the wavelength of a 343 Hz sound wave in air at 20 °C?', '1.00 m.
Sound travels at about 343 m/s in 20 °C air, and λ = v/f = (343 m/s)/(343 Hz). v = fλ holds for every wave: the medium sets the speed, the source sets the frequency.', '1 m', array['1', '1.0 m', '1.00 m', '1.0', '1.00', '1 meter', '1 metre', '100 cm']::text[]),
  ('phys-waves-modern/string-harmonic-wavelength', 'phys-waves-modern', 1, 'A string of length L is fixed at both ends. What is the wavelength of its nth harmonic?', 'λₙ = 2L/n (n = 1, 2, 3, ...), so fₙ = nv/(2L).
Both ends are nodes, so the string holds a whole number of half-wavelengths. The wave speed on a string is v = √(T/μ): tension over mass per unit length.', '2L/n', array['(2L)/n']::text[]),
  ('phys-waves-modern/closed-pipe-harmonics', 'phys-waves-modern', 2, 'A pipe is closed at one end and open at the other. Which harmonics of its fundamental frequency f₁ can it produce?', 'Only odd harmonics: f₁, 3f₁, 5f₁, ..., with f₁ = v/(4L).
The closed end is a displacement node and the open end an antinode, so the pipe fits an odd number of quarter-wavelengths. A pipe open at both ends has all harmonics, with f₁ = v/(2L).', null, '{}'::text[]),
  ('phys-waves-modern/decibel-intensity-ratio', 'phys-waves-modern', 3, 'A sound''s intensity increases by a factor of 100. By how much does its sound level rise, in decibels?', '20 dB.
β = (10 dB) log₁₀(I/I₀), with I₀ = 10⁻¹² W/m². Every factor of 10 in intensity adds 10 dB, so ×100 adds 20 dB. Doubling the intensity adds only about 3 dB.', '20 dB', array['20', '+20 dB', '+20', '20 decibels', '20 decibel']::text[]),
  ('phys-waves-modern/doppler-passing-siren', 'phys-waves-modern', 4, 'A siren approaches you at constant speed, passes you, then moves away. How does the pitch you hear compare with the emitted pitch?', 'Higher while it approaches, lower while it recedes, dropping as it passes.
f′ = f(v ± v_D)/(v ∓ v_S), with the upper signs for motion toward the other. Trap: the pitch doesn''t keep rising as it gets closer; that''s the loudness.', null, '{}'::text[]),
  ('phys-waves-modern/index-of-refraction', 'phys-waves-modern', 5, 'Light travels at 2.00×10⁸ m/s in a certain glass. What is the glass''s index of refraction?', 'n = 1.50.
n = c/v = (3.00×10⁸ m/s)/(2.00×10⁸ m/s). Vacuum has n = 1 and ordinary materials have n > 1. Entering the glass, the frequency stays the same while the wavelength shrinks to λ/n.', '1.5', array['1.50', '3/2']::text[]),
  ('phys-waves-modern/snell-refraction-angle', 'phys-waves-modern', 6, 'Light in air (n = 1.00) strikes glass (n = 1.50) at 30.0° from the normal. What is the angle of refraction?', '≈ 19.5° from the normal.
Snell''s law: n₁ sin θ₁ = n₂ sin θ₂, so sin θ₂ = (1.00)(0.500)/1.50 = 0.333. Light bends toward the normal entering a higher-n medium. Trap: measure angles from the normal, not the surface.', '19.5', array['19.5 degrees', '19.5 degree', '19.5 deg', '19.5°', '19.47', '19.47 degrees', '19', '19 degrees']::text[]),
  ('phys-waves-modern/critical-angle-glass-air', 'phys-waves-modern', 7, 'Light inside glass (n = 1.50) hits a glass–air boundary. What is the critical angle for total internal reflection?', '≈ 41.8°.
sin θc = n₂/n₁ = 1.00/1.50 = 0.667. Total internal reflection happens only going from higher n to lower n, at incidence angles greater than θc. Optical fibers rely on it.', '41.8', array['41.8 degrees', '41.8 degree', '41.8 deg', '41.8°', '41.81', '42', '42 degrees', '42°']::text[]),
  ('phys-waves-modern/thin-lens-image-distance', 'phys-waves-modern', 8, 'An object is 30 cm in front of a converging lens with focal length 10 cm. How far from the lens does the image form?', '15 cm, on the far side: real, inverted and half-size.
1/d_o + 1/d_i = 1/f gives 1/d_i = 1/10 − 1/30 = 1/15, and m = −d_i/d_o = −0.5. Signs: d_i > 0 means a real image, f < 0 for a diverging lens, m < 0 means inverted.', '15 cm', array['15', '+15 cm', '+15', '0.15 m', '15 centimeters', '15 centimetres', '15.0 cm']::text[]),
  ('phys-waves-modern/double-slit-bright-fringes', 'phys-waves-modern', 9, 'In Young''s double-slit experiment (slit separation d, wavelength λ), what condition gives a bright fringe at angle θ?', 'd sin θ = mλ, with m = 0, ±1, ±2, ...
The path difference from the two slits is a whole number of wavelengths. Dark fringes: d sin θ = (m + ½)λ. For small angles, fringe spacing is Δy = λL/d (L = slit-to-screen distance), so closer slits spread the fringes.', null, '{}'::text[]),
  ('phys-waves-modern/time-dilation', 'phys-waves-modern', 10, 'A spaceship''s clock moves at 0.60c relative to you. When 4.0 s pass on that clock, how much time passes for you?', '5.0 s.
Δt = γΔt₀ with γ = 1/√(1 − v²/c²) = 1/√(1 − 0.36) = 1.25. Moving clocks run slow; the proper time Δt₀ is measured by a clock at rest relative to the events (here, the ship''s clock).', '5 s', array['5', '5.0 s', '5.0', '5 seconds', '5.0 seconds', '5 sec']::text[]),
  ('phys-waves-modern/photon-energy', 'phys-waves-modern', 11, 'What is the energy of a single photon of wavelength 620 nm, in electron-volts?', '2.00 eV (≈ 3.20×10⁻¹⁹ J).
E = hf = hc/λ, and hc ≈ 1240 eV·nm, so E = 1240/620. Planck''s constant h = 6.626×10⁻³⁴ J·s. Shorter wavelength means more energy per photon: violet beats red.', '2 eV', array['2', '2.0 eV', '2.00 eV', '2.0', '2.00', '2 electron volts', '2 electron-volts', '3.2e-19 J']::text[]),
  ('phys-waves-modern/photoelectric-intensity', 'phys-waves-modern', 12, 'In the photoelectric effect, how does doubling the light''s intensity (same frequency) change the electrons'' maximum kinetic energy?', 'It doesn''t. K_max = hf − φ depends only on the light''s frequency and the metal''s work function φ.
Doubling intensity doubles the photon rate, so twice as many electrons (twice the current) are emitted. Below the threshold frequency f₀ = φ/h, none are emitted at any intensity.', null, '{}'::text[]),
  ('phys-waves-modern/de-broglie-wavelength', 'phys-waves-modern', 13, 'What is the de Broglie wavelength of a particle with momentum p?', 'λ = h/p = h/(mv) (nonrelativistic).
Faster or heavier means a shorter wavelength. A 0.15 kg ball at 40 m/s has λ ≈ 10⁻³⁴ m, far too small to observe; diffraction shows up only for tiny particles such as electrons and neutrons.', 'h/p', array['h/(mv)', 'h/mv']::text[]),
  ('phys-waves-modern/half-life-fraction', 'phys-waves-modern', 14, 'A radioactive sample has a half-life of 5.0 days. What fraction of the original nuclei remains undecayed after 15 days?', '1/8 (12.5%).
15 days is 3 half-lives, and (½)³ = 1/8. In general N = N₀e^(−λt), with decay constant λ = ln 2 / t½. Trap: after two half-lives a quarter remains, not zero.', '1/8', array['0.125', '12.5%', '12.5 percent', 'one eighth', 'one-eighth', 'eighth', '1/8th']::text[]),
  ('phys-waves-modern/alpha-decay-changes', 'phys-waves-modern', 15, 'In alpha decay, how do the parent nucleus''s atomic number Z and mass number A change?', 'Z decreases by 2 and A decreases by 4: the nucleus emits a helium-4 nucleus (2 protons + 2 neutrons), e.g., ²³⁸U → ²³⁴Th + α.
Compare β⁻ decay: Z increases by 1, A unchanged (a neutron becomes a proton). Gamma decay changes neither.', null, '{}'::text[])
on conflict (id) do update set pack_id = excluded.pack_id, position = excluded.position, title = excluded.title, body = excluded.body, answer = excluded.answer, accepted_answers = excluded.accepted_answers;
delete from public.pack_cards where pack_id = 'phys-waves-modern' and id not in ('phys-waves-modern/sound-wavelength', 'phys-waves-modern/string-harmonic-wavelength', 'phys-waves-modern/closed-pipe-harmonics', 'phys-waves-modern/decibel-intensity-ratio', 'phys-waves-modern/doppler-passing-siren', 'phys-waves-modern/index-of-refraction', 'phys-waves-modern/snell-refraction-angle', 'phys-waves-modern/critical-angle-glass-air', 'phys-waves-modern/thin-lens-image-distance', 'phys-waves-modern/double-slit-bright-fringes', 'phys-waves-modern/time-dilation', 'phys-waves-modern/photon-energy', 'phys-waves-modern/photoelectric-intensity', 'phys-waves-modern/de-broglie-wavelength', 'phys-waves-modern/half-life-fraction', 'phys-waves-modern/alpha-decay-changes');

